      "content": "/**\n * Knit · 宿主半边\n *\n * 两件事：\n *   1. 扫描会话工作区里的 Markdown，按 mtime 或**与当前对话的相关性**排序后吐给浏览器半边\n *   2. 按需返回单篇正文，供面板内联预览\n *\n * 为什么必须有宿主半边：\n *   - DSH 的 workspaceFiles Remote 协议里没有 mtime\n *     （WorkspaceFileStat.version 是 opaque token 从不解析，WorkspaceDirectoryEntry 只有 name/type/size），\n *     纯客户端做不出「按修改时间倒序」。\n *   - 会话事件（`session.snapshotEvents()`）只有宿主读得到，那正是相关性排序的输入。\n *\n * 零模型、零网络出口：只读本地文件与会话日志。\n */\nimport { createHash } from 'node:crypto'\nimport { readFile, readdir, stat } from 'node:fs/promises'\nimport { createReadStream, realpathSync, statSync } from 'node:fs'\nimport { dirname, join, relative, resolve, sep } from 'node:path'\nimport { homedir } from 'node:os'\nimport { extractKeywords, rankByRelevance, topicLabel } from './relevance.js'\nimport { registerKnitDocsTool } from './tool.js'\n// v0.12：引用关系。`links.js` **不反过来 import 本文件**（依赖由这里注入），所以没有环。\n// v0.22 修法 ①：这里多用了一个 `extractRefsWithLines` —— 它把「抽取引用」这件事\n// 从「每次装配上下文的消费者各抽一遍」提前到「读盘那一次抽一遍，结果进索引」。\nimport { buildLinkGraph, extractRefsWithLines, linksOf } from './links.js'\n// v0.21：关系事实表（谁提到谁）。**同步、零 I/O** —— 只吃记录上现成的 `refs` / `head`。\n// v0.22 修法 ①：`importsOf` 同样提前到读盘时执行，结果进索引的 `refs.imports`。\nimport { buildRelationFacts, importsOf } from './relations.js'\n// v0.25：对话里「工具产出」的图（在媒体档里显示）。它**是唯一读工作区之外**的地方，\n// 所以边界全在那个模块里写死：只认 sha256、只认本会话出现过的 id、只读那一个对象文件。\nimport {\n  createAttachmentStore, isAttachmentId, objectPath, attachmentsRoot, dropSaved, MAX_ATTACHMENT_BYTES,\n} from './attachments.js'\n// v0.21：上下文控制层（固定 / 排除）。**纯逻辑 + 可选持久化**：本文件负责把\n// `ctx.storage`（拿得到才有）递给它，它自己不 import 任何官方包。\nimport {\n  createControlRegistry, applyPinOverride, excludedSet, sharedControlRegistry,\n  CONTROL_ACTIONS,\n} from './control.js'\n// v0.22：增量上下文索引的持久层。**不参与排序、不缓存正文** —— 它只回答\n// 「这个文件的头部指纹和上次一样吗」。存储拿不到时它自己降级成空 Map。\nimport { sharedIndexStore, headHashOf, refsShapeOk } from './index-store.js'\n// v0.23：可选混合检索（Phase A）。**默认零调用** —— 没有配置、或要的是词法模式时，\n// 这一层连探测都不发（方案 §9.2 判据 1）。它只算「有界的语义候选数」，**不进三层、不改名次**\n// （那是 Phase B 的规则变更，见 `Knit-v0.23-方案-可选混合检索.md` §3 第 6/7/8 条与 §11）。\nimport {\n  createSemanticEngine, sharedSemanticStore, normalizeProviderConfig,\n} from './semantic.js'\n// v0.25：Git 变更关联检索。**只读、有界、默认关闭** —— `git.js` 只跑一条\n// `git status --porcelain=v1 -z`（argv 是数组，绝不走 shell；写动词一个都没有），\n// `changes.js` 把变更文件当种子去**已有的**关系事实表里取边，不发明关系。\nimport { createGitReader, MAX_REPORTED_FILES } from './git.js'\nimport { splitSeeds, ghostCandidates, projectChangeRelated, MAX_CHANGE_RELATED } from './changes.js'\n// v0.14：上下文装配。同样由这里注入依赖（`list` / `read`），保持纯函数可单测。\n// ⚠️ 这里**只 import `buildContext`**：Context Pack 的文本渲染只在 `tool.js` 的\n// `renderToolText()` 里发生（模型看到的是那段文本，不是结构化 JSON）。曾经多导出一个\n// `renderContextText` 却没人调用 —— 那是个会与 `tool.js` 漂移的第二渲染器，已删。\nimport { buildContext, sourceTypeOf } from './context.js'\n// v0.20：内容片段层（Deep Context Retrieval）。**纯函数、不读盘**，\n// 目录遍历与缓存全在本文件 —— 它只回答「这篇正文里哪几段相关」。\nimport { passageMatchesFor, passageTfOf, PASSAGE_WINDOW } from './passage.js'\n// v0.19：文件分类层。**所有「这个文件是什么、能不能预览/检索/进上下文」的判断都在这里**，\n// 本文件（以及 retrieval / preview / UI）不再自己看扩展名 —— 见 `classification.js` 的文件头。\nimport {\n  classifyFile, isContextKind, isPreviewKind,\n  KIND_DOCUMENT, KIND_CODE, KIND_IMAGE, KIND_VIDEO, KIND_GENERATED, KIND_IGNORED,\n  IMAGE_TYPES, VIDEO_TYPES,\n} from './classification.js'\n// v0.15：Context Feedback / Context Audit —— 「Context Pack 之后真的被用了吗」。\n// ⚠️ 只做三件确定性的事：从会话事件里抽**真实的 `read`**、把交出去的包记成 Snapshot、\n// 把两者接起来算 Usage。**不订阅 event bus、不落盘、不联网、不调模型、不改 Retrieval。**\nimport {\n  createStore, activateAudit, isAudited, ingestEvents, noteSnapshot, usageFor, getAuditSummary,\n  markBackfilled, isBackfilled,\n} from './feedback.js'\n\nexport const name = 'dsh-knit'\n\n/** 本插件占用的路由前缀。 */\nexport const ROUTE_PREFIX = '/knit'\n\n/* ── 扫描预算：宁可少列几条，也不能把宿主卡住 ───────────────── */\nconst MAX_DEPTH = 6\nconst MAX_DIRS = 500\nconst MAX_DOCS = 400\n/** 图片/视频等媒体产物的扫描上限（与文档分开计数，避免截图刷爆文档列表）。 */\nconst MAX_MEDIA = 400\n/**\n * 代码产物的扫描上限（v0.19）。\n *\n * ⚠️ 这个数字是**审计真实工作区之后定的**，不是拍的：\n * 拿 `DeepSeek Harness Native` 这一级真实工作区数过一遍，根下有 635 篇 Markdown、\n * 773 个代码文件（`.mjs` 270 / `.js` 173 / `.json` 122 / `.py` 105 / `.html` 74 /\n * `.yml` 13 / `.css` 10 / `.sh` 5），代码比文档多约 1.2 倍。\n *\n * 所以取 **300**（≈ 0.75 × `MAX_DOCS`）而不是和文档齐平 400：\n * 「支持代码」不该让代码把原有的 Markdown 上下文挤出去（需求 §15），\n * 同一批语料里代码的准入名额略小于文档，是这条要求最直接的落实。\n * 另外它在面板里也不与文档竞争 —— 文档档的语料只有 Markdown（见 `scan()`）。\n */\nconst MAX_CODE = 300\nconst SCAN_BUDGET_MS = 4000\nconst HEAD_BYTES = 16 * 1024\n/**\n * 代码文件参与扫描时读取的**头部**字节数（v0.19）。\n *\n * 比 Markdown 的 16KB 更小是**刻意的**：头部只服务于引用关系与摘要渲染，\n * 而真实项目里 `.ts` / `.js` 的数量可能非常高 —— 这是「bounded content read」\n * 那条要求（需求 §16）唯一的落地点。\n *\n * ⚠️ v0.20 之后它**不再**限制检索：参与打分的正文是 `MAX_BODY_BYTES` 那份，\n * 与本常量彻底解耦（见 `readCode()`）。\n */\nconst CODE_HEAD_BYTES = 8 * 1024\n/** 单次内联预览返回的正文上限（超出截断，面板只做预览不做全量阅读）。 */\nconst DOC_MAX_BYTES = 512 * 1024\n/**\n * 参与相关性打分的正文字节上限（v0.20）。\n *\n * v0.19 之前这里是「正文前 2500 个字符」，于是正文命中只可能发生在前 2500 字里 ——\n * 而真实案例里目标词出现在第 29 033 字（`CHANGELOG.md` 那条「不改窗口」的记录）。\n * v0.20 取消这个窗口：**整篇正文都参与打分**，剩下的只是内存兜底。\n *\n * 单位是**字节**而不是字符：它是一道内存闸门，按字节量才是诚实的\n * （中文文件因此拿到更少的字符数 —— 偏差方向是安全的那一侧）。\n */\nconst MAX_BODY_BYTES = 256 * 1024\n/** 解析结果缓存的条目上限（v0.20：缓存里现在留着整篇正文，必须封顶）。 */\nconst MAX_CACHE_ENTRIES = 1200\n/** 解析结果缓存里正文的总字节上限 —— 比条目数更硬的那道闸门。 */\nconst MAX_CACHE_BYTES = 24 * 1024 * 1024\n\n/** 相关性输入：最多回看几条消息、总字符上限。 */\nconst CONV_MAX_MESSAGES = 6\nconst CONV_MAX_CHARS = 6000\nconst CONV_MESSAGE_CHARS = 2000\n\n/**\n * `task` 字段（当前任务的**原文引用**）的长度上限。\n *\n * 右栏要显示它、agent 文本里也会带一行，所以太长的消息会把它变成一个正文块。\n * 截断是这里唯一允许的加工 —— 它不改语义，只是裁剪，超出部分用 `…` 标出。\n */\nconst TASK_MAX_CHARS = 80\n\n/**\n * 纯应答词表：这些不是任务，是「接着说」。\n *\n * `task` 要回答「现在这个任务是什么」，而「继续」「好的」回答不了这个问题 ——\n * 把它们当任务显示，比空着更糟（空着至少不撒谎）。判定前先按标点切成段，\n * 所以「好的，继续」也命中。\n */\nconst TASK_ACK = new Set([\n  '继续', '好的', '好', '嗯', '嗯嗯', '收到', '谢谢', '可以', '行', '对',\n  '是的', '没问题', '辛苦了', '麻烦了',\n  'ok', 'okay', 'yes', 'yep', 'y', 'thanks', 'thx', 'gotit', 'continue', 'goon', 'next', 'done',\n])\n\n/**\n * 图片/视频的类型白名单已经搬进 `classification.js`（v0.19）—— 扩展名归哪一类\n * 只该有一个事实来源，本文件只 import 它的 MIME 表（`mediaInfo` 按扩展名取 MIME）。\n */\n\n/** 单张内联图片的字节上限。 */\nconst MAX_IMAGE_BYTES = 12 * 1024 * 1024\n/**\n * 单个视频的字节上限。\n * Agent 生成的短视频通常几十 MB；放宽到 256MB，再大就该用系统播放器打开，\n * 而不是让侧边栏扛着整段字节。\n */\nconst MAX_VIDEO_BYTES = 256 * 1024 * 1024\n\n/**\n * 列表条目类型：文档（Markdown）/ 代码 / 图片 / 视频。\n *\n * v0.19 起这四个常量由 `classification.js` 拥有并在这里重新导出（`KIND_*` 是本文件的\n * 惯用名）。**不要再在本文件里写扩展名判断** —— 那正是要收拢的东西。\n */\nconst KIND_DOC = KIND_DOCUMENT\n\n/**\n * 机器可读的错误码。\n *\n * 宿主**不返回面向用户的文案** —— 文案由浏览器半边按当前语言翻译。\n * 这样宿主不必知道 UI 语言，以后加语言也不用动宿主。\n */\nexport const ERROR_CODES = {\n  outsideWorkspace: 'knit/outside-workspace',\n  /**\n   * v0.19：从 `knit/markdown-only` 改名。\n   *\n   * 名字必须跟着能力改 —— 这个码现在表示「这个类型不支持在面板里预览」\n   * （媒体、二进制、这一版不支持的代码语言、未知扩展名），\n   * 而不只是「不是 Markdown」。留着旧名字会让下一个读代码的人以为\n   * 放行范围还是「只有 Markdown」。\n   */\n  notPreviewable: 'knit/not-previewable',\n  notFound: 'knit/not-found',\n  notAFile: 'knit/not-a-file',\n  imageOnly: 'knit/image-only',\n  imageTooLarge: 'knit/image-too-large',\n  mediaOnly: 'knit/media-only',\n  mediaTooLarge: 'knit/media-too-large',\n  readFailed: 'knit/read-failed',\n  missingRel: 'knit/missing-rel',\n  notFoundRoute: 'knit/not-found-route',\n  loopbackOnly: 'knit/loopback-only',\n  methodNotAllowed: 'knit/method-not-allowed',\n  /**\n   * v0.21：写控制状态那一条路由（`POST /api/control`）的畸形输入。\n   *\n   * ⚠️ 这是**开发者可见、用户不可见**的码：面板只会发合法动作，\n   * 所以它不进客户端词典（`test/i18n.test.mjs` 的 `notUserFacing` 白名单里有它）。\n   */\n  badRequest: 'knit/bad-request',\n  internal: 'knit/internal',\n}\n\n/** 摘要截断长度（需求文档写 20-32 字，演示阶段放宽到 60 更好读）。 */\nexport const SUMMARY_CHARS = 60\n\n/** 明显的噪音目录，不进。 */\nconst SKIP_DIRS = new Set([\n  'node_modules', '.git', '.hg', '.svn', '.DSH', '.dsh',\n  'dist', 'build', 'out', '.next', '.nuxt', '.cache', '.turbo',\n  '__pycache__', '.venv', 'venv', 'env', 'target', 'coverage',\n  '.idea', '.vscode', '.gradle', 'Pods', 'DerivedData',\n])\n\n/* ── 解析结果缓存：key = 绝对路径，mtime+size 未变则直接复用 ──── */\n/** @type {Map<string, object>} */\nconst cache = new Map()\n\n/** 缓存里正文的总字节数（配合 `MAX_CACHE_BYTES` 淘汰）。 */\nlet cacheBodyBytes = 0\n\n/* ── v0.22 增量索引 ────────────────────────────────────────────────\n *\n * 审计结论（`Knit-v0.22-Phase0-审计.md` §2）：上面的 `cache` 已经兑现了「未变化文件不\n * 重读、不重解析」和「改一个文件只重处理该文件」—— 暖扫 `readFile = 0`。它**缺**的是\n * 跨进程：进程一没，缓存即空，重启后第一次扫描要把 700 个文件全部重读重解析。\n *\n * 所以这一版**不动检索算法**，只在 `cache` 外围加两件事：\n *   1. 持久层 `indexStore`（`index-store.js`）：把每个文件的内容指纹与派生的标题/摘要\n *      存进 DSH 自己的存储，让**重启后**能跳过读盘与解析；\n *   2. 目录级 memo `dirMemo`：目录 mtime 未变就跳过 `readdir`（实测暖扫耗时**全部**是\n *      `readdir + stat`，而 `collectDocs` 占扫描总耗时 104%–122%）。\n *\n * ⚠️ 三条不许破的边界：\n *   · `mtimeMs + size` **不是**唯一证据 —— 必须再核 `headHash`（提示词 §4）。\n *   · 树绝不因为「维护缓存」而遍历两遍 —— 目录 memo 只省 `readdir`，不改遍历顺序，\n *     `MAX_DIRS` / `MAX_DEPTH` / `SCAN_BUDGET_MS` 的作用范围一字不动。\n *   · 索引里**没有正文**（裁决 A）⇒ 正文永远来自当次读取，不可能陈旧。\n */\n\n/** 进程内的增量索引 store（`apply()` 拿到 `ctx.storage` 时换成持久化的那份）。 */\nlet indexRegistry = null\n\n/**\n * 一轮扫描里「核过指纹的」记录数上限。\n *\n * 提示词 §5⑤ 要求「reconciliation 只读取变化项，必要时**分批**执行避免阻塞主交互」。\n * 这个数字就是「分批」的粒度：坏掉的第一条会被立刻重读，其余未变化条目每轮抽查这么多，\n * 于是整个工作区在一段窗口内被核完，而单轮扫描的额外读盘有界。\n */\nconst INDEX_VERIFY_PER_PASS = 8\n\n/**\n * 本轮生效的抽验预算（默认 `INDEX_VERIFY_PER_PASS`）。\n *\n * 它可调，只为一件事：**证伪**。把预算设成 0，对账一次都不跑 ⇒ 「靠索引复用之后\n * 没人核指纹」这件事必须能被测试抓出来（提示词 §18：新增守卫必须能够证伪）。\n * 生产路径没有任何地方改它。\n */\nlet indexVerifyBudget = INDEX_VERIFY_PER_PASS\n\n/** 目录 → `{mtimeMs, md, code, media, dead, stats}`；目录 mtime 未变则跳过 `readdir`。 */\nconst dirMemo = new Map()\n\n/** 已装载持久索引的工作区根 → `Map<rel, 记录>`（值只在扫描时读，不长期留存）。 */\nconst indexRels = new Map()\n\n/** 已核过指纹的记录（`${hostRoot}\\u0000${rel}`）—— 抽验是「没核过的优先」。 */\nconst indexVerified = new Set()\n\n/** 抽验游标（每个 hostRoot 一个）—— 保证「分批」是轮转的，不是每次盯前几条。 */\nconst indexVerifyCursor = new Map()\n\n/** 每个 hostRoot 最近一轮扫描被解析过的记录数（基准脚本用它断言「只重处理变化的文件」）。 */\nconst indexStats = new Map()\n\n/* ── /v0.22 ──────────────────────────────────────────────────────── */\n\n/**\n * 写缓存并做容量淘汰（v0.20）。\n *\n * 淘汰顺序是**插入序**（`Map` 的迭代序），命中时不重排 —— 也就是 FIFO，不是严格的 LRU。\n * 对本插件的访问模式这是合适的：每次轮询扫的是同一批文件，FIFO 足够；\n * 更重要的是它**完全确定**，不会引入「同一输入两次跑出不同结果」的风险（§20）。\n *\n * @param {string} key - 绝对路径\n * @param {object} entry - 解析结果（`bodyBytes` 为正文占用）\n */\nfunction cacheSet(key, entry) {\n  const prev = cache.get(key)\n  if (prev) {\n    cacheBodyBytes -= prev.bodyBytes || 0\n    cache.delete(key)\n  }\n  cache.set(key, entry)\n  cacheBodyBytes += entry.bodyBytes || 0\n  while (cache.size > MAX_CACHE_ENTRIES || (cacheBodyBytes > MAX_CACHE_BYTES && cache.size > 1)) {\n    const oldest = cache.keys().next()\n    if (oldest.done) break\n    const dropped = cache.get(oldest.value)\n    cacheBodyBytes -= (dropped && dropped.bodyBytes) || 0\n    cache.delete(oldest.value)\n  }\n}\n\n/* ── 对话关键词缓存：key = sessionId，seq 未变则直接复用 ─────── */\n/** @type {Map<string, {seq:number, keywords:Array<{term:string,weight:number}>}>} */\nconst convCache = new Map()\n\n/** 会话里没有对话时的兜底关键词（空）。 */\nconst NO_KEYWORDS = []\n\n/**\n * 去掉 Markdown 行内标记，留下一句干净的纯文本。\n * @param {string} line - 原始行\n * @returns {string} 清洗后的行\n */\nfunction stripInline(line) {\n  return line\n    .replace(/!\\[[^\\]]*\\]\\([^)]*\\)/g, '')       // 图片\n    .replace(/\\[([^\\]]*)\\]\\([^)]*\\)/g, '$1')    // 链接 → 文字\n    .replace(/`([^`]*)`/g, '$1')                // 行内代码\n    .replace(/[*_~]/g, '')                      // 强调\n    .replace(/\\s+/g, ' ')\n    .trim()\n}\n\n/**\n * 从 Markdown 头部抽「标题 + 首段摘要」。\n *\n * 标题：正文里第一个 `# xxx`，没有就用文件名（去掉 .md）。\n * 摘要：跳过 YAML frontmatter / 标题行 / 代码围栏 / 列表 / 引用 / 表格，\n *       取第一段真正的正文文字。\n *\n * @param {string} head - 文件头部若干字节的文本\n * @param {string} fileName - 文件名（无路径）\n * @returns {{title:string, summary:string}} 解析结果\n */\nexport function parseMarkdown(head, fileName) {\n  const fallbackTitle = fileName.replace(/\\.md$/i, '')\n  const lines = head.split(/\\r?\\n/)\n\n  let title = ''\n  let summary = ''\n  let inFence = false\n  let i = 0\n\n  // 跳过开头可能存在的 YAML frontmatter\n  if (lines[0] !== undefined && lines[0].trim() === '---') {\n    for (i = 1; i < lines.length; i += 1) {\n      if (lines[i].trim() === '---') { i += 1; break }\n    }\n  }\n\n  for (; i < lines.length; i += 1) {\n    const line = lines[i].trim()\n\n    if (/^(```|~~~)/.test(line)) { inFence = !inFence; continue }\n    if (inFence) continue\n\n    if (!title) {\n      const m = /^#\\s+(.+)$/.exec(line)\n      if (m) { title = stripInline(m[1]); continue }\n    }\n    if (summary) continue\n    if (!line) continue\n    if (/^#{1,6}\\s/.test(line)) continue          // 其它级标题\n    if (/^([-*+]|\\d+\\.)\\s/.test(line)) continue   // 列表\n    if (/^>/.test(line)) continue                 // 引用\n    if (/^\\|/.test(line)) continue                // 表格\n    if (/^([-*_]\\s*){3,}$/.test(line)) continue   // 分隔线\n    if (/^</.test(line)) continue                 // HTML 块\n\n    const cleaned = stripInline(line)\n    if (cleaned) summary = cleaned\n  }\n\n  if (!title) title = fallbackTitle\n  if (summary.length > SUMMARY_CHARS) summary = `${summary.slice(0, SUMMARY_CHARS)}…`\n\n  return { title, summary }\n}\n\n/**\n * 从**已在内存里的首部**抽出索引要存的引用/导入列表（v0.22 修法 ①）。\n *\n * 为什么提前到这里做：引用图（`buildLinkGraph()`）与关系投影（`buildRelationFacts()`）\n * 各自都要「原首部 → 候选引用」，而它们**互相不知道对方也抽过一遍**。把这一遍放进\n * 读盘那一刻，结果同时进内存条目与索引记录，于是：进程内两个消费者各取所需、\n * 重启后从索引直接取 —— 抽取次数从「每个消费者每轮一次」降到「每个文件每次读盘一次」。\n *\n * ⚠️ 两套 Markdown 口径都算、都存（见 `index-store.js` 模块头第 1 条）：\n * `md` = `extractRefs()` 的默认口径（只认 `.md` 目标，引用图用），\n * `any` = `anyExt: true`（还认 md→代码，关系投影用）。**不能只存一套再过滤** ——\n * 两者各有自己的 `MAX_REFS_PER_DOC = 500` 截断点，近似会在引用极多的文件上改变目标集合。\n *\n * @param {string} head - 文件首部（已在内存里）\n * @param {boolean} isCode - 代码走 `importsOf()`，Markdown 走引用抽取\n * @returns {{md?: Array<object>, any?: Array<object>, imports?: Array<object>}} 抽取结果\n */\nfunction refsForHead(head, isCode) {\n  const text = typeof head === 'string' ? head : ''\n  if (isCode) return { imports: importsOf(text) }\n  return {\n    md: extractRefsWithLines(text),\n    any: extractRefsWithLines(text, { anyExt: true }),\n  }\n}\n\n/**\n * v0.22：一份**完整的**索引记录 → `readDoc()` 形状的缓存条目。\n *\n * 「索引里存了什么」与「条目里能还原什么」是同一件事，这里就把它写死：\n *\n *   · `title` / `summary` / `refs` → 索引里各存一份（`refs` = 抽取后的引用/导入列表，见修法 ①）。\n *   · `body`（整篇正文）→ **索引里没有，也永远不会有**。调用方（`readDoc`）因此\n *     只在「这一轮不需要正文」时用这份还原结果（时间序扫描），相关检索仍然读盘。\n *     这条分工就是裁决 A 的落实：正文不可能陈旧。\n *\n * ⚠️ 字段必须与 `readDoc()` 里的条目**逐字对齐**。少一个 `hayBody`，相关检索就会\n * 在「条目看起来命中缓存」与「打分读到 undefined」之间产生静默的空结果。\n *\n * @param {object} record - 索引记录\n * @returns {object} 缓存条目形状（`body` 为空串）\n */\nfunction restoreFromIndex(record) {\n  return {\n    mtimeMs: record.mtimeMs,\n    size: record.size,\n    headHash: record.headHash,\n    title: record.title,\n    summary: record.summary,\n    // v0.22 修法 ①：索引里**没有原文首部**，只有抽取结果。所以还原出来的条目\n    // `head` 是空串、`refs` 带着关系投影与引用图需要的一切。谁要是还从 `head`\n    // 读内容，重启后就会**静默**拿到空串 —— 两个消费者因此都优先读 `refs`。\n    head: '',\n    refs: record.refs,\n    body: '',\n    bodyBytes: 0,\n    bodyTruncated: false,\n    // v0.22：还原出来的条目**没有正文**。`hydrateBodies()` 靠这一位决定补不补，\n    // 相关检索因此不会拿到一份「看着像命中、其实是空串」的正文去打分。\n    bodyReady: false,\n    hayTitle: String(record.title).toLowerCase(),\n    haySummary: String(record.summary).toLowerCase(),\n    hayBody: '',\n  }\n}\n\n/**\n * `readDoc()` 的读盘那一半（v0.22 从原函数里原样拆出，逻辑一字未改）。\n *\n * ⚠️ v0.22 起这就是**唯一**的文档读取路径：原来那个「先查缓存再决定读不读」的包装\n * 已经并进 `collectDocs()` 的逐条判定里（缓存 / 索引 / 重读三选一，见那里的注释）。\n * 留两份判定只会漂移 —— 所以包装函数被删掉了，这里只负责「读 + 解析」。\n *\n * @param {string} absPath - 绝对路径\n * @param {object} st - 已取得的 stat 结果\n * @returns {Promise<object|null>} 解析结果，读失败返回 null\n */\nasync function readDocFromDisk(absPath, st, options = {}) {\n  // v0.22 修法 ①：抽取结果可以不要。`hydrateBodies()` 补正文时条目上已经有\n  // 索引带来的 `refs`（同一份内容算出来的同一个结果），再抽一遍纯属白烧 CPU ——\n  // 实测在 16KB 首部的语料上是每文件两次正则扫描。\n  const wantRefs = options.refs !== false\n  let head = ''\n  let body = ''\n  let bodyBytes = 0\n  let bodyTruncated = false\n  try {\n    const buf = await readFile(absPath)\n    head = buf.subarray(0, HEAD_BYTES).toString('utf8')\n    // v0.20：**整篇正文**参与打分。只解码前 `MAX_BODY_BYTES` 个字节 ——\n    // `toString(enc, start, end)` 在字节边界解码，超出部分从不变成字符串，\n    // 所以「巨文件」这条路径上的内存占用是有界的。\n    bodyBytes = Math.min(buf.length, MAX_BODY_BYTES)\n    body = buf.toString('utf8', 0, bodyBytes)\n    bodyTruncated = buf.length > MAX_BODY_BYTES\n  } catch {\n    return null\n  }\n\n  const fileName = absPath.split(sep).pop() || absPath\n  const { title, summary } = parseMarkdown(head, fileName)\n  const entry = {\n    mtimeMs: st.mtimeMs,\n    size: st.size,\n    title,\n    summary,\n    // v0.22：内容指纹（对上面那段**已在内存里**的头部算，不额外读盘）。\n    // 它是「mtime+size 之外的第二道证据」—— 见 `Knit-决策记录.md` 裁决 A。\n    headHash: headHashOf(head),\n    // v0.22：正文已在手上（这条路径刚刚整读过）。\n    bodyReady: true,\n    // v0.22 修法 ①：抽取结果随读盘一起算出来 —— 进索引的就是它（原文首部不进索引）。\n    // `wantRefs: false` 是给「条目上已经有一份同一个内容算出来的 refs」的调用方用的\n    // （`hydrateBodies()` 补正文时就是这种情况），省掉每文件两次正则扫描。\n    ...(wantRefs ? { refs: refsForHead(head, false) } : {}),\n    // ⚠️ 原文首部**留在缓存里**（v0.14）：上下文装配要用它抽引用关系。\n    // 它已经在内存里了 —— 再读一遍盘才是浪费。`publicDoc()` 不会把它发出去。\n    // 修法 ① 之后 `refs` 是首选、`head` 只是**同进程内的**兜底。\n    head,\n    // v0.20：正文（截到上限）也留在缓存里 —— 片段切分与全文打分的输入。\n    // 语义上 `head` 是「首部」（引用关系用，16KB），`body` 是「全文」，\n    // 两者**不许互相挪用**（实现说明 D4）。\n    body,\n    bodyBytes,\n    bodyTruncated,\n    hayTitle: title.toLowerCase(),\n    haySummary: summary.toLowerCase(),\n    // v0.20：**不再截前 2500 字**。文件级 BM25 现在看得到整篇正文，\n    // 于是 `avgdl[body]` 是真实长度，长文件被 `b = 0.75` 直接惩罚（D3）。\n    hayBody: body.toLowerCase(),\n  }\n  cacheSet(absPath, entry)\n  return entry\n}\n\n/**\n * 读一个**代码文件**参与检索所需的头部（v0.19）。\n *\n * 与 `readDocFromDisk()` 共用同一套 `haystack` 形状 —— 这正是「不给代码建第二套检索」\n * 在数据层面的落实：`relevance.js` 一个字节都不用改，它看到的仍是它一直在看的\n * `{title, summary, body}`。\n *\n * haystack 的字段语义在这里被**重新指派**（需求 §13：代码不复用 Markdown 的语义）：\n *\n *   - `title`   ← 文件名（权重 4，最高价值字段：`plugin-loader.js` 本身就带任务语义）\n *   - `summary` ← 工作区相对路径的目录部分（权重 2）\n *   - `body`    ← **整篇正文**（权重 1；v0.20 起不再截前 2500 字）\n *\n * 于是 `FIELD_WEIGHTS` 现成的 4 / 2 / 1 恰好等于\n * 「filename × 4 / path × 2 / content × 1」，排序器零改动。\n *\n * ⚠️ v0.22：这就是**唯一**的代码读取路径（原因同 `readDocFromDisk()`）。\n * 它**必须**知道 `rel` —— haystack 的 `summary` 槽放的正是相对路径的目录部分。\n *\n * @param {string} absPath - 绝对路径\n * @param {string} root - 工作区根\n * @param {object} st - 已取得的 stat 结果\n * @returns {Promise<object|null>} 解析结果，读失败返回 null\n */\nasync function readCodeFromDisk(absPath, root, st, options = {}) {\n  const wantRefs = options.refs !== false\n  let head = ''\n  let body = ''\n  let bodyBytes = 0\n  let bodyTruncated = false\n  try {\n    const buf = await readFile(absPath)\n    head = buf.subarray(0, CODE_HEAD_BYTES).toString('utf8')\n    // v0.20：与 `readDoc` 同一条口径 —— 头部只服务引用关系，打分看整篇正文。\n    bodyBytes = Math.min(buf.length, MAX_BODY_BYTES)\n    body = buf.toString('utf8', 0, bodyBytes)\n    bodyTruncated = buf.length > MAX_BODY_BYTES\n  } catch {\n    return null\n  }\n\n  const name = absPath.split(sep).pop() || absPath\n  const rel = relative(root, absPath).split(sep).join('/')\n  const cut = rel.lastIndexOf('/')\n  // 目录部分保留结尾的 `/`（`src/context/`），与列表里第二行的观感一致；\n  // 根目录下的文件是空串 —— 不编一个 `/` 出来。\n  const dir = cut >= 0 ? rel.slice(0, cut + 1) : ''\n\n  const entry = {\n    mtimeMs: st.mtimeMs,\n    size: st.size,\n    // v0.22：内容指纹 + 「正文已在手上」，口径与 `readDocFromDisk` 一致。\n    headHash: headHashOf(head),\n    bodyReady: true,\n    // v0.22 修法 ①：代码侧抽的是 import 语句（`importsOf()` 的 `{spec, line}`）。\n    ...(wantRefs ? { refs: refsForHead(head, true) } : {}),\n    head,\n    body,\n    bodyBytes,\n    bodyTruncated,\n    // ⚠️ 标题是**带扩展名的文件名**，不是去扩展名的 stem。\n    // 代码的文件名里扩展名是信息的一部分（`plugin-loader.js` vs `plugin.json`），\n    // 去掉它反而丢掉了最能区分两个候选的那个字符。\n    title: name,\n    // 摘要位放路径。列表第二行本来就在显示路径，这里只是让同一个值也能参与打分。\n    summary: dir,\n    hayTitle: name.toLowerCase(),\n    haySummary: dir.toLowerCase(),\n    hayBody: body.toLowerCase(),\n  }\n  cacheSet(absPath, entry)\n  return entry\n}\n\n/**\n * `stat` 的「拿不到就是没有」版本（v0.22）。\n *\n * 目录 memo 的判据是目录 mtime，而 `stat` 失败（权限、刚被删）不是一个可以让扫描\n * 崩掉的理由 —— 失败一律当 `null`，调用方据此走原路径重新 `readdir`。\n *\n * @param {string} path - 绝对路径\n * @returns {Promise<object|null>} stat 结果或 null\n */\nasync function statOrNull(path) {\n  try {\n    return await stat(path)\n  } catch {\n    return null\n  }\n}\n\n/**\n * 广度优先扫出工作区里的文档、代码与媒体文件（v0.19；v0.22 加目录级 memo）。\n *\n * 一次遍历同时收三类，目录预算与时间预算共享；三类各自有数量上限，\n * 截图再多也不会把文档名额挤光，代码再多也不会（见 `MAX_CODE`）。\n *\n * **扫描只做「目录元数据 → 分类 → 准入」**：这里不读任何文件内容，\n * 正文读取留给 `collectDocs`（bounded，见 `readCode`）。\n *\n * v0.22：目录自己的 mtime 与上一轮逐字相同 ⇒ 跳过这一层的 `readdir`，改用缓存的\n * 分类结果。**它省的是 syscall，不是正确性** —— 缓存的是「这一层有什么、各自算哪类」，\n * 重新入队、计数、配额三条规则一字未改（见审计文档 §3 结论 4 与 §5 R3）。\n *\n * @param {string} root - 工作区根（会话 cwd）\n * @returns {Promise<{md: string[], code: string[], media: Array<{abs:string, kind:string}>,\n *                    mdTruncated: boolean, codeTruncated: boolean, mediaTruncated: boolean,\n *                    stats: object, scanMs: number}>} 分类后的绝对路径与计数\n */\nasync function collectEntries(root) {\n  const startedAt = Date.now()\n  /** @type {string[]} */\n  const md = []\n  /** @type {string[]} */\n  const code = []\n  /** @type {Array<{abs:string, kind:string}>} */\n  const media = []\n  /**\n   * 同一轮扫描内的去重集合（v0.22）。\n   *\n   * 目录 memo 让**同一层**可能被两条路径各命中一次（父目录缓存里已经有子目录清单，\n   * 子目录自己也命中 memo），不去重的话列表长度会随目录层级虚增。集合是本轮内幂等的\n   * 唯一保证 —— 它的作用域**只有这一轮**，不进任何持久结构。\n   */\n  const mdSeen = new Set()\n  const codeSeen = new Set()\n  const mediaSeen = new Set()\n  const deadline = startedAt + SCAN_BUDGET_MS\n  /** @type {Array<{dir:string,depth:number}>} */\n  const queue = [{ dir: root, depth: 0 }]\n  let visited = 0\n  /**\n   * v0.19 验收要的计数（需求 §50）。\n   * `codeSeen` 是**见到的**代码文件数，`codeAdmitted` 是进语料的，\n   * `codeExcluded` 是被 `MAX_CODE` 挡在外面的 —— 三者分开，才看得出上限有没有真的生效。\n   */\n  const stats = {\n    mdSeen: 0, mdAdmitted: 0,\n    codeSeen: 0, codeAdmitted: 0, codeExcluded: 0,\n    mediaSeen: 0, mediaAdmitted: 0,\n    generated: 0, ignored: 0,\n  }\n\n  while (queue.length > 0) {\n    if (visited >= MAX_DIRS\n      || (md.length >= MAX_DOCS && media.length >= MAX_MEDIA && code.length >= MAX_CODE)\n      || Date.now() > deadline) break\n    const { dir, depth } = queue.shift()\n    visited += 1\n\n    // ── v0.22：目录没变就不重新 `readdir` ──────────────────────────────\n    //\n    // 判据只有一条 —— 目录自身的 mtime 与上一轮**逐字相同**。APFS 实测（审计文档 §3\n    // 结论 4）：新增 / 删除文件只更新**直接父目录**的 mtime，且**不向上传播** ⇒ 这个\n    // 判据不会漏掉「某个子目录里多了个文件」，因为那一层自己的 mtime 变了。\n    //\n    // ⚠️ 它只决定「要不要重新 `readdir`」，**不改变遍历顺序**：命中的目录照样把缓存的\n    // 子目录重新入队，于是 `MAX_DIRS` / `MAX_DEPTH` / `SCAN_BUDGET_MS` 的作用范围一字不动。\n    // （旧实测否掉的是 cap-aware **剪枝** —— 提前 break 不遍历，那会让语料变小，见 §5 R3。）\n    const snapshot = await statOrNull(dir)\n    if (snapshot) {\n      const memo = dirMemo.get(dir)\n      if (memo && memo.mtimeMs === snapshot.mtimeMs) {\n        // 计数照旧累加：缓存省的是 `readdir`，不是「这个工作区里有什么」。\n        for (const key of Object.keys(stats)) stats[key] += memo.stats[key] || 0\n        // 两份列表都受**当前**配额约束，且必须**去重**：同一轮扫描里 A 命中了目录 memo、\n        // B 也命中了，它们缓存的是各自那一层，`B` 的子目录在 `A` 的记录里也会出现一次。\n        // 去重集合是「同一轮内幂等」的保证 —— 少了它，列表长度会随目录层级虚增。\n        for (const abs of memo.md) {\n          if (md.length >= MAX_DOCS) break\n          if (mdSeen.has(abs)) continue\n          mdSeen.add(abs)\n          md.push(abs)\n        }\n        for (const abs of memo.allCode) {\n          if (code.length >= MAX_CODE) break\n          if (codeSeen.has(abs)) continue\n          codeSeen.add(abs)\n          code.push(abs)\n        }\n        for (const item of memo.allMedia) {\n          if (media.length >= MAX_MEDIA) break\n          if (mediaSeen.has(item.abs)) continue\n          mediaSeen.add(item.abs)\n          media.push({ abs: item.abs, kind: item.kind })\n        }\n        if (depth < MAX_DEPTH) {\n          for (const sub of memo.dirs) queue.push({ dir: sub, depth: depth + 1 })\n        }\n        continue\n      }\n    }\n    const mtimeMs = snapshot ? snapshot.mtimeMs : null\n    /** 本目录**自己**发现的子目录与文件（不含更深层）—— 缓存的就是这一小份。 */\n    const local = {\n      dirs: [], md: [], allCode: [], allMedia: [],\n      stats: {\n        mdSeen: 0, mdAdmitted: 0,\n        codeSeen: 0, codeAdmitted: 0, codeExcluded: 0,\n        mediaSeen: 0, mediaAdmitted: 0,\n        generated: 0, ignored: 0,\n      },\n    }\n\n    let entries\n    try {\n      entries = await readdir(dir, { withFileTypes: true })\n    } catch {\n      continue\n    }\n\n    for (const entry of entries) {\n      const abs = join(dir, entry.name)\n      if (entry.isDirectory()) {\n        if (depth >= MAX_DEPTH) continue\n        if (SKIP_DIRS.has(entry.name)) continue\n        if (entry.name.startsWith('.')) continue\n        if (mtimeMs !== null) local.dirs.push(abs)\n        queue.push({ dir: abs, depth: depth + 1 })\n      } else if (entry.isFile()) {\n        const info = classifyFile(entry.name)\n        // **准入判定只有这一处**：`isContextKind()` 回答「算不算上下文候选」，\n        // 下面再按具体类型分账。配额与计数必须分开 —— v0.19 的 corpus pressure\n        // 要求能看出到底是文档还是代码把语料撑大的（需求 §15 §50）。\n        if (isContextKind(info.kind)) {\n          if (info.kind === KIND_DOC) {\n            stats.mdSeen += 1\n            local.stats.mdSeen += 1\n            if (mtimeMs !== null) local.md.push(abs)\n            if (md.length < MAX_DOCS && !mdSeen.has(abs)) {\n              mdSeen.add(abs)\n              md.push(abs)\n              stats.mdAdmitted += 1\n              local.stats.mdAdmitted += 1\n            }\n          } else {\n            stats.codeSeen += 1\n            local.stats.codeSeen += 1\n            if (mtimeMs !== null) local.allCode.push(abs)\n            if (code.length < MAX_CODE && !codeSeen.has(abs)) {\n              codeSeen.add(abs)\n              code.push(abs)\n              stats.codeAdmitted += 1\n              local.stats.codeAdmitted += 1\n            } else {\n              stats.codeExcluded += 1\n              local.stats.codeExcluded += 1\n            }\n          }\n        } else if (info.kind === KIND_IMAGE || info.kind === KIND_VIDEO) {\n          stats.mediaSeen += 1\n          local.stats.mediaSeen += 1\n          if (mtimeMs !== null) local.allMedia.push({ abs, kind: info.kind })\n          if (media.length < MAX_MEDIA && !mediaSeen.has(abs)) {\n            mediaSeen.add(abs)\n            media.push({ abs, kind: info.kind })\n            stats.mediaAdmitted += 1\n            local.stats.mediaAdmitted += 1\n          }\n        } else if (info.kind === KIND_GENERATED) {\n          // 生成/噪声产物：**数一下，但一个都不准入**（需求 §6 §7）。\n          stats.generated += 1\n          local.stats.generated += 1\n        } else {\n          stats.ignored += 1\n          local.stats.ignored += 1\n        }\n      }\n    }\n\n    // 只有拿到 mtime 的目录才入 memo：`mtimeMs === null` 意味着这次 `stat` 失败，\n    // 而「失败」绝不能变成一条「以后都不用再看」的记录。上限与解析缓存同量级，\n    // 超出按插入序淘汰最早的（与 `cacheSet` 同一条 FIFO 纪律）。\n    if (mtimeMs !== null) {\n      dirMemo.set(dir, {\n        mtimeMs, dirs: local.dirs, md: local.md,\n        allCode: local.allCode, allMedia: local.allMedia, stats: local.stats,\n      })\n      while (dirMemo.size > MAX_CACHE_ENTRIES) {\n        const oldest = dirMemo.keys().next()\n        if (oldest.done) break\n        dirMemo.delete(oldest.value)\n      }\n    }\n  }\n\n  return {\n    md,\n    code,\n    media,\n    mdTruncated: md.length >= MAX_DOCS,\n    codeTruncated: code.length >= MAX_CODE,\n    mediaTruncated: media.length >= MAX_MEDIA,\n    stats,\n    scanMs: Date.now() - startedAt,\n  }\n}\n\n/**\n * 读一个媒体文件的元信息（只 stat，绝不读内容 —— 视频可能上百 MB）。\n * @param {string} root - 工作区根\n * @param {{abs:string, kind:string}} item - 扫描阶段记下的媒体项\n * @returns {Promise<object|null>} 列表记录，读失败返回 null\n */\nasync function readMediaMeta(root, { abs, kind }) {\n  let st\n  try {\n    st = await stat(abs)\n  } catch {\n    return null\n  }\n  if (!st.isFile()) return null\n\n  const name = abs.split(sep).pop() || abs\n  return {\n    kind,\n    path: abs,\n    rel: relative(root, abs).split(sep).join('/'),\n    name,\n    // 没有正文可解析，标题就用文件名（去扩展名）。\n    title: name.replace(/\\.[^.]+$/, ''),\n    summary: '',\n    size: st.size,\n    mtimeMs: st.mtimeMs,\n    // 媒体只能靠文件名参与相关性匹配（镜头名、截图名里的关键词）。\n    haystack: { title: name.toLowerCase(), summary: '', body: '' },\n  }\n}\n\n/**\n * 清掉**全部**进程内派生状态（v0.22；与 `relations.js` 的 `resetRelationCache()` 同定位）。\n *\n * 仅供测试：用例之间必须能拿到一个「刚重启」的插件，而模块级状态在同一个进程里是共享的。\n * 生产路径一次都不会调用它。\n *\n * @returns {void}\n */\nexport function resetIndexMemory() {\n  cache.clear()\n  cacheBodyBytes = 0\n  dirMemo.clear()\n  indexRels.clear()\n  indexVerified.clear()\n  indexVerifyCursor.clear()\n  indexStats.clear()\n  indexRegistry = null\n  indexVerifyBudget = INDEX_VERIFY_PER_PASS\n}\n\n/**\n * 装一次插件存储（`apply()` 拿到 `ctx.storage` 时换掉内存版；测试也走它）。\n * @param {{createIndexStore?: Function}} store - 索引存储实例；传 `null` 退回「没有存储」\n * @returns {void}\n */\nexport function setIndexRegistry(store) {\n  indexRegistry = store || null\n}\n\n/**\n * 装一次语义引擎（`apply()` 拿到 `ctx.storage` 时换成带持久化配置的那份；测试也走它）。\n * @param {object|null} engine - `semantic.js` 的引擎；传 `null` 退回「没有配置」\n * @returns {void}\n */\nexport function setSemanticEngine(engine) {\n  semanticEngine = engine || createSemanticEngine({ store: null })\n}\n\n/**\n * 最近一轮扫描的索引计数（v0.22）。\n *\n * 验收要求「不能只说更快」，所以这些**计数**要和墙钟一起报出来：\n * 这一轮真正读盘的候选数、靠索引复用的条数、写回的差量条数。\n * 它只有计数，没有文件名、没有正文、没有用户数据 —— 因此可以安全地进基准报告。\n *\n * @param {string} root - canonical 工作区根\n * @returns {{readFiles:number, reused:number, put:number, del:number,\n *            persisted:boolean, reason:string}|null} 计数或 null\n */\nexport function indexStatsFor(rawRoot) {\n  const held = indexStats.get(hostPathOf(rawRoot))\n  return held ? { ...held } : null\n}\n\n/**\n * 索引存储当前是否**已被证明**可用（`persisted` 只在读或写成功之后才是 true）。\n * @returns {{persisted:boolean, reason:string}} 状态\n */\nexport function indexStorageStatus() {\n  return indexRegistry\n    ? { persisted: indexRegistry.persisted, reason: indexRegistry.reason }\n    : { persisted: false, reason: 'no-storage' }\n}\n\n/**\n * 调本轮抽验预算（v0.22）。**只为证伪**：设成 0 时对账一次都不跑，测试据此证明\n * 「指纹核对」这道守卫真的在起作用；生产代码不调用它。\n *\n * @param {number} budget - 非负整数；非法值退回默认 `INDEX_VERIFY_PER_PASS`\n * @returns {number} 生效之后的预算\n */\nexport function setIndexVerifyBudget(budget) {\n  const n = Number(budget)\n  indexVerifyBudget = Number.isFinite(n) && n >= 0 ? Math.trunc(n) : INDEX_VERIFY_PER_PASS\n  return indexVerifyBudget\n}\n\n/** 抽验标记的键（`hostRoot` 与 `rel` 之间用 NUL，避免路径里出现这个组合）。 */\nconst verifyKey = (root, rel) => `${root}\\u0000${rel}`\n\n/**\n * 把一个工作区的索引读进内存（每个 root 只读一次）。\n *\n * 读一次就够：这一轮扫描内的所有判定都以这份快照为准，写回走差量。\n * 存储不可用时 `read()` 自己返回空 Map —— 这条路径与「索引为空」完全同形，\n * 检索因此**不需要**知道存储坏没坏（提示词 §5③ 的降级要求）。\n *\n * @param {string} root - canonical 工作区根\n * @returns {Promise<Map<string, object>>} rel → 记录\n */\nasync function ensureIndexRels(root) {\n  const held = indexRels.get(root)\n  if (held) return held\n  const map = indexRegistry ? await indexRegistry.read(root) : new Map()\n  indexRels.set(root, map)\n  return map\n}\n\n/**\n * 从「靠索引复用」的记录里挑出本轮要**核指纹**的那几条（v0.22）。\n *\n * 两条纪律：\n *   · **有界** —— 最多 `INDEX_VERIFY_PER_PASS` 条，与语料规模无关，于是单轮扫描的\n *     额外读盘是常数级的，不会把一次用户可见的检索拖慢。\n *   · **公平** —— 优先挑「这个进程里还没核过」的，游标轮转推进；全核过一遍之后\n *     从头再核，于是对账是**持续**的，不是启动时一次性走过场。\n *\n * @param {string} root - canonical 工作区根\n * @param {Array<{abs:string, rel:string, isCode:boolean, record:object}>} reused - 复用清单\n * @returns {Array<{abs:string, rel:string, isCode:boolean, record:object}>} 本轮要核的\n */\nfunction sampleForVerify(root, reused) {\n  if (reused.length === 0) return []\n  const take = Math.min(indexVerifyBudget, reused.length)\n  const cursorKey = `verify\\u0000${root}`\n  const cursor = (indexVerifyCursor.get(cursorKey) || 0) % reused.length\n  const out = []\n  for (let i = 0; i < reused.length && out.length < take; i += 1) {\n    const item = reused[(cursor + i) % reused.length]\n    if (indexVerified.has(verifyKey(root, item.rel))) continue\n    out.push(item)\n  }\n  // 全部核过了（进程活得够久）⇒ 从游标处再核一遍，保持持续对账。\n  if (out.length === 0) {\n    for (let i = 0; i < take; i += 1) out.push(reused[(cursor + i) % reused.length])\n  }\n  indexVerifyCursor.set(cursorKey, (cursor + take) % reused.length)\n  return out\n}\n\n/**\n * 一条已解析记录 → 可持久化的索引记录。\n *\n * 存的是**抽取后的 `refs`**，不是原文首部（v0.22 修法 ①，见 `index-store.js` 模块头）：\n * `buildRelationFacts()` / `buildLinkGraph()` 要的只是「这份文件提到了哪些路径」，\n * 存 16KB 原文会让索引体积 ≈ 源码体积，而 `KvUnit` 只有 `loadAll()` ⇒ 每次用索引\n * 都要为加载一份和源码一样大的 JSON 付钱（实测让默认的相关检索重启后慢 1.31×）。\n *\n * @param {object} entry - `readDoc()` / `readCode()` 的条目\n * @param {string} rel - 工作区相对路径\n * @returns {object} 索引记录\n */\nfunction recordFor(entry, rel) {\n  return {\n    rel,\n    mtimeMs: entry.mtimeMs,\n    size: entry.size,\n    headHash: entry.headHash,\n    title: entry.title,\n    summary: entry.summary,\n    refs: entry.refs,\n  }\n}\n\n/**\n * 算一份 rel → 记录的快照，并与装载进来的旧索引比对出差量。\n *\n * 三种变化各有各的动作，**都在这里**：\n *   · 新增 / 更新 → `put`（只写这一条）\n *   · 少了的（被删 / 被移出准入范围 / 被 Git 切分支切没了）→ `del`（只删这一条）\n *   · 没变的 → 两边都不出现，一个字节都不写\n *\n * 删除必须有界：一轮扫描只抽验 `INDEX_VERIFY_PER_PASS` 条**没在本轮语料里出现**的旧记录\n * （游标轮转，见 `sweepStale`）—— 否则「1000 个文件全删掉」会把删除量变成一次 O(N) 的写风暴。\n *\n * @param {string} root - canonical 工作区根\n * @param {Map<string, object>} next - 本轮算出的 rel → 记录\n * @param {Map<string, object>} before - 装载进来的旧索引\n * @returns {{put: Array<object>, del: string[]}} 差量\n */\nfunction indexDiff(root, next, before) {\n  const put = []\n  const del = []\n  for (const [rel, record] of next) {\n    const old = before.get(rel)\n    if (old && old.headHash === record.headHash\n      && old.mtimeMs === record.mtimeMs && old.size === record.size) continue\n    put.push(record)\n  }\n  // 本轮语料里根本没有的旧记录：抽验删除（游标轮转，保证「分批」是公平的）。\n  const stale = []\n  for (const rel of before.keys()) {\n    if (!next.has(rel)) stale.push(rel)\n  }\n  if (stale.length > 0) {\n    let cursor = indexVerifyCursor.get(root) || 0\n    if (cursor >= stale.length) cursor = 0\n    const take = Math.min(INDEX_VERIFY_PER_PASS, stale.length)\n    for (let i = 0; i < take; i += 1) {\n      del.push(stale[(cursor + i) % stale.length])\n    }\n    indexVerifyCursor.set(root, (cursor + take) % stale.length)\n  }\n  return { put, del }\n}\n\n/**\n * 把一批记录里缺少正文的那些**按需**补齐（v0.22）。\n *\n * 为什么必须有这一步：索引里**没有正文**（裁决 A），而从索引还原出来的条目\n * `body` 是空串。时间序列表不需要正文（`publicDoc()` 本来就不下发它），但\n * **相关检索需要** —— 文件级 BM25 打分的输入是整篇小写正文。\n *\n * 所以相关路径照旧读正文，「跳过读盘」这一版只在时间序路径上成立，这是**如实记下的代价**，\n * 不是遗漏。补齐仍然是有界的：只补真的会参与打分的那批（`pool` 已按 kind 切好）。\n *\n * @param {Array<object>} list - 条目（原地升级）\n * @param {string} root - 工作区根\n * @returns {Promise<number>} 真正补了几条\n */\nasync function hydrateBodies(list, root) {\n  let hydrated = 0\n  for (const doc of list) {\n    if (doc.bodyReady) continue\n    // 条目上已经有 `refs`（索引复用来的）时明说不要重算 —— 省掉两次正则扫描，\n    // 而结果本来就一模一样。没有 `refs` 时才让它顺带算出来。\n    const wantRefs = !(doc.refs && typeof doc.refs === 'object')\n    const meta = doc.kind === KIND_CODE\n      ? await readCodeFromDisk(doc.path, root, { mtimeMs: doc.mtimeMs, size: doc.size }, { refs: wantRefs })\n      : await readDocFromDisk(doc.path, { mtimeMs: doc.mtimeMs, size: doc.size }, { refs: wantRefs })\n    if (!meta) continue\n    doc.head = meta.head\n    // v0.22 修法 ①：整读时顺带算出的抽取结果也要跟着升级 —— 否则「索引复用来的\n    // `refs`」与「刚读出来的 `head`」会在同一个条目上不一致（关系用旧的、引用图用新的）。\n    if (meta.refs) doc.refs = meta.refs\n    doc.body = meta.body\n    doc.bodyBytes = meta.bodyBytes\n    doc.bodyTruncated = meta.bodyTruncated\n    doc.haystack = { title: meta.hayTitle, summary: meta.haySummary, body: meta.hayBody }\n    doc.bodyReady = true\n    cacheSet(doc.path, meta)\n    hydrated += 1\n  }\n  return hydrated\n}\n\n/**\n * 扫出工作区里全部文档、代码与媒体的元信息（各自按 mtime 倒序）。\n *\n * 三类共用一次目录遍历（`collectEntries`），但**只有文档与代码会读正文头部**\n * ——媒体永远只 stat（视频可能上百 MB）。\n *\n * v0.22：每条候选先过一遍「有没有资格不读盘」——顺序是\n *   ① 进程内缓存命中（mtime+size）→ 直接复用，一次盘都不读；\n *   ② 持久索引里有记录且 mtime+size 一致 → **只读头部核指纹**（≤16KB），核过就还原；\n *   ③ 其余 → 老老实实整读 + 重解析。\n * 第 ② 步是这一版唯一新增的一致性问题：「同 mtime、同 size、内容变了」必须在核过指纹后\n * 才敢复用，而提示词 §4 明确禁止把 mtime/size 当作唯一证据。\n *\n * @param {string} root - 工作区根\n * @returns {Promise<{docs: Array<object>, code: Array<object>, media: Array<object>,\n *                    truncated: boolean, codeTruncated: boolean, mediaTruncated: boolean,\n *                    stats: object, scanMs: number}>}\n */\nexport async function collectDocs(rawRoot, options = {}) {\n  // v0.22：**索引一律按 canonical 工作区根记账**。\n  //\n  // 为什么必须在这里归一，而不是只靠调用方：`scan()` 自己有 `hostPathOf()`（展开符号\n  // 链接），但 `collectDocs()` 是导出函数，工具与测试会**直接用工作区原路径**调它。\n  // 两边都用原路径分别记账的话，同一个工作区会留下两份内存状态，而**存储里\n  // 同一个键会被两个不同的 `root` 值轮流覆盖** —— 于是「跨工作区隔离」的过滤条件\n  // 会随最后一次写入摇摆，索引时灵时不灵，且完全不报错。\n  // `hostPathOf()` 在路径不存在时兜底返回原值，所以这里不会把「打不开」升级成异常。\n  const root = hostPathOf(rawRoot)\n  // v0.22 修法 ②（2026-10-10）：**要正文的扫描不查索引**。\n  //\n  // 索引省下的是「读盘 + 解析正文」，而相关检索（BM25）无论如何都要拿到全部正文\n  // —— `rankByRelevance()` 的 `avgdl` / `df` 都是正文的函数（裁决 A）。于是那条路上\n  // 复用来的记录会被 `hydrateBodies()` 立刻整读补回正文，净效果是**多付一次索引装载**：\n  // 每条记录一个文件 open + read + `JSON.parse`，实测 600 条约 60–75 ms，而且这个成本\n  // 与记录里的载荷大小**几乎无关**（见 `Knit-v0.22-实现与基准报告.md` §4.5）。\n  // 判据因此不是「有没有索引」，而是**这一轮到底用不用得着正文** —— 只有调用方知道，\n  // 于是由它显式传 `{ index: false }`；不传仍然查索引（低层 API 不替调用方做这个决定）。\n  const useIndex = options.index !== false\n  const found = await collectEntries(root)\n  const docs = []\n  // v0.20：被 `MAX_BODY_BYTES` 截掉尾巴的文件数。**只是计数**，用来在规模报告里\n  // 诚实说出「有多大比例的文件没有全量参与打分」，不参与任何排序。\n  let bodyTruncated = 0\n\n  // v0.22：装载索引 + 逐条「读盘 / 还原」判定。整段就是上面的 ①②③。\n  // `useIndex === false` 时给一张空表：下面的 `resolve()` 因此逐条走 ③（整读 + 重解析），\n  // 而**不装载、不对账、不写回** —— 正是修法 ② 要的那条口径。\n  const index = useIndex ? await ensureIndexRels(root) : new Map()\n  const nextIndex = new Map()\n  let readFiles = 0\n\n  /**\n   * 一条候选的取数判定（文档与代码共用；`isCode` 只决定读盘时走哪个解析器）。\n   * @param {string} abs - 绝对路径\n   * @param {string} rel - 工作区相对路径\n   * @param {object} st - 已取得的 stat\n   * @param {boolean} isCode - 是否代码\n   * @returns {Promise<object|null>} 条目\n   */\n  /** 本轮靠**进程内 `cache`** 复用的条数（v0.20 就有的能力，与索引复用分开报）。 */\n  let cached = 0\n\n  const resolve = async (abs, rel, st, isCode) => {\n    const key = verifyKey(root, rel)\n    const hit = cache.get(abs)\n    if (hit && hit.mtimeMs === st.mtimeMs && hit.size === st.size) {\n      // ① 进程内已解析过，且 mtime+size 未变 —— 一次盘都不读。\n      //    ⚠️ 它与 `reused`（靠索引还原）**分开计数**：v0.20/v0.21 就已经做到了\n      //    「同一进程内不重读」，而 v0.22 的收益在**跨进程重启**。混在一起报，\n      //    就会把旧能力算进这一版的成绩里。\n      indexVerified.add(key)\n      cached += 1\n      return hit\n    }\n    const stored = index.get(rel)\n    const plausible = !!stored\n      && typeof stored.headHash === 'string' && stored.headHash.length > 0\n      // v0.22 修法 ①：`refs` 必须真的在里面。v2 记录（存的是 `head`）与 v1 记录\n      // 都过不了这一关 ⇒ 当「没有可用记录」处理 ⇒ 本轮回退读盘并重建，\n      // 迁移不需要任何专用代码。少这一条，重启后关系投影会**静默少掉**。\n      && refsShapeOk(stored.refs)\n      && stored.mtimeMs === st.mtimeMs && stored.size === st.size\n    if (plausible) {\n      // ② 元信息一致 ⇒ **正文与头部都不读**，直接用索引还原。\n      //\n      //    这里就是这一版的立论：`mtime + size` 当**快速筛子**用（提示词 §4 允许），\n      //    而「筛过之后凭什么信」由两件事回答 ——\n      //      a) 每条记录都带 `headHash`，内容一旦变化，下一次抽验必然发现；\n      //      b) 每轮扫描抽验 `INDEX_VERIFY_PER_PASS` 条（`verifySampled()`），\n      //         把「同 mtime 同 size 的编辑」这类伪造在一个有界窗口内抓出来。\n      //    两者合起来才是「mtime/size 不是唯一证据」的落实 —— 不是让每次扫描都重读一遍\n      //    头部（那等于没省），而是**读到的那一份永远能被指纹复核**。\n      indexVerified.add(key)\n      reused.push({ abs, rel, isCode, record: stored })\n      return restoreFromIndex(stored)\n    }\n    // ③ 没有可用记录（或元信息就变了）—— 整读 + 重解析，并重算指纹。\n    indexVerified.add(key)\n    const meta = isCode\n      ? await readCodeFromDisk(abs, root, st)\n      : await readDocFromDisk(abs, st)\n    if (!meta) return null\n    readFiles += 1\n    return meta\n  }\n\n  /** 本轮「靠索引复用」的候选 —— 抽验的对象。 */\n  const reused = []\n\n  for (const abs of found.md) {\n    const st = await statOrNull(abs)\n    if (!st || !st.isFile()) continue\n    const rel = relative(root, abs).split(sep).join('/')\n    const meta = await resolve(abs, rel, st, false)\n    if (!meta) continue\n    if (meta.bodyTruncated) bodyTruncated += 1\n    docs.push({\n      kind: KIND_DOC,\n      path: abs,\n      rel,\n      name: abs.split(sep).pop(),\n      title: meta.title,\n      summary: meta.summary,\n      size: meta.size,\n      mtimeMs: meta.mtimeMs,\n      headHash: meta.headHash,\n      // v0.22 修法 ①：抽取后的引用列表（索引里存的就是它）。内部字段，不下发。\n      refs: meta.refs,\n      // 原文首部：`buildContextFor()` 抽引用关系用（v0.14）。内部字段，不下发。\n      // 索引复用来的条目这里是空串 —— 消费方必须优先读 `refs`。\n      head: meta.head,\n      // v0.20：整篇正文随记录走 —— 片段切分与 `matches` 的输入。\n      // 它是**内部字段**：`publicDoc()` 不转发正文，只转发派生出的行号与摘要。\n      body: meta.body,\n      bodyReady: !!meta.bodyReady,\n      bodyBytes: meta.bodyBytes,\n      bodyTruncated: meta.bodyTruncated,\n      haystack: { title: meta.hayTitle, summary: meta.haySummary, body: meta.hayBody },\n    })\n  }\n  docs.sort((a, b) => b.mtimeMs - a.mtimeMs)\n\n  // v0.19：代码条目与文档条目**形状完全一致**（同一个 `kind` 位、同一套 haystack、\n  // 同一批下游消费者）。差别只在 haystack 字段的语义 —— 见 `readCode`。\n  // 这不是「第二套数据模型」，就是同一套模型里多了一类 kind。\n  const code = []\n  for (const abs of found.code) {\n    const st = await statOrNull(abs)\n    if (!st || !st.isFile()) continue\n    const rel = relative(root, abs).split(sep).join('/')\n    const meta = await resolve(abs, rel, st, true)\n    if (!meta) continue\n    if (meta.bodyTruncated) bodyTruncated += 1\n    code.push({\n      kind: KIND_CODE,\n      path: abs,\n      rel,\n      name: abs.split(sep).pop(),\n      title: meta.title,\n      summary: meta.summary,\n      size: meta.size,\n      mtimeMs: meta.mtimeMs,\n      headHash: meta.headHash,\n      refs: meta.refs,\n      head: meta.head,\n      body: meta.body,\n      bodyReady: !!meta.bodyReady,\n      bodyBytes: meta.bodyBytes,\n      bodyTruncated: meta.bodyTruncated,\n      haystack: { title: meta.hayTitle, summary: meta.haySummary, body: meta.hayBody },\n    })\n  }\n  code.sort((a, b) => b.mtimeMs - a.mtimeMs)\n\n  // v0.22：**有界对账**。抽验「靠索引复用」的那些记录 —— 读头部、比指纹；对不上就\n  // 重读重解析并**就地改正刚刚交出去的那条记录**。每轮只抽 `INDEX_VERIFY_PER_PASS` 条，\n  // 游标轮转，于是整个工作区在一段有界的窗口内被核完，而单轮扫描的额外读盘是常数级的\n  // （提示词 §5⑤「必要时分批执行避免阻塞主交互」）。\n  const byRel = new Map()\n  for (const doc of docs) byRel.set(doc.rel, doc)\n  for (const doc of code) byRel.set(doc.rel, doc)\n  const sampled = sampleForVerify(root, reused)\n  let verified = 0\n  let repaired = 0\n  for (const item of sampled) {\n    if (!item) continue\n    let head = null\n    try {\n      const buf = await readFile(item.abs)\n      // ⚠️ 代码的头部口径是 `CODE_HEAD_BYTES`（8KB），文档是 `HEAD_BYTES`（16KB）。\n      // 用错长度算出来的指纹**永远对不上**（会让索引对代码彻底失效且不报错），\n      // 所以这一行必须与 `readDocFromDisk` / `readCodeFromDisk` 里那行逐字一致。\n      head = buf.subarray(0, item.isCode ? CODE_HEAD_BYTES : HEAD_BYTES).toString('utf8')\n    } catch {\n      continue\n    }\n    readFiles += 1\n    verified += 1\n    if (headHashOf(head) === item.record.headHash) continue\n    // 指纹不符 —— 元信息骗了我们。重读重解析，并改正这条记录。\n    const fresh = await statOrNull(item.abs)\n    if (!fresh || !fresh.isFile()) continue\n    const meta = item.isCode\n      ? await readCodeFromDisk(item.abs, root, fresh)\n      : await readDocFromDisk(item.abs, fresh)\n    if (!meta) continue\n    readFiles += 1\n    repaired += 1\n    const doc = byRel.get(item.rel)\n    if (!doc) continue\n    doc.head = meta.head\n    doc.refs = meta.refs\n    doc.title = meta.title\n    doc.summary = meta.summary\n    doc.size = meta.size\n    doc.mtimeMs = meta.mtimeMs\n    doc.headHash = meta.headHash\n    // ⚠️ 内容变了，抽取结果必然跟着变 —— 漏了这一个字段，修好的记录会把**旧引用**\n    // 写回索引，重启后关系与引用图就静默少了东西（而且看不出错）。\n    if (meta.refs) doc.refs = meta.refs\n    doc.body = meta.body\n    doc.bodyReady = true\n    doc.bodyBytes = meta.bodyBytes\n    doc.bodyTruncated = meta.bodyTruncated\n    doc.haystack = { title: meta.hayTitle, summary: meta.haySummary, body: meta.hayBody }\n    cacheSet(item.abs, meta)\n  }\n\n  const media = []\n  for (const item of found.media) {\n    const meta = await readMediaMeta(root, item)\n    if (meta) media.push(meta)\n  }\n  media.sort((a, b) => b.mtimeMs - a.mtimeMs)\n\n  // 这一轮算出的索引：**从刚刚交出去的记录本身**生成，所以抽验修好的那几条自动是正确值。\n  for (const doc of docs) nextIndex.set(doc.rel, recordFor(doc, doc.rel))\n  for (const doc of code) nextIndex.set(doc.rel, recordFor(doc, doc.rel))\n\n  // v0.22：把这一轮算出来的索引写回存储。**只写差量**（新增/更新那几条 + 抽验出的删除），\n  // fire-and-forget：写失败只影响「下次重启」，不影响本次结果，所以不 await\n  // —— 不为维护缓存去阻塞一次用户可见的检索（提示词 §4 最后一条）。\n  if (useIndex && indexRegistry) {\n    const diff = indexDiff(root, nextIndex, index)\n    indexRels.set(root, nextIndex)\n    indexStats.set(root, {\n      candidates: nextIndex.size,\n      readFiles,\n      cached,\n      reused: reused.length,\n      verified,\n      repaired,\n      put: diff.put.length,\n      del: diff.del.length,\n      skipped: false,\n      persisted: indexRegistry.persisted,\n      reason: indexRegistry.reason,\n    })\n    if (diff.put.length > 0 || diff.del.length > 0) {\n      indexRegistry.write(root, diff)\n    }\n  } else {\n    indexStats.set(root, {\n      candidates: nextIndex.size,\n      readFiles,\n      cached,\n      reused: reused.length,\n      verified,\n      repaired,\n      put: 0,\n      del: 0,\n      // 「这一轮没查索引」与「这个进程没有存储」是两件事，读数不能混成同一个 0。\n      skipped: !useIndex,\n      persisted: false,\n      reason: useIndex ? 'no-storage' : 'index-skipped',\n    })\n  }\n\n  return {\n    docs,\n    code,\n    media,\n    truncated: found.mdTruncated,\n    codeTruncated: found.codeTruncated,\n    mediaTruncated: found.mediaTruncated,\n    stats: { ...found.stats, bodyTruncated },\n    scanMs: found.scanMs,\n  }\n}\n\n/* ── 会话事件 → 对话文本 ────────────────────────────── */\n\n/**\n * 拼一条消息里所有 text block 的文字。\n * @param {object} message - UserMessage / AssistantMessage\n * @returns {string} 文本\n */\nfunction messageText(message) {\n  if (!message || !Array.isArray(message.content)) return ''\n  let out = ''\n  for (const block of message.content) {\n    if (block && block.type === 'text' && typeof block.text === 'string') out += `${block.text}\\n`\n  }\n  return out\n}\n\n/**\n * 把一段文本压成可显示的单行。\n * @param {string} text - 原始文本\n * @returns {string} 折叠空白后的文本\n */\nfunction tidyText(text) {\n  return String(text || '').replace(/\\s+/g, ' ').trim()\n}\n\n/**\n * 整条消息是否**只由应答词组成**（切成段后逐段查 `TASK_ACK`）。\n * @param {string} tidy - 已折叠空白的文本\n * @returns {boolean} 是否只是应答\n */\nfunction isAcknowledgementOnly(tidy) {\n  const parts = tidy.split(/[^\\p{L}\\p{N}]+/u).filter(Boolean)\n  if (parts.length === 0) return false\n  return parts.every((part) => TASK_ACK.has(part.toLowerCase()))\n}\n\n/**\n * 判断一条用户消息能不能当「任务」引用。\n *\n * 全部是确定性判定，没有任何主观打分：\n *   - 折叠空白后至少 2 个字符；\n *   - 至少含一个字母或汉字（纯数字 / emoji / 符号不算）；\n *   - 不能只是应答词（「继续」「好的」不是任务）。\n *\n * @param {string} text - 用户消息文本\n * @returns {boolean} 是否可作为 `task` 引用\n */\nfunction isSubstantiveTask(text) {\n  const tidy = tidyText(text)\n  if (tidy.length < 2) return false\n  if (!/\\p{L}/u.test(tidy)) return false\n  return !isAcknowledgementOnly(tidy)\n}\n\n/**\n * 把用户消息原文截成 `task` 字段的值。\n * @param {string} text - 用户消息文本\n * @returns {string} 截断后的单行文本\n */\nfunction taskText(text) {\n  const tidy = tidyText(text)\n  if (tidy.length <= TASK_MAX_CHARS) return tidy\n  return `${tidy.slice(0, TASK_MAX_CHARS - 1)}…`\n}\n\n/**\n * 取会话里最近的若干条人机对话文本（**最新在前**），外加当前任务的原文引用。\n *\n * 只收 `source.kind === 'user'` 的 user/message —— `agent.inject()` 塞进来的\n * 合成上下文（AGENTS.md、skill 内容、文件变更通知）不是用户意图，会把话题带偏。\n *\n * `task` 与用于检索的窗口**同源**：都只看最近 `CONV_MAX_MESSAGES` 条。这不是偷懒 ——\n * 让「右栏显示的任务」和「实际排序依据的对话」来自两个不同窗口，用户会对不上账。\n *\n * @param {object} session - 宿主会话对象\n * @returns {{texts: string[], seq: number, task: string}} 对话文本、最新事件 seq、任务原文\n */\nfunction recentConversation(session) {\n  let events\n  try {\n    events = session && typeof session.snapshotEvents === 'function' ? session.snapshotEvents() : null\n  } catch {\n    return { texts: [], seq: -1, task: '' }\n  }\n  if (!Array.isArray(events) || events.length === 0) return { texts: [], seq: -1, task: '' }\n\n  const texts = []\n  let seq = -1\n  let chars = 0\n  // 从新往旧扫，第一条通过 `isSubstantiveTask()` 的用户消息就是当前任务。\n  // 用**第一条**而不是最长的：任务会变，「现在在做什么」由最近那句说了算。\n  let task = ''\n\n  for (let i = events.length - 1; i >= 0 && texts.length < CONV_MAX_MESSAGES; i -= 1) {\n    const event = events[i]\n    if (!event || typeof event.type !== 'string') continue\n\n    let text = ''\n    if (event.type === 'user/message') {\n      const source = event.data && event.data.source\n      if (source && source.kind && source.kind !== 'user') continue\n      text = messageText(event.data)\n      if (!task && isSubstantiveTask(text)) task = taskText(text)\n    } else if (event.type === 'assistant/message') {\n      text = messageText(event.data && event.data.message)\n    } else {\n      continue\n    }\n\n    if (!text.trim()) continue\n    if (seq < 0) seq = event.seq\n\n    const sliced = text.slice(0, CONV_MESSAGE_CHARS)\n    texts.push(sliced)\n    chars += sliced.length\n    if (chars >= CONV_MAX_CHARS) break\n  }\n\n  return { texts, seq, task }\n}\n\n/**\n * 取一个会话当前的检索关键词与任务引用，按最新事件 seq 缓存。\n *\n * 两者一起缓存是因为它们**必须来自同一次读数** —— 分开缓存会在「用户刚说完一句话」\n * 的那个 5 秒轮询里出现「词已经更新、任务还是上一句」的错位。\n *\n * @param {object} session - 宿主会话对象\n * @param {string} sessionId - 会话 id（缓存键）\n * @returns {{keywords: Array<{term:string,weight:number}>, task: string}} 关键词表与任务原文\n */\nfunction conversationFor(session, sessionId) {\n  const { texts, seq, task } = recentConversation(session)\n  const hit = convCache.get(sessionId)\n  if (hit && hit.seq === seq) return hit\n\n  const keywords = extractKeywords(texts, 30)\n  const entry = { seq, keywords, task }\n  convCache.set(sessionId, entry)\n  return entry\n}\n\n/* ── 对外载荷 ───────────────────────────────────────── */\n\n/**\n * 剥掉内部字段，得到发给浏览器的文档记录。\n *\n * ⚠️ `raw` 与 `matchedTerms` **必须**留在这里被剥掉（v0.14）：它们是上下文装配的\n * 内部输入，泄漏出去就等于对外给了一套第二分数（`test/host.test.mjs` 有守卫）。\n *\n * @param {object} doc - 内部文档记录\n * @returns {object} 公开记录\n */\nfunction publicDoc(doc) {\n  const out = {\n    kind: doc.kind || KIND_DOC,\n    path: doc.path,\n    rel: doc.rel,\n    name: doc.name,\n    title: doc.title,\n    summary: doc.summary,\n    size: typeof doc.size === 'number' ? doc.size : null,\n    mtimeMs: doc.mtimeMs,\n    score: typeof doc.score === 'number' ? doc.score : null,\n  }\n  // v0.20：命中片段（§11）。只下发**派生结果** —— 行号区间、命中词、片段摘要；\n  // `body` 与 `passage.text` 一律不出宿主（§16：不准把大文件正文塞进载荷）。\n  // 没有片段的记录**不带这个键**（v0.19 的响应形状因此逐字不变）。\n  if (Array.isArray(doc.matches) && doc.matches.length > 0) out.matches = doc.matches\n  return out\n}\n\n/**\n * 组装一次列表扫描结果。\n *\n * @param {string} root - 工作区根\n * @param {number} limit - 最多返回多少条\n * @param {{session?: object, sessionId?: string, sort?: string, kind?: string, query?: string}} options -\n *   排序上下文；`kind` 为 `doc`（默认，仅 Markdown）、`media`（仅图片/视频）或 `all`；\n *   `query` 非空时**用它排序，而不是用当前对话**（v0.7 的 agent 工具走这条路）；\n *   HTTP 路由不传 `query`，所以 `/knit/api/recent` 的行为逐字不变\n * @returns {Promise<object>} 给浏览器的载荷。\n *   ⚠️ **不要把这个对象直接 `sendJson`** —— 它现在带一个 `ranked` 键（全量名次，\n *   含 `raw` 与 `matchedTerms`），是给 `buildContextFor()` 用的**内部输入**。\n *   HTTP 路由必须走 `publicScanPayload()`（`test/host.test.mjs` 有守卫）。\n */\n/**\n * 进程内的固定 / 排除状态（v0.21）。\n *\n * `apply(ctx)` 里若拿得到 `ctx.storage` 就换成**带持久化**的那份；拿不到时这份内存态\n * 照常工作，只是活不过这次进程 —— 面板必须把这件事说出来（`control.persisted`）。\n */\nlet controlRegistry = createControlRegistry(null)\n\n/**\n * v0.23 · 进程内的语义引擎（`apply()` 拿到 `ctx.storage` 时换成带持久化配置的那份）。\n *\n * ⚠️ **只持久化配置**；向量活在 `semantic.js` 的进程内有界缓存里 —— 持久化向量与\n * 「有界增量嵌入」是 Phase B 的事（方案 §6）。\n */\nlet semanticEngine = createSemanticEngine({ store: null })\n\n/**\n * v0.25 · 进程内的 Git 读取器。**只有 `changes=1` 那一轮才会真的去跑 git** ——\n * 默认关闭意味着默认这条路上一个进程都不 spawn（用户需求 §三.3 的「不悄悄改变基础检索行为」）。\n * 缓存（8 秒）与「不是仓库」的负缓存都在它内部，见 `git.js`。\n */\nconst gitReader = createGitReader()\n\n/**\n * v0.23 Phase A：跑一轮**有界**语义候选。\n *\n * 三条不会变的行为（判据 1 / 5 / 7）：\n *   · 词法模式 ⇒ **一次 provider 调用都不发**（`available` 老实回 `null`：本轮没探测过）；\n *   · 任何失败 ⇒ 收敛成一个 `reason`，**绝不抛**（语义层坏了不许带坏检索）；\n *   · Phase A 只**数**候选，不往 `pool` 里塞任何东西 ⇒ 面板与工具载荷逐字不变。\n *\n * @param {string} root - 工作区根\n * @param {{retrieval: string, keywords: string[], task: string, docs: Array<object>}} input\n * @returns {Promise<object>} 语义状态行\n */\nasync function semanticPassFor(root, input) {\n  const status = await semanticEngine.ready()\n  const requested = input.retrieval === 'hybrid' ? 'hybrid' : 'lexical'\n  // ⚠️ v0.23 修订（2026-10-11）：**时间序下这一层整个不适用**。\n  // 判据在代码里：`contextPayload()` 要求 `sort === 'relevance'` 才产出 Context Pack\n  // （`contextPayload()` 的第一行），所以时间序**根本没有分层结构**，语义标记没有消费者；\n  // 而这一轮如果照跑，就是「白花 provider 调用 + 界面上还显示成可用」。\n  // ⇒ 直接如实回 `not-applicable`，**不探测、不嵌入**（判据 1 的同一条纪律：不该花的钱一分不花）。\n  if (requested === 'hybrid' && input.applies !== true) {\n    return {\n      mode: 'lexical', requested, configured: status.configured, available: null,\n      reason: 'not-applicable', candidates: 0, provider: status.provider, rels: [],\n    }\n  }\n  if (requested !== 'hybrid') {\n    return {\n      mode: 'lexical', requested, configured: status.configured, available: null,\n      reason: null, candidates: 0, provider: status.provider, rels: [],\n    }\n  }\n  // ⚠️ 2026-10-11（Phase C 量尺发现）：查询文本必须是**用户原话**。\n  // 原来的顺序是 `task || keywords.join(' ')` —— 显式 `query` 路径（`knit_docs(query=…)`）下\n  // `task` 是空的，于是拿去做嵌入的是 `extractKeywords()` **去重叠后的 3-gram 碎片**\n  // （实测 `失效策略怎么定` → `[\"失效策\",\"效策略\"]`），语义那条路的质量因此明显更差。\n  // 现在由调用方按「原话优先」传 `queryText`：显式 query > 会话原话 > 关键词（最后兜底）。\n  const query = (input.queryText && String(input.queryText).trim())\n    || (input.task && String(input.task).trim())\n    || (Array.isArray(input.keywords) ? input.keywords.join(' ') : '')\n  try {\n    const result = await semanticEngine.pass({ root, query, docs: input.docs })\n    // ⚠️ `mode` 报的是**实际生效**的模式，不是「你要的那个」：\n    // 只有语义那一轮真的跑成功（`available === true`）才算 `hybrid`；\n    // 没配置 / 探测失败 / 超时 / 形状不对一律**如实回 `lexical`** 并带上 `reason`\n    // —— 判据 5 的「不许伪装成混合成功」在宿主这一侧就是这一行。\n    const ok = result.available === true\n    return {\n      mode: ok ? 'hybrid' : 'lexical',\n      requested,\n      configured: !!result.provider,\n      available: ok,\n      reason: ok ? null : (result.reason || 'unavailable'),\n      candidates: ok ? result.candidates : 0,\n      provider: result.provider,\n      rels: ok ? result.rels : [],\n    }\n  } catch {\n    return {\n      mode: 'lexical', requested, configured: true, available: false,\n      reason: 'bad-response', candidates: 0, provider: status.provider, rels: [],\n    }\n  }\n}\n\n/**\n * 把上面那一行压成**可以下发**的形状：`rels` 是内部输入（Phase B 要用），不下发。\n * @param {object} row - `semanticPassFor()` 的产物\n * @returns {object} 公开字段\n */\nfunction publicSemantic(row) {\n  return {\n    mode: row.mode,\n    requested: row.requested,\n    configured: !!row.configured,\n    available: row.available === null ? null : !!row.available,\n    reason: row.reason || null,\n    candidates: Number(row.candidates) || 0,\n    provider: row.provider || null,\n  }\n}\n\nexport async function scan(root, limit, options = {}) {\n  // v0.19 修订：**扫的是展开符号链接后的那份路径**。\n  // 每条记录里的 `path`（`publicDoc()` 原样下发给客户端）就是「打开 / 定位」时\n  // 交给宿主的路径，而 DSH 只认 realpath（见 `hostPathOf()`）—— 跟着会话的\n  // 符号链接走一遍，客户端拿到的 `path` 直接可用，不必等 `/api/doc` 回来再校正。\n  // ⚠️ `rel` 用同一个 base 算，所以相对路径一字不变；对外的 `root` 仍是会话\n  // 原本那条（界面显示用），canonical 的那份单独放在 `hostRoot`。\n  const hostRoot = hostPathOf(root)\n\n  // v0.22 修法 ②：**先算出这一轮要不要正文，再决定查不查索引**（2026-10-10）。\n  //\n  // 判据只有一条：`mode === 'relevance'` —— 排序改成「相关」**并且**真的抽到了关键词。\n  // 那时 `rankByRelevance()` 必须拿到全部正文，索引复用在那种情形下是净开销（见\n  // `collectDocs()` 里的长注释）。时间序（含「按相关排序但一个关键词都没抽到」）\n  // 完全吃索引里的 `title` / `summary` / 有界正文派生字段 —— 那才是索引的收益点。\n  // 这一段原来在 `collectDocs()` 之后；挪上来只为把 `mode` 先算出来，判定规则一字未动。\n  const wantRelevance = options.sort === 'relevance'\n  const sessionId = options.sessionId || ''\n  let keywords = NO_KEYWORDS\n  let mode = 'time'\n  let matched = []\n  // 当前任务的**原文引用**（SDD §12）。只在「对话驱动」这条路上有值：\n  // 显式 query 路径下模型自己知道在问什么，把 query 当「任务」是编的。\n  let task = ''\n  // v0.23：给语义通道的**查询原话**（显式 query 或会话里那条用户消息）。\n  // 与 `task` 分开：`task` 是「包引用的任务原文」，这里是「拿去嵌入的文本」。\n  let queryText = ''\n\n  if (wantRelevance) {\n    // 调用方给了明确的 query（v0.7 的 agent 工具走这条路）：把它当成**一条最新的消息**，\n    // 于是走的是完全相同的抽取与门槛规则，不引入第二条抽取路径。\n    // 不进 convCache —— 那个缓存按 session seq 键控，塞 query 进去会互相污染。\n    const explicitQuery = typeof options.query === 'string' ? options.query.trim() : ''\n    if (explicitQuery) {\n      keywords = extractKeywords([explicitQuery], 30)\n      // v0.23：语义那一层要的是**原话**，不是抽完的碎片（见 `semanticPassFor()` 的注释）。\n      queryText = explicitQuery\n    } else {\n      const conv = conversationFor(options.session, sessionId)\n      keywords = conv.keywords\n      task = conv.task\n      queryText = conv.task\n    }\n    // 没有对话可依据时老实退回时间序，而不是假装排了个序\n    mode = keywords.length > 0 ? 'relevance' : 'time'\n  }\n\n\n  const collected = await collectDocs(hostRoot, { index: mode !== 'relevance' })\n\n  // 默认 doc：旧版客户端 / 悬停浮层不带 kind，行为与「只列 Markdown」时完全一致。\n  //\n  // v0.19 的 `kind` 取值集合（**唯一权威**，HTTP 与工具都从这里取）：\n  //   `doc`     仅 Markdown（默认，v0.18 行为逐字不变）\n  //   `code`    仅代码（v0.19）\n  //   `media`   仅图片/视频（v0.18 行为逐字不变）\n  //   `all`     文档 + 代码 + 媒体（面板「全部」档；v0.18 是「文档 + 媒体」，只多不少）\n  //   `context` **内部**语料：文档 + 代码。不给 HTTP —— agent 工具的 Context Pack\n  //             要在「文档与代码混合竞争」上排序（需求 §34 Case C），而媒体不进上下文，\n  //             所以它不能复用 `all`（那会把媒体也塞进候选）。\n  const kind = options.kind === 'all' || options.kind === 'media'\n    || options.kind === 'code' || options.kind === 'context'\n    ? options.kind\n    : 'doc'\n  let pool\n  let truncated\n  if (kind === 'media') {\n    pool = collected.media\n    truncated = collected.mediaTruncated\n  } else if (kind === 'code') {\n    pool = collected.code\n    truncated = collected.codeTruncated\n  } else if (kind === 'context') {\n    pool = collected.docs.concat(collected.code).sort((a, b) => b.mtimeMs - a.mtimeMs)\n    truncated = collected.truncated || collected.codeTruncated\n  } else if (kind === 'all') {\n    pool = collected.docs.concat(collected.code, collected.media)\n      .sort((a, b) => b.mtimeMs - a.mtimeMs)\n    truncated = collected.truncated || collected.codeTruncated || collected.mediaTruncated\n  } else {\n    pool = collected.docs\n    truncated = collected.truncated\n  }\n\n  // v0.21（D7）：**排除发生在检索之前**。用户排掉的文件根本不进候选集 ——\n  // 于是它不参与排序、不计入 `matched`、不出现在任何一层，也不进工具输出。\n  // 这一步是「用户的话比排序算法更硬」的唯一实现点，所以放在最前面。\n  // 显式传入的 `excluded` 优先（测试与内部调用用），否则问进程内的控制状态。\n  const excluded = options.excluded instanceof Set\n    ? options.excluded\n    : excludedSet(controlRegistry.controlOf(root))\n  let controlSkipped = 0\n  /** 被排除的 rel 里，**工作区里真的还有**的那些（面板据此决定给不给「恢复」）。\n   *  按 `collected`（**尚未按 kind 过滤**）判：切到代码档时那篇被排除的 Markdown\n   *  只是不在本档语料里，文件并没有消失，不该把「恢复」也一起收掉。\n   *  面板要的是「这一篇我还能不能找回来」，不是「它在这档里吗」。 */\n  let controlAlive = null\n  if (excluded.size > 0) {\n    const before = pool.length\n    pool = pool.filter((doc) => !excluded.has(doc.rel))\n    controlSkipped = before - pool.length\n    controlAlive = new Set()\n    for (const doc of collected.docs.concat(collected.code, collected.media)) {\n      if (excluded.has(doc.rel)) controlAlive.add(doc.rel)\n    }\n  }\n\n  // ── v0.23：可选混合检索（Phase A）────────────────────────────────\n  //\n  // 位置是**刻意的**，两处都不能挪（方案 §3）：\n  //   · 在**排除之后** ⇒ 被排除的文件不可能经语义路径回来（判据 3）；\n  //   · 在 `rankByRelevance()` **之前** ⇒ 与未来 Phase B 的融合点一致。\n  // Phase A 只算候选数、如实报告可用性 —— **不往 `pool` 里塞东西**（判据 2：载荷不变）。\n  const semantic = await semanticPassFor(root, {\n    retrieval: options.retrieval === 'hybrid' ? 'hybrid' : 'lexical',\n    // 只有相关序才有 Context Pack（`contextPayload()` 的判据）⇒ 时间序下语义不适用。\n    applies: mode === 'relevance',\n    // 嵌入用的查询文本：**原话优先**（显式 query > 会话原话 > 关键词碎片兜底）。\n    queryText,\n    keywords,\n    task,\n    docs: pool,\n  })\n\n  // v0.23 Phase B：把这一轮的语义候选**标进池子**（只标记 —— 不排序、不抬层、不改名次）。\n  // 与词法同时命中的条目也照标：`context.js` **只在 `raw === 0` 时**才认这个标记，\n  // 所以「有词法证据的仍按词法规则分层」是结构性保证，不靠纪律。\n  // ⚠️ `pool` 里的对象就是后面 `rankByRelevance()` / `publicDoc()` 看到的那些；\n  // `publicDoc()` 是白名单投影，所以这个标记**不会**下发到浏览器。\n  if (semantic.mode === 'hybrid' && semantic.rels.length > 0) {\n    const semanticRels = new Set(semantic.rels)\n    for (const doc of pool) if (semanticRels.has(doc.rel)) doc.semantic = true\n  }\n\n  let ordered\n  let topic = ''\n  if (mode === 'relevance') {\n    // v0.22：相关检索必须拿到**正文**（打分、片段、逐词字频都读它）。从索引还原出来的\n    // 条目没有正文（裁决 A），这里按需补齐 —— 只补真的会参与打分的那批，而且是整读。\n    //\n    // ⚠️ 放在 `rankByRelevance()` **之前**，不是之后：没有正文的条目会让 BM25 的\n    // `avgdl` 与 `df` 一起偏小，名次与「索引开/关」两份结果就对不上了。顺序在这里是\n    // 正确性问题，不是性能问题。\n    await hydrateBodies(pool, hostRoot)\n    // 一个 `now` 贯到底（打分与片段用同一个时间基准）—— 同一批输入两次跑出的\n    // 结果因此逐字相同（§20 的确定性要求）。\n    const now = Date.now()\n    const ranked = rankByRelevance(pool, keywords, now)\n    ordered = ranked.docs\n    // v0.20（D5）：给每条命中记录附上逐词的「单窗口内最大字频」。\n    // 分层闸门 `isDocHit` 原来用**整篇**字频，而整篇字频会随文件变长而虚高 ——\n    // 窗口一开，29000 字的 CHANGELOG 就能对**每个**任务满足闸门（需求 §9 明令禁止）。\n    // 这一步只算「正文真的命中」的词，成本是几次 `indexOf`，不改名次、也不进 payload。\n    for (const doc of ordered) {\n      const tf = passageTfOf(doc)\n      if (tf) doc.passageTf = tf\n    }\n    // v0.20：给排名最前的 `PASSAGE_WINDOW` 条挂上命中片段（§11）。\n    // ⚠️ 这一步**不改名次**：片段是文件名的投影（实现说明 D3）。\n    // 窗口之外的记录只是「没有片段」，不是「不相关」—— `limit` 才管分页，\n    // 这里是宿主侧的成本上限（切段是 O(全文)，不该为 400 篇文件各做一遍）。\n    // `rankByRelevance` 返回的是浅拷贝，所以挂 `matches` 不会污染 `pool`。\n    const stop = Math.min(ordered.length, PASSAGE_WINDOW)\n    for (let i = 0; i < stop; i++) {\n      const matches = passageMatchesFor(ordered[i], keywords, now)\n      if (matches.length > 0) ordered[i].matches = matches\n    }\n    // 话题标签用 `label`（把命中词的**原文区间合并**后的可读结果），不是 `matched`。\n    // 后者是「语料里真实存在的词」，但仍可能是一堆碎片：\n    // 「项目文档」的候选是 `项目文` / `目文档`，直接显示就成了「按「目文档、项目文」排序」。\n    // `keywords` 字段保持语义不变，仍然是那批真实存在的词。\n    topic = topicLabel(ranked.label)\n    matched = ranked.matched\n  } else {\n    ordered = pool.map((doc) => ({ ...doc, score: null }))\n  }\n\n  const out = {\n    ok: true,\n    root,\n    // v0.19 修订：`root` 是会话自己那条路径（可能含符号链接，用于显示）；\n    // `hostRoot` 是同一目录展开链接后的 canonical 路径，**只给「打开 / 定位」用** ——\n    // 宿主只认 realpath 形态，理由见 `hostPathOf()`。\n    hostRoot,\n    kind,\n    total: ordered.length,\n    truncated,\n    sessionId,\n    mode,\n    topic,\n    keywords: mode === 'relevance' ? matched.slice(0, 8) : [],\n    // 全量名次（未按 limit 切片）。**只给上下文装配用**，由 `publicScanPayload()` 剥掉。\n    // 放在这里而不是让调用方再扫一遍，是 §二十「不要为了 Context Pack 再扫描一次\n    // 整个 Workspace」那条要求的实现：这里复用同一次 `rankByRelevance` 的结果。\n    ranked: mode === 'relevance' ? ordered : [],\n    // 任务原文。**也不下发**（由 `publicScanPayload()` 一并剥掉）—— 它只喂装配层与右栏。\n    // 剥掉不是为了保密（这是用户自己刚说过的话），而是为了不动 v0.13 的响应形状：\n    // `context.task` 已经把这个值带出去了，顶层再来一份是重复。\n    task: mode === 'relevance' ? task : '',\n    // v0.23：检索模式 + 语义可用性 / 回退原因 / 有界候选数。**只计数、不进包**。\n    semantic: publicSemantic(semantic),\n    docs: ordered.slice(0, limit).map(publicDoc),\n    // 全量列表（未按 limit 切片）。**内部输入**：v0.17 的 lifecycle 需要「被读过但\n    // 不一定落在当前页」的文档的当前 mtime。由 `publicScanPayload()` 剥掉。\n    allDocs: ordered,\n    // v0.25：**文档 + 代码**那一份语料（与类型档无关）。Git 变更关联要在「文档 ↔ 代码」\n    // 之间找证据（`documents` / `imports` / `tests` 三类都跨档），而面板的档位把语料切开了；\n    // 所以这里多带一份**不分档**的候选集给它。它只是一组引用（记录本身已在 `allDocs` 里），\n    // 由 `publicScanPayload()` 剥掉，不下发。\n    contextCorpus: collected.docs.concat(collected.code),\n    // v0.19 扫描计数（需求 §50 要报的那几个数：见到的 / 准入的 / 被排除的 / 生成噪声）\n    // 加上 `corpusSize`（本档语料的实际大小，即 `allDocs.length`）。\n    // **内部输入**，由 `publicScanPayload()` 剥掉 —— HTTP 响应形状一个键都不加。\n    stats: {\n      ...collected.stats, scanMs: collected.scanMs, corpusSize: ordered.length, controlSkipped, controlAlive,\n      // v0.23：带 `rels` 的那一份**只在内部**（装配层 / 测试用）。\n      semantic,\n    },\n  }\n  // v0.25：记一份给独立接口复用（见 `corpusForChanges`）。**只写不读**，扫描语义不变。\n  scanMemoState = { root, at: Date.now(), payload: out }\n  return out\n}\n\n/**\n * **最近一次扫描**的备忘（v0.25）。\n *\n * 存在的唯一理由是：Git 变更关联现在走**独立接口** `/knit/api/changes`，而它需要与\n * `/api/recent` **同一份**工作区语料。如果它自己再 `scan()` 一次，一轮轮询就会\n * **走两遍目录树**——那正是「不得因为两个请求重复扫描整个工作区」要禁掉的事。\n *\n * ⚠️ 这份备忘**只被独立接口读**，`scan()` 自己从不读它 ⇒ 扫描的语义一个字节没变\n * （同一进程里连续两次 `scan()` 依旧各自真扫，增量索引那套测试的前提因此不被动摇）。\n * TTL 与 `git.js` 的 `GIT_CACHE_TTL_MS`（8 s）**同窗**：一个快照窗口 = 一次扫描 + 一次 git。\n */\nconst SCAN_MEMO_TTL_MS = 8000\nlet scanMemoState = null\n\n/** 仅供测试：读当前备忘（`null` = 没有可复用的扫描）。 */\nexport function scanMemo() {\n  if (!scanMemoState) return null\n  if (Date.now() - scanMemoState.at > SCAN_MEMO_TTL_MS) return null\n  return { root: scanMemoState.root, at: scanMemoState.at }\n}\n\n/** 仅供测试：清掉备忘，好把「复用」与「真扫」两条路分开断言。 */\nexport function resetScanMemo() {\n  scanMemoState = null\n}\n\n/**\n * 仅供测试：清掉 **git 状态缓存**。\n *\n * 与 `resetScanMemo()` 配对使用：只证明「缓存热的时候看不见变化」是不够的 ——\n * 还要证明「缓存冷了变化就出现」。两条合起来才说明那个「看不见」是缓存造成的，\n * 而不是接口本来就对文件增删无感。\n */\nexport function resetGitReaderCache() {\n  gitReader.reset()\n}\n\n/**\n * 独立接口要的那份语料：**优先复用最近一次扫描**，没有（或过期）才真扫一遍。\n *\n * @param {string} root - 工作区根\n * @param {object} fallback - 真扫时用的参数（与 `/api/recent` 同一组：同参数才能命中同一份语料）\n * @returns {Promise<object>} `scan()` 的完整载荷\n */\nexport async function corpusForChanges(root, fallback) {\n  const memo = scanMemoState\n  if (memo && memo.root === root && Date.now() - memo.at <= SCAN_MEMO_TTL_MS) return memo.payload\n  return scan(root, fallback.limit, fallback.options)\n}\n\n/**\n * 把 `scan()` 的载荷压成**可以发给浏览器/模型**的那一份。\n *\n * 存在的唯一理由是 `ranked`（全量名次、含 `raw` 与 `matchedTerms`）必须被剥掉 ——\n * 它是装配层的内部输入，发出去就等于对外给了一套第二分数，而且响应体会大好几倍。\n * `task` 同理：装配层已经把它放进 `context.task` 了。\n * HTTP 路由与 agent 工具都只许返回这个函数的产物。\n *\n * @param {object} payload - `scan()` 的产物\n * @returns {object} 公开载荷（与 v0.13 逐字一致，外加 v0.14 的 `context`）\n */\nexport function publicScanPayload(payload) {\n  if (!payload || typeof payload !== 'object') return payload\n  const { ranked, task, allDocs, contextCorpus, stats, ...rest } = payload\n  void ranked\n  void task\n  void allDocs\n  void contextCorpus\n  void stats\n  return rest\n}\n\n/**\n * 按需建引用图。\n *\n * `withLinks` 为假时**连图都不建** —— 媒体档 / 时间序 / 悬停浮层的条数不需要分层，\n * 不该为它们读全库（这是 §二十「不要为了 Context Pack 再扫描一次整个 Workspace」\n * 那条要求的一半；另一半是复用 `rankByRelevance` 已经算好的名次与命中词）。\n *\n * `read` 用文档记录上现成的 `head`（`collectDocs` 解析 title / summary 时已经读过\n * 同样的 16KB）—— **零额外 I/O**。代价是只看头部 16KB，长文档尾部的引用会漏，\n * 但那只影响「哪些邻居进 Supporting」，不影响任何一篇的名次。\n *\n * v0.19：**入图的一律只看 Markdown**（`buildLinkGraph` 自己也只认 `.md` 目标）。\n * 代码不进图有两个理由，都不是洁癖：\n *   1. 引用图是 `.md` 与 `.md` 之间的关系（`links.js` 的解析规则就是为中文文档语料\n *      量出来的）。把代码的正文塞进这个索引没有语义，只会让 basename 歧义变多。\n *   2. 更重要的是**不能给代码开一条新的入围路径**。代码进 Supporting 的唯一正当理由\n *      应当是「任务检索命中了它」；如果它还能靠「正文里恰好写了一句 `docs/X.md`」\n *      进 Supporting，那就成了「因为它是代码所以特别」的反面 —— 一条不打分的后门。\n *\n * @param {string} root - 工作区根\n * @param {boolean} withLinks - 是否要引用关系\n * @param {Map<string, object>} byRel - 本次扫描到的产物（按 rel）\n * @returns {Promise<object|null>} 图或 null\n */\nasync function linkGraphFor(root, withLinks, byRel) {\n  if (!withLinks) return null\n  try {\n    return await buildLinkGraph(root, {\n      list: async () => ({\n        docs: [...byRel.values()].filter((doc) => doc.kind === KIND_DOC),\n        truncated: false,\n      }),\n      read: async (_root, rel) => {\n        const entry = byRel.get(rel)\n        if (!entry) return { ok: false }\n        // v0.22 修法 ①：索引复用来的条目没有原文首部（`head` 是空串），所以\n        // **正常不会走到这里** —— `links.js` 优先吃条目上的 `refs.md`（抽取结果），\n        // 只有那条路没有时才回来要文本。保留这条分支是给「列表方与读取方不是同一份数据」\n        // 的调用方用的（单测的假条目就是这种）。\n        if (typeof entry.head !== 'string') return { ok: false }\n        return { ok: true, text: entry.head }\n      },\n    })\n  } catch {\n    // 图建不起来只是少一个上下文信号 —— 分层退化成「只看命中」，不报错。\n    return null\n  }\n}\n\n/**\n * 装配一个工作区的 Context Pack（v0.14）。\n *\n * 顺序固定：`collect → relevance → links → context assembly`，四步复用同一批结果。\n * `ranked` 为空时**不读盘**（媒体档 / 时间序走的就是这条），直接返回空包。\n *\n * @param {string} root - 工作区根\n * @param {{ranked?: Array<object>, topic?: string, task?: string, total?: number, withLinks?: boolean, withRelations?: boolean}} [options] -\n *   `ranked` 是 `scan()` 里的全量名次（含 `raw` 与 `matchedTerms`）；\n *   `task` 是当前任务的**原文引用**，原样透传给 `buildContext()`，这里不生成也不改写；\n *   `withRelations: false` 关掉 v0.21 的关系投影（默认开）\n * @returns {Promise<object>} Context Pack\n */\nexport async function buildContextFor(root, options = {}) {\n  const ranked = Array.isArray(options.ranked) ? options.ranked : []\n  const total = Number.isInteger(options.total) ? options.total : ranked.length\n  const task = typeof options.task === 'string' ? options.task : ''\n  const empty = () => buildContext({ ranked: [], topic: options.topic || '', task, total })\n  if (ranked.length === 0) return empty()\n\n  const byRel = new Map()\n  for (const doc of ranked) {\n    if (doc && doc.rel) byRel.set(String(doc.rel), doc)\n  }\n\n  const graph = await linkGraphFor(root, options.withLinks !== false, byRel)\n  // v0.21：关系事实表。与引用图**分开**算（图只吃 Markdown，关系要认 md→代码、代码→代码、\n  // 测试↔被测），也分开缓存。候选集是**整批名次**，不是「已进包的条目」——\n  // 一条 `in` 边的源可能没进包（比如 AGENTS.md 引用 Primary），那正是要展示的「为什么」。\n  // `withRelations: false` 是**关掉关系投影**的开关（默认开）。有了它，「关系不改变任何一层」\n  // 这句话才能被一条测试直接证伪（同一次调用、只差这一个选项）。\n  const facts = options.withRelations === false ? null : buildRelationFacts(byRel, { root })\n  const pack = buildContext({\n    ranked, topic: options.topic || '', task, total, graph,\n    relations: facts ? facts.incident : null,\n  })\n  // v0.21（D7）：**固定发生在装配之后**。被固定的条目从三层**移出**、进入独立的\n  // 「固定上下文」区（`pack.pinned`，来源 `manual`）—— 三层的连续编号规则因此一个字不动。\n  // 条目只从这一包现成的行里取，零新 I/O；固定了一篇但这一批里没有它，**不硬凑**。\n  // 显式传入的 `control` 优先（测试用），否则问进程内的控制状态 —— 与 `scan()` 同一条口径。\n  const withPin = applyPinOverride(pack, options.control || controlRegistry.controlOf(root))\n  // ⚠️ v0.25（第二轮修订）：**变更关联不在这里**。它不再往 Context Pack 里挂任何东西 ——\n  // 「三层 + 固定区」就是这个函数的全部产出，与 v0.24 逐字相同（有测试守着）。\n  // 变更关联走**独立的 `/knit/api/changes` 接口**（`changesPayload()`），\n  // 因为它是「另一个问题的答案」，不是这一份包的第四条目录。\n  return withPin\n}\n\n/**\n * v0.25 · **Git 变更关联**：独立接口 `/knit/api/changes` 的载荷构造函数。\n *\n * 它**不碰** Context Pack：不改三层、不改固定区、不改编号、不改排序 —— 那份包由\n * `buildContextFor()` 原样产出，两条路径唯一的交汇点是「同一个工作区扫描结果」与\n * 「同一张关系事实表」。\n *\n * **数据结构是专用的**（不是 Context Pack 条目，也不复用 `provenance` / `reason` 那套词汇）：\n *\n * ```\n * { ok, root, hostRoot, mode: 'changes',\n *   git:   { available, reason, filesTotal, truncated, files: [{rel, kinds[], origRel?}] },\n *   links: [ { target,            // 关联目标（工作区相对路径）\n *              kind, source,       // 目标自身的分类（宿主给，客户端不看扩展名）\n *              title, summary, mtimeMs,\n *              evidence: [ { origin,   // **变更起点**：牵出这条关联的那个被改过的文件\n *                            type,     // 关系类型：references | imports | tests | documents\n *                            dir,      // 方向（见下）：相对**目标**而言\n *                            line } ], // **真实存在时**才给行号；`tests` 是文件名约定 ⇒ null\n *              evidenceTotal, types } ],\n *   linksTotal, unresolved: [rel], outOfScope: [rel] }\n * ```\n *\n * ⚠️ `dir` 是必需的第五个字段，不是冗余：没有它，「`src/foo.ts` 与 `docs/guide.md` 之间的\n * `documents` 边」读起来会分不清**谁提到谁**（`dir='in'` = 起点指向目标；`dir='out'` = 目标\n * 指向起点）。它与 v0.21 行级证据里的 `dir` 逐字同源，所以客户端**不需要第二条渲染路径**。\n *\n * @param {string} root - 工作区根\n * @param {{corpus: Array<object>, changeSet?: object, gitReader?: object}} input\n *   `corpus` = `scan()` 给的**不分档**候选集（文档 + 代码）；`changeSet` 只在测试里注入\n * @returns {Promise<object>} 这个接口的完整载荷（**任何情况下都不抛**）\n */\nexport async function changesPayload(root, input = {}) {\n  const corpus = Array.isArray(input.corpus) ? input.corpus : []\n  const reader = input.gitReader && typeof input.gitReader.read === 'function' ? input.gitReader : gitReader\n  const changeSet = input.changeSet && typeof input.changeSet === 'object'\n    ? input.changeSet\n    : await reader.read(root)\n  const git = {\n    available: changeSet.available === true,\n    reason: changeSet.reason || null,\n    // 面板要说的第一句话是「你改了几个文件」。给出的是**解析后**的条数（截断时另标 truncated）。\n    filesTotal: Number(changeSet.filesTotal) || 0,\n    truncated: changeSet.truncated === true,\n    files: (Array.isArray(changeSet.files) ? changeSet.files : []).slice(0, MAX_REPORTED_FILES)\n      .map((f) => ({ rel: f.rel, kinds: Array.isArray(f.kinds) ? f.kinds : [], ...(f.origRel ? { origRel: f.origRel } : {}) })),\n  }\n  // ⚠️ 载荷里**不带 `root` / `hostRoot`**：它们是绝对文件系统路径，而客户端只用工作区相对\n  // 路径就能定位每一篇（`target` / `origin` 都是 rel）。面板要从别处拿根路径就去问\n  // `/api/recent`（它本来就有）—— 关联接口不重复暴露一遍绝对路径。\n  const shell = { ok: true, mode: 'changes', git, links: [], linksTotal: 0, unresolved: [], outOfScope: [] }\n  if (!git.available) return shell\n\n  const corpusRels = new Set(corpus.map((d) => String(d.rel)))\n  const docOf = new Map(corpus.map((d) => [String(d.rel), d]))\n  const { seeds, gone, outside, seedRels } = splitSeeds(changeSet, corpusRels)\n  // ⚠️ 种子要**带上 `gone`**：删掉的测试文件照样牵着它的被测文件（那正是要答的问题），\n  // 只是它自己不能当结果（`corpusRels` 里没有它）。\n  if (seedRels.length === 0) return { ...shell, outOfScope: outside }\n\n  // 变更文件**自己不当结果**（这一区回答的是「还该看什么」）。\n  // ⚠️ 与上一版的差别：这里**不再**排除「已经在三层里的条目」—— 那需要先有一份包才知道，\n  // 而独立接口不该为了一个减法去装配一份三层。两边都出现不是重复：一个是「这一轮该先看什么」，\n  // 一个是「我改的东西牵着谁」。客户端按 rel 去重（它手上两份都有）。\n  const exclude = new Set(seeds)\n\n  // 已删除 / 重命名前的路径当种子时要有「空壳」候选，否则别人指向它的边解析不出来。\n  // ⚠️ 没有 gone 时**不拼**这个数组 —— 那样候选集与装配层那一份逐字相同，\n  // `relations.js` 的缓存（按候选集签名）能直接命中，省掉一次 10 ms 级的重算。\n  const candidates = gone.length > 0 ? [...corpus, ...ghostCandidates(gone)] : corpus\n  const facts = buildRelationFacts(candidates, { root })\n  const projected = projectChangeRelated({\n    seeds: seedRels, incident: facts.incident, itemRels: corpusRels, exclude, limit: MAX_CHANGE_RELATED,\n  })\n  const links = projected.related.map((row) => {\n    const doc = docOf.get(row.rel)\n    if (!doc) return null\n    // 每条证据一行：起点 / 类型 / 方向 / 行号（`line` 没有就是 `null`，不省略 —— 专用结构里\n    // 「这里没有行号」本身是信息，而 `tests` 那一类就是没有）。\n    const evidence = row.evidence.map((e) => ({\n      origin: e.other,\n      type: e.type,\n      dir: e.dir,\n      line: Number.isInteger(e.line) ? e.line : null,\n    }))\n    return {\n      target: row.rel,\n      kind: doc.kind || KIND_DOCUMENT,\n      source: sourceTypeOf(row.rel),\n      title: doc.title || row.rel,\n      summary: doc.summary == null ? '' : String(doc.summary),\n      mtimeMs: Number.isFinite(doc.mtimeMs) ? doc.mtimeMs : 0,\n      evidence,\n      evidenceTotal: row.evidenceTotal,\n      types: row.types,\n    }\n  }).filter(Boolean)\n  return {\n    ...shell,\n    links,\n    linksTotal: projected.relatedTotal,\n    // ⚠️ 两个计数**不许重复算同一篇**（写完当场被测试抓到过一次）：\n    // · `unresolved` 只说「在语料里、但一条证据都没有」的那些（= 查过了，没有）；\n    // · 语料之外的（删除的、重命名前的、这一档不认的后缀）只进 `outOfScope`（= 根本没得查）。\n    //   它们仍然**当种子**用（`seedRels` 带着它们），只是不该被说成「查了没查到」。\n    unresolved: projected.unresolved.filter((rel) => corpusRels.has(rel)),\n    outOfScope: outside,\n  }\n}\n\n/**\n * 给 Context Pack 补一份**计数摘要**（不是分数）。\n *\n * 客户端需要它来做两件事：① 在没有可见条目时区分「这个工作区是空的」与\n * 「有文档但当前话题一篇都没命中」；② 显示「相关上下文还有 N 篇」。\n * 数字全部是**集合大小**，没有任何相似度含义。\n *\n * @param {object} pack - `buildContext()` 的产物\n * @returns {object} 带 `summary` 的包\n */\nfunction withStats(pack) {\n  const primary = Array.isArray(pack.primary) ? pack.primary : []\n  const supporting = Array.isArray(pack.supporting) ? pack.supporting : []\n  const related = Array.isArray(pack.related) ? pack.related : []\n  return {\n    ...pack,\n    summary: {\n      primary: primary.length,\n      supporting: supporting.length,\n      related: related.length,\n      // 三层加起来的**可见条目数**（客户端「全部」档要用它做上限判断）\n      shown: primary.length + supporting.length + related.length,\n      // 本批语料里命中了话题的篇数 —— 「有文档但一篇都没命中」靠它判\n      matched: pack.totals ? pack.totals.matched : 0,\n      total: pack.totals ? pack.totals.total : 0,\n    },\n  }\n}\n\n/**\n * 一次请求里的上下文载荷：不适用（时间序 / 媒体档 / 没有命中）时返回 `null`。\n *\n * **只在「文档档 / 代码档 + 相关序」时装配** —— 其余情形返回 null，\n * 客户端于是退回它一直在用的平铺列表，行为与 v0.13 逐字一致。\n *\n * v0.19：代码档走的是**同一个**装配调用，没有任何 code-only 分支。\n * 引用图仍然只有 Markdown 才建（`links.js` 解析的是 Markdown 链接语法，\n * 这是它的既有边界，v0.19 不扩）—— 所以 `withLinks` 只在文档档为真。\n *\n * @param {string} root - 工作区根\n * @param {object} payload - `scan()` 的产物\n * @param {string} sort - 当前排序模式\n * @param {string} kind - 当前条目类型\n * @returns {Promise<object|null>} Context Pack（带 `summary`）或 null\n */\nasync function contextPayload(root, payload, sort, kind) {\n  // v0.23（方案 A）：面板的「全部」档也要一份包 —— 它是**包的原样**（三层混排文档 + 代码），\n  // 媒体在三层之后单独成网格。所以 `all` 与 `doc` / `code` / `context` 一样产出 Context Pack。\n  const contextKind = kind === 'doc' || kind === 'code' || kind === 'context' || kind === 'all'\n  if (!payload || payload.mode !== 'relevance' || sort !== 'relevance' || !contextKind) return null\n  // ⚠️ 媒体必须**在装配之前**剔掉，而且这不是洁癖：实测（2026-10-12）媒体能靠**文件名**命中\n  // 查询词并拿到 `raw > 0`，`docs/clip.mp4` 甚至能进 Primary —— 一个没有正文的视频当「先看」\n  // 是不可解释的上下文。剔掉之后「全部」档的语料与 `kind=context`（文档 + 代码）逐条一致。\n  const ranked = (Array.isArray(payload.ranked) ? payload.ranked : [])\n    .filter((doc) => doc && doc.kind !== KIND_IMAGE && doc.kind !== KIND_VIDEO)\n  if (ranked.length === 0) return null\n  try {\n    const pack = await buildContextFor(root, {\n      ranked,\n      topic: payload.topic,\n      task: payload.task,\n      total: payload.total,\n      // 引用图只在**真有命中**时才值得建（零命中时 Primary 为空，邻居逻辑没有锚点）；\n      // 而且只有 Markdown 有图可建。\n      // 「全部」也建引用图：三层里要能看到与「文档」档同样的关系证据（同一张图，零额外 I/O）。\n      withLinks: (kind === 'doc' || kind === 'all') && ranked.some((doc) => Number(doc.raw) > 0),\n    })\n    return withStats(pack)\n  } catch {\n    // 装配失败不该让整个列表接口失败 —— 退回 null，面板照常出平铺列表。\n    return null\n  }\n}\n\n/**\n * 读一个**可预览的文本产物**的完整正文（Markdown 文档 / 代码 / 生成产物），\n * 供面板内联预览。\n *\n * 路径必须落在工作区根之内——`rel` 来自浏览器，按不可信输入处理。\n *\n * v0.19：放行范围从「只认 `.md`」改成**按分类层判定**（`isPreviewKind`）。\n * 这条放宽是必须的（否则代码点不开），但边界一点没松：\n * 媒体仍然只走 `/knit/api/raw`，`ignored`（含这一版不支持的 `.go` / `.rs` / `.java`\n * / 未知扩展名）一律拒绝 —— **`/knit/api/doc` 仍然是按路径读文件的接口**，\n * 不能变成「读工作区里任意文件」的后门。\n *\n * @param {string} root - 工作区根\n * @param {string} rel - 工作区相对路径\n * @returns {Promise<object>} 载荷\n */\nexport async function readDocument(root, rel) {\n  // root 由调用方给出，这里自己归一化，不假设它已经 resolve 过\n  const base = resolve(root)\n  const abs = resolve(base, rel)\n  if (abs !== base && !abs.startsWith(base + sep)) {\n    return { ok: false, code: ERROR_CODES.outsideWorkspace }\n  }\n  const name = abs.split(sep).pop() || abs\n  const info = classifyFile(name)\n  if (!isPreviewKind(info.kind)) return { ok: false, code: ERROR_CODES.notPreviewable }\n\n  let st\n  try {\n    st = await stat(abs)\n  } catch {\n    return { ok: false, code: ERROR_CODES.notFound }\n  }\n  if (!st.isFile()) return { ok: false, code: ERROR_CODES.notAFile }\n\n  const buf = await readFile(abs)\n  const truncated = buf.length > DOC_MAX_BYTES\n  const text = buf.subarray(0, DOC_MAX_BYTES).toString('utf8')\n\n  const relPath = relative(base, abs).split(sep).join('/')\n  const payload = {\n    ok: true,\n    rel: relPath,\n    // v0.19 修订：给「打开 / 定位」用的 canonical 绝对路径（展开符号链接）。\n    // 客户端拿它去 `remote.session.openWorkspacePath`；自己用 root + rel 拼出来的那份\n    // 一旦含符号链接就会被宿主拒掉（`Path has no verified Host path`）。\n    path: hostPathOf(abs),\n    // v0.19：预览分支的判据由宿主给（分类层的结论），客户端不再自己看扩展名。\n    kind: info.kind,\n    language: info.language,\n    // 代码不用 `parseMarkdown` 猜标题 —— 一段开头的 `# 注释` 在 shell 里是注释，\n    // 不是标题。代码的标题就是文件名本身。\n    title: info.kind === KIND_DOC ? parseMarkdown(text, name).title : name,\n    bytes: buf.length,\n    truncated,\n    text,\n  }\n  // v0.19（需求 §6 §28）：同名 `<file>.map` 存在时，在 code 预览里给一个**极轻量**入口。\n  // 只多做一次 `stat`（不读内容、不进任何列表、不进检索、不进上下文）——\n  // `.map` 本身仍然不是 Context，这里只是「它就在旁边」这一个事实的搬运。\n  if (info.kind === KIND_CODE && !info.sourceMap) {\n    try {\n      const mapStat = await stat(`${abs}.map`)\n      if (mapStat.isFile()) payload.mapRel = `${relPath}.map`\n    } catch {\n      // 没有就是没有 —— 不加字段，不报错。\n    }\n  }\n  return payload\n}\n\n/**\n * 解析一个媒体（图片/视频）路径：越界防护 + 扩展名白名单 + 类型与大小校验。\n *\n * 这是按路径读文件的接口，不设限就等于开了读任意文件的后门：路径必须落在工作区内，\n * 扩展名必须在图片/视频白名单里，视频还有单独的大小上限。\n *\n * 只 stat、不读字节 —— 视频可能上百 MB，字节交给流式接口按需读取。\n *\n * @param {string} root - 工作区根\n * @param {string} rel - 工作区相对路径\n * @returns {Promise<object>} 成功时带 `{ abs, kind, type, size }`，否则带错误码\n */\nexport async function mediaInfo(root, rel) {\n  const base = resolve(root)\n  const abs = resolve(base, rel)\n  if (abs !== base && !abs.startsWith(base + sep)) {\n    return { ok: false, code: ERROR_CODES.outsideWorkspace }\n  }\n\n  const ext = (abs.split('.').pop() || '').toLowerCase()\n  let kind = KIND_IMAGE\n  let type = IMAGE_TYPES.get(ext)\n  if (!type) {\n    kind = KIND_VIDEO\n    type = VIDEO_TYPES.get(ext)\n  }\n  if (!type) return { ok: false, code: ERROR_CODES.mediaOnly }\n\n  let st\n  try {\n    st = await stat(abs)\n  } catch {\n    return { ok: false, code: ERROR_CODES.notFound }\n  }\n  if (!st.isFile()) return { ok: false, code: ERROR_CODES.notAFile }\n  if (kind === KIND_IMAGE && st.size > MAX_IMAGE_BYTES) {\n    return { ok: false, code: ERROR_CODES.imageTooLarge }\n  }\n  if (kind === KIND_VIDEO && st.size > MAX_VIDEO_BYTES) {\n    return { ok: false, code: ERROR_CODES.mediaTooLarge }\n  }\n\n  return { ok: true, abs, kind, type, size: st.size }\n}\n\n/**\n * 解析 HTTP Range 头（只支持 bytes 的单区间，覆盖 `<video>` 首帧与拖动播放的请求形态）。\n *\n * 解析不了（无 Range、多区间、语法怪异）一律返回 null —— 调用方回退成 200 整文件，\n * 而不是因为一个边角 Range 把播放掐死。\n *\n * @param {string|undefined} header - Range 头原值\n * @param {number} size - 文件总字节\n * @returns {{start:number,end:number}|null} 闭区间字节范围；null 表示返回整个文件\n */\nexport function parseRange(header, size) {\n  if (!header || size <= 0) return null\n  const m = /^bytes=(\\d*)-(\\d*)$/.exec(String(header).trim())\n  if (!m) return null\n  const startRaw = m[1]\n  const endRaw = m[2]\n  if (startRaw === '' && endRaw === '') return null\n\n  // bytes=-N：最后 N 个字节\n  if (startRaw === '') {\n    const suffix = Number(endRaw)\n    if (!Number.isInteger(suffix) || suffix <= 0) return null\n    return { start: Math.max(0, size - suffix), end: size - 1 }\n  }\n\n  const start = Number(startRaw)\n  if (!Number.isInteger(start) || start < 0 || start >= size) return null\n  let end = endRaw === '' ? size - 1 : Number(endRaw)\n  if (!Number.isInteger(end) || end < start) end = size - 1\n  end = Math.min(end, size - 1)\n  return { start, end }\n}\n\n/**\n * 从一个宿主会话对象解析工作区根。\n *\n * v0.16 起 `session/event` 的订阅回调里**只有 session 对象**（没有注入过的 webCtx），\n * 所以这段逻辑必须能独立使用：面板路由与记账回调共用它，保证「算列表用的根」与\n * 「归一化读路径用的根」永远是同一个 —— 否则同一次读会被一边算作包内、\n * 一边算作包外（AGENTS.md §8.10 踩过这个坑）。\n * @param {object} session - 宿主会话（可为空）\n * @returns {string} 绝对路径根\n */\nfunction rootOfSession(session) {\n  let root = ''\n  try {\n    if (session && session.header && typeof session.header.cwd === 'string') root = session.header.cwd\n  } catch { /* 取不到 cwd 就走兜底根 */ }\n  if (!root) root = process.cwd()\n  if (root.startsWith('~')) root = join(homedir(), root.slice(1))\n  return resolve(root)\n}\n\n/**\n * 交给宿主去「打开 / 定位」的路径必须**展开所有符号链接**。\n *\n * 判据在 DSH 自己那里：`dsh-api-session-controller` 的 `verifyDesktopPath()` 把路径送进\n * `ctx.fs`，要求\n * `fs.processPath(await fs.resolve(fs.processPathFromHostPath(p))) === p`；\n * 而 `dsh-fs-local` 的 `resolve()` 落的是 `realpath()`。也就是说 ——\n * **路径里只要有一个符号链接没展开，宿主就回\n * `gateway/bad-request / Path has no verified Host path`**，\n * 客户端把它显示成「打开失败：Path has no verified Host path」。\n *\n * 会话的工作区根完全可能是符号链接（实测：`DSH_Skill_Trace -> 10_DSH_Skill_Trace`），\n * 于是「打开」这条路必须另外给一份 canonical 路径。\n * **显示与检索仍用会话原本那个 root** —— 用户看到的是自己选的那条路径，\n * 只有交给宿主打开的路径要展开。\n *\n * 文件不存在时 `realpathSync` 会抛；调用点都在 `stat` 成功之后，兜底返回原路径，\n * 免得把一次「打不开」升级成接口 500。\n *\n * @param {string} path - 绝对路径\n * @returns {string} 展开符号链接后的绝对路径\n */\nfunction hostPathOf(path) {\n  try {\n    return realpathSync(path)\n  } catch {\n    return path\n  }\n}\n\n/**\n * 解析一个会话的工作区根。\n * @param {object} webCtx - 注入了 sessions 的上下文\n * @param {string} sessionId - 会话 id（可为空）\n * @returns {string} 绝对路径根\n */\nfunction workspaceRootOf(webCtx, sessionId) {\n  let session\n  try {\n    session = sessionId && typeof webCtx.sessions.get === 'function'\n      ? webCtx.sessions.get(sessionId)\n      : undefined\n  } catch { /* 会话查不到就走兜底根 */ }\n  return rootOfSession(session)\n}\n\n/**\n * 解析请求对应的宿主会话对象。\n * @param {object} webCtx - 注入了 sessions 的上下文\n * @param {string} sessionId - 会话 id\n * @returns {object|undefined} 会话对象\n */\nfunction sessionOf(webCtx, sessionId) {\n  try {\n    return sessionId && typeof webCtx.sessions.get === 'function' ? webCtx.sessions.get(sessionId) : undefined\n  } catch {\n    return undefined\n  }\n}\n\n/**\n * 判断来源是不是本机回环。\n * @param {string|undefined} address - socket remoteAddress\n * @returns {boolean} 是否放行\n */\nfunction isLoopback(address) {\n  if (!address) return false\n  return address === '::1' || address === '127.0.0.1' || address.startsWith('::ffff:127.')\n}\n\n/**\n * 读一个 JSON 请求体（v0.21 **唯一**用到它的地方是 `POST /api/control`）。\n *\n * 上限 8 KiB：控制状态是几个相对路径，没有理由收大包。畸形 JSON / 超限 / 读失败\n * 一律 `null`，由调用方翻成 `knit/bad-request` —— 这里不抛。\n *\n * @param {import('node:http').IncomingMessage} req - 请求对象\n * @returns {Promise<object|null>} 解析结果或 null\n */\nfunction readJsonBody(req, limit = 8192) {\n  return new Promise((resolve) => {\n    const chunks = []\n    let size = 0\n    req.on('data', (chunk) => {\n      size += chunk.length\n      if (size > limit) {\n        resolve(null)\n        req.destroy()\n        return\n      }\n      chunks.push(chunk)\n    })\n    req.on('end', () => {\n      if (size === 0) {\n        resolve({})\n        return\n      }\n      try {\n        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')))\n      } catch {\n        resolve(null)\n      }\n    })\n    req.on('error', () => resolve(null))\n  })\n}\n\n/**\n * `rel` 是否是一个**落在这个工作区内**的相对路径（v0.21 的写路由用）。\n *\n * ⚠️ 与 `readDocument()` 的区别：这里**不看文件是否存在**，也不读一个字节。\n * 控制状态存的是一个不透明字符串，写路由不暴露任何读原语；一个不存在的 rel\n * 最多是「标了一篇不在工作区里的文件」，它永远不会出现在任何一层的行里\n * （两层都在 `scan()` 之后，而 `scan()` 只吐真实收集到的文件）。\n * 越界 / 绝对路径 / 空串仍然一律拒绝 —— 拒绝的理由是「别把工作区外的路径存进来」。\n *\n * @param {string} root - 工作区根\n * @param {string} rel - 工作区相对路径\n * @returns {boolean} 是否放行\n */\nfunction relInside(root, rel) {\n  if (typeof rel !== 'string' || rel.length === 0 || rel.length > 1024) return false\n  if (rel.startsWith('/') || rel.includes('\\0')) return false\n  const base = resolve(root)\n  const abs = resolve(base, rel)\n  return abs !== base && abs.startsWith(base + sep)\n}\n\n/**\n * 写一个 JSON 响应。\n * @param {import('node:http').ServerResponse} res - 响应对象\n * @param {number} status - HTTP 状态码\n * @param {object} body - 载荷\n * @returns {void}\n */\nfunction sendJson(res, status, body) {\n  const text = JSON.stringify(body)\n  res.writeHead(status, {\n    'content-type': 'application/json; charset=utf-8',\n    'content-length': Buffer.byteLength(text),\n    'cache-control': 'no-store',\n    'x-content-type-options': 'nosniff',\n  })\n  res.end(text)\n}\n\n/**\n * 流式回一个媒体文件（图片/视频），支持 HTTP Range（206 Partial Content）。\n *\n * 视频首帧与拖动播放都依赖 Range：一次性把上百 MB 读进内存再返回既慢又占内存；\n * createReadStream 按区间读，客户端断开就销毁流。安全头与原图片接口一致：\n * nosniff 防类型嗅探，default-src 'none' + sandbox 让 SVG 脚本/外链失效。\n *\n * @param {import('node:http').IncomingMessage} req - 请求对象\n * @param {import('node:http').ServerResponse} res - 响应对象\n * @param {{abs:string, type:string, size:number}} info - mediaInfo 的成功结果\n * @returns {void}\n */\nfunction sendMedia(req, res, info) {\n  const part = parseRange(req.headers.range, info.size)\n  /** @type {Record<string, string|number>} */\n  const headers = {\n    'content-type': info.type,\n    'accept-ranges': 'bytes',\n    'cache-control': 'no-store',\n    'x-content-type-options': 'nosniff',\n    'content-security-policy': \"default-src 'none'; sandbox\",\n  }\n\n  let stream\n  if (part) {\n    headers['content-range'] = `bytes ${part.start}-${part.end}/${info.size}`\n    headers['content-length'] = part.end - part.start + 1\n    res.writeHead(206, headers)\n    stream = createReadStream(info.abs, { start: part.start, end: part.end })\n  } else {\n    headers['content-length'] = info.size\n    res.writeHead(200, headers)\n    stream = createReadStream(info.abs)\n  }\n\n  stream.on('error', () => {\n    try { stream.destroy() } catch { /* 已关闭 */ }\n    try { res.destroy() } catch { /* 已关闭 */ }\n  })\n  req.on('close', () => { try { stream.destroy() } catch { /* 已关闭 */ } })\n  stream.pipe(res)\n}\n\n/* ── v0.16 · Context Feedback 的宿主侧封装 ────────────────────────────\n *\n * 这一层只做三件事：\n *   1. **订阅**宿主的 `session/event`，把真实发生过的 `read` 一条条喂给 feedback store；\n *   2. 把刚交出去的 Context Pack 记成 Context Snapshot（带 `epochId`）；\n *   3. 给面板与 `knit_docs` 提供「**上一份**包之后发生了什么」。\n *\n * ⚠️ 读证据走**订阅**（`session/event`），不拿 `session.snapshotEvents()` 当审计来源：\n * 那个 API 已被 DSH 标记 deprecated（「new production calls are prohibited」）。\n * 代价是闸门打开**之前**已经发生的读不在订阅范围内，所以**开闸时回填一次**（v0.17 修订，用户拍板）：\n * 闸门只在你打开开关时才开，而真实用法是读完才看面板 —— 不回填就只能把真实发生过的读\n * 显示成「未读」，那是假话（规格 §3）。回填的代价被三条边界锁住：一个会话只做一次、\n * 只在开闸那一 tick、仍然零 I/O 零网络零模型且只在内存里。已知的不精确：回填的读按\n * 「我们已知最早的那份包」（= 开闸时看到的那份）归因，更早的包无从得知，所以**宁可少说**。\n *\n * 记账只在**被显式打开**的会话里发生（面板的「使用情况」开关，或 `knit_docs` 的\n * `audit: true`）—— 默认一条事件的处理成本就是一次 Map 查找。\n * 所有入口都 try/catch：记账坏了不许影响面板与工具（规格 §33 的降级纪律）。\n */\n\n/** 进程内唯一的 feedback store（按会话分片，会话数与篇数都有硬上限）。 */\nconst feedbackStore = createStore()\n\n/**\n * 本会话「工具产出的图」的登记簿（v0.25）。\n *\n * 内存里、有界、进程重启即失 —— 与 feedback 那一套同样只做**事实登记**，不落盘、不发请求。\n */\nconst attachmentStore = createAttachmentStore()\n\n/**\n * 已经回填过附件的会话（每个会话只回填一次）。\n *\n * ⚠️ **这是本文件第 3 处调用 `session.snapshotEvents()`**（前两处：`rankByRelevance` 当检索输入、\n * v0.17 的 `backfillFeedback`）。那个 API 已被 DSH 标 deprecated（「new production calls are prohibited」），\n * 所以这里刻意照抄 v0.17 那条例外的三条边界：**一个会话只做一次、同步零 I/O、只读内存**，\n * 失败一律吞掉（回填坏了不许带影响面板）。\n *\n * 为什么非要有它：只靠订阅的话，**插件启动之前**生成的图一条都收不到 —— 用户看到的是一个\n * 永远空着的列表（`重启 DSH 前的历史全部消失`），那等于没做。\n */\nconst attachmentBackfilled = new Set()\n\n/**\n * 一次性回填某会话已有的附件（幂等、有界、失败静默）。\n * @param {object|undefined} session - 宿主会话\n * @param {string} sessionId - 会话 id\n * @returns {void}\n */\nfunction backfillAttachments(session, sessionId) {\n  if (!sessionId || attachmentBackfilled.has(sessionId)) return\n  // ⚠️ 只有「请求里的 id」与「真的解析出这个会话」一致时才回填。\n  // 否则一个伪造的 sessionId 只要解析到**任意**会话，就能把那个会话的图登记到伪造 id 名下 ——\n  // 那等于绕过「读字节必须在本会话出现过」这条闸门。\n  if (!session || session.id !== sessionId) return\n  attachmentBackfilled.add(sessionId)\n  try {\n    if (typeof session.snapshotEvents !== 'function') return\n    const events = session.snapshotEvents() || []\n    for (const event of events) attachmentStore.note(sessionId, event)\n  } catch { /* 回填失败 = 少几张历史图，绝不影响面板 */ }\n}\n\n/** 测试用：清空附件登记簿与回填记账。 */\nexport function resetAttachments() {\n  attachmentStore.reset()\n  attachmentBackfilled.clear()\n}\n\n/**\n * 工作区内某个文件的 sha256（十六进制）。**越界一律不读**。\n * @param {string} root - 工作区根\n * @param {string} rel - 相对路径\n * @returns {Promise<string>} 十六进制（读不到回空串）\n */\nasync function sha256OfRel(root, rel) {\n  try {\n    const base = resolve(root)\n    const abs = resolve(base, rel)\n    if (abs !== base && !abs.startsWith(base + sep)) return ''\n    const st = await stat(abs)\n    if (!st.isFile() || !(st.size > 0) || st.size > MAX_IMAGE_BYTES) return ''\n    const hash = createHash('sha256')\n    const stream = createReadStream(abs)\n    for await (const chunk of stream) hash.update(chunk)\n    return hash.digest('hex')\n  } catch {\n    return ''\n  }\n}\n\n/**\n * 宿主会话注册表（`webCtx.sessions`）的引用，只给**工具**那条路用。\n *\n * 面板那条路拿得到 `webCtx`；`knit_docs` 的 `audit: true` 走的是 `auditBridge`，\n * 它也需要在开闸时回填历史（见 `backfillFeedback`），所以在这里留一份引用。\n */\nlet sessionsRef = null\n\n/**\n * 按会话 id 取宿主会话对象（拿不到就 undefined —— 回填只是「能补就补」）。\n * @param {string} sessionId - 会话 id\n * @returns {object|undefined} 会话\n */\nfunction sessionFor(sessionId) {\n  try {\n    if (!sessionId || !sessionsRef || typeof sessionsRef.get !== 'function') return undefined\n    return sessionsRef.get(sessionId)\n  } catch {\n    return undefined\n  }\n}\n\n/**\n * 取一个**已归一化**的工作区相对路径的版本标记（`mtimeMs`）。\n *\n * v0.17 用它回答「这篇文档被读过之后改过吗」。只接受走过 `normalizeRel` 的 `rel`\n * （无 `..`、无绝对路径逃逸、无 URL scheme），再 `resolve` 到 root 之下 `statSync` ——\n * 不新增任何用户可控的路径来源。任何异常 / 非有限值都返回 `null`：拿不到证据就不说。\n *\n * ⚠️ `feedback.js` 保持零 I/O，所以取样只能由宿主注入（`options.stat`）。\n *\n * @param {string} root - 工作区根（绝对路径）\n * @param {string} rel - 已归一化的工作区相对路径\n * @returns {number|null} mtimeMs，或 null\n */\nfunction mtimeOf(root, rel) {\n  try {\n    if (typeof root !== 'string' || !root) return null\n    if (typeof rel !== 'string' || !rel) return null\n    const st = statSync(resolve(root, rel))\n    return Number.isFinite(st.mtimeMs) ? st.mtimeMs : null\n  } catch {\n    return null\n  }\n}\n\n/**\n * 订阅宿主的会话事件流，把真实的读记进 store。\n *\n * `{ global: true }` 是**必需**的：`session/event` 按 scope 过滤派发，而这个插件挂在\n * 根上下文上、要看的却是各 agent scope 里的会话（宿主自己的 `invariant.js` 也这么订）。\n *\n * 三道闸门，顺序即开销顺序：**没记账的会话，一条事件只花一次 Map 查找**就返回。\n * 任何异常一律咽掉 —— 记账坏了绝不许影响宿主。\n * @param {object} session - 宿主会话\n * @param {object} event - 会话事件（`tool/call` / `tool/result` / 其它）\n * @returns {void}\n */\nfunction onSessionEvent(session, event) {\n  try {\n    const sessionId = session && typeof session.id === 'string' ? session.id : ''\n    if (!sessionId || !event) return\n    // v0.25：附件收集**不看审计闸门** —— 媒体档要显示工具产出的图，与「使用反馈」\n    // 是两件事。记一条的成本是一次 `event.type` 判断（不是带图的事件立刻返回）。\n    attachmentStore.note(sessionId, event)\n    if (!isAudited(feedbackStore, sessionId)) return\n    const root = rootOfSession(session)\n    // v0.17：成功读被确认的那一刻取一次版本标记。取样只发生在**新事件**上，\n    // 所以同一事件重复派发既不重复计数，也不重复取样。\n    ingestEvents(feedbackStore, sessionId, [event], {\n      root,\n      stat: (rel) => mtimeOf(root, rel),\n    })\n  } catch { /* 记账坏了不许影响宿主 */ }\n}\n\n/**\n * 把会话**已经发生**的事件补进 store（v0.17 修订，用户拍板）。\n *\n * 为什么需要：记账闸门只在面板带 `usage=1`（或 `knit_docs` 传 `audit: true`）那一刻才开，\n * 而真实用法是**读完才想起来看面板**。那些读发生在闸门外，Knit 手上零证据，面板只能把它们\n * 显示成「未读」—— 那是**假话**（规格 §3：只讲事实，不讲推断）。所以开闸时把会话已有的历史\n * 一次性补进 store：宁可补记，不可诬告。\n *\n * ⚠️ 顺序是这个函数的一部分：**先记下手上这份包，再喂事件**。`recordRead()` 在事件入库那一刻\n * 就把归因（`tier` / `inside` / `epochId`）结算并**冻结**，之后不再重算。若先喂事件，那些读会在\n * 「一份快照都还没有」的状态下被冻成包外，而「它当时不在 Context Pack 里」正是我们**不知道**的事。\n * 先记包则快照 seq 自然是 `-1`（此刻 `state.seq` 也是 `-1`），补记的读归到「我们已知最早的那份包」。\n *\n * 代价与边界（都写在这里，免得日后被误解成「全量扫描」）：\n *   - 只在**开闸那一刻**读一次 `snapshotEvents()`，一个会话只做一次（`isBackfilled`）；\n *   - 仍然**零 I/O、零网络、零模型**：事件来自宿主内存，版本标记来自一次 `statSync`；\n *   - 仍然只在内存里（重启即丢），也仍然只在有人看的时候才发生；\n *   - `ingestEvents` 自己按 `seq` 水位去重，所以回填过的事件稍后再从订阅派发一次\n *     也不会重复计数（规格 §18 Case 12 的幂等性照旧）。\n *\n * @param {string} sessionId - 会话 id\n * @param {object} session - 宿主会话（要有 `snapshotEvents()`）\n * @param {object|null} [pack] - 此刻手上这份 Context Pack；给了就先记成第一份快照\n * @returns {number} 补进来的读条数（拿不到 / 已回填过 → 0）\n */\nfunction backfillFeedback(sessionId, session, pack = null) {\n  try {\n    if (!sessionId || !session) return 0\n    if (typeof session.snapshotEvents !== 'function') return 0\n    if (isBackfilled(feedbackStore, sessionId)) return 0\n    const events = session.snapshotEvents()\n    if (!Array.isArray(events) || events.length === 0) return 0\n    const root = rootOfSession(session)\n    // 先记包（见上面的顺序说明）：快照 seq 会是 -1，于是补记的读能归到它身上。\n    // ⚠️ 不传 `at`：这份包代表的是「会话开始时的那份上下文」，与 seq = -1 同一口径。\n    // 传此刻的墙钟会让第一次记账的 `usage.at` 从「还没有上一份」(0) 变成一个假的具体时间，\n    // 而这一请求真正的交包时间由下面 `auditBridge.note()` 那次去重更新写进去。\n    if (pack) noteSnapshot(feedbackStore, sessionId, pack)\n    const result = ingestEvents(feedbackStore, sessionId, events, {\n      root,\n      stat: (rel) => mtimeOf(root, rel),\n    })\n    if (!result.ok) return 0\n    markBackfilled(feedbackStore, sessionId)\n    return result.reads\n  } catch {\n    return 0\n  }\n}\n\n/**\n * 打开某个会话的记账（面板的「使用情况」开关走它），并顺手回填已有历史。\n *\n * ⚠️ 回填**必须**发生在开闸之后、同一个 tick 里：开闸前的事件由回填补，\n * 开闸后的事件走订阅，两者在 `seq` 上严丝合缝，不会漏也不会重。\n *\n * @param {string} sessionId - 会话 id\n * @param {object} [session] - 宿主会话；省略则只开闸不回填\n * @param {object|null} [pack] - 此刻手上的 Context Pack，交给回填当第一份快照\n * @returns {boolean} 是否成功\n */\nexport function activateFeedback(sessionId, session = null, pack = null) {\n  const ok = activateAudit(feedbackStore, sessionId)\n  if (ok) backfillFeedback(sessionId, session, pack)\n  return ok\n}\n\n/**\n * 这个会话在记账吗。\n * @param {string} sessionId - 会话 id\n * @returns {boolean} 是否记账\n */\nexport function feedbackActive(sessionId) {\n  return isAudited(feedbackStore, sessionId)\n}\n\n/**\n * 线路上的紧凑使用情况：面板只需要**计数**、**四态生命周期**与最近一次变化，\n * 不需要 200 条明细。\n * @param {object|null} usage - `usageFor()` 的结果\n * @param {number} [limit] - 明细最多带几条\n * @param {Set<string>|null} [rels] - v0.17：本次真正要渲染的文档（当前页 ∪ 包外明细）；\n *   省略/为 null 时不裁剪 lifecycle（测试与其它调用方兼容）\n * @returns {object|null} 紧凑视图\n */\nexport function publicUsage(usage, limit = 20, rels = null) {\n  if (!usage || !usage.stats) return null\n  const delta = usage.delta ? {\n    appeared: usage.delta.appeared.slice(0, limit),\n    disappeared: usage.delta.disappeared.slice(0, limit),\n    moved: usage.delta.moved.slice(0, limit),\n    taskChanged: !!usage.delta.taskChanged,\n  } : null\n\n  // v0.17：lifecycle 每个条目只带 UI 要用的三个字段（状态值仍是英文事实，\n  // 中文只在客户端词典里）。按 rels 裁剪是刻意的：只发真正会渲染的那些行。\n  const source = usage.lifecycle && typeof usage.lifecycle === 'object' ? usage.lifecycle : {}\n  const lifecycle = {}\n  for (const rel of Object.keys(source)) {\n    if (rels && !rels.has(rel)) continue\n    const row = source[rel]\n    if (!row) continue\n    lifecycle[rel] = { status: row.status, count: row.count, lastReadAt: row.lastReadAt }\n  }\n\n  return {\n    at: usage.at,\n    epochId: usage.epochId,\n    stats: { ...usage.stats, outsideReads: usage.stats.outsideReads.slice(0, limit) },\n    delta,\n    // v0.17 新增（`latestDelta` 与 `delta` 同值：前者是 UI 唯一读的那个键）\n    latestDelta: delta,\n    recentRead: usage.recentRead ? { ...usage.recentRead } : null,\n    outsideDocs: (Array.isArray(usage.outsideDocs) ? usage.outsideDocs : [])\n      .slice(0, limit)\n      .map((row) => ({ ...row })),\n    lifecycle,\n  }\n}\n\n/**\n * 注入给 `knit_docs` 的桥 —— 工具不认识 `feedback.js`，只认识这两个方法\n * （与 `scan` / `read` / `contextFor` 同样的注入理由）。\n *\n * ⚠️ `summary()` 必须在 `note()` **之前**调用：它报告的是**上一份**包的用法。\n * v0.16 起这个桥**不再收** root 与 session：读证据由订阅那条路进 store，\n * 交包只是记一份快照（`seq` 用 store 自己的事件水位）。\n */\nconst auditBridge = {\n  usage(sessionId, mtimes) {\n    try {\n      if (!sessionId) return null\n      // mtimes：v0.17 的当前版本标记（rel → mtimeMs）。不传就是保守投影（拿不到变化证据）。\n      return usageFor(feedbackStore, sessionId, { mtimes })\n    } catch {\n      return null\n    }\n  },\n  summary(sessionId) {\n    try {\n      if (!sessionId) return ''\n      return getAuditSummary(usageFor(feedbackStore, sessionId))\n    } catch {\n      return ''\n    }\n  },\n  note(sessionId, pack) {\n    try {\n      if (!sessionId || !pack) return null\n      // 走到这里说明记账是**显式**的（面板带了 `usage=1`，或 agent 传了 `audit: true`\n      // 且 `tool.js` 只在那一刻调 note）—— 所以在这里开闸是安全的。\n      // v0.17 修订：开闸的同时回填会话已有的事件，否则「读完才打开」的那些读\n      // 会被显示成「未读」——那是假话。\n      activateAudit(feedbackStore, sessionId)\n      backfillFeedback(sessionId, sessionFor(sessionId), pack)\n      // 不传 `seq`：noteSnapshot 用会话当前的**事件水位**，也就是「交这份包时\n      // 已经发生到第几个事件」—— seq ≤ 它的读才算在这份包里。\n      return noteSnapshot(feedbackStore, sessionId, pack, { at: Date.now() })\n    } catch {\n      return null\n    }\n  },\n}\n\n/**\n * 从 `ctx.storage` 上取一份带 `kv` facet 的后端（v0.21）。\n *\n * ⚠️ `backend.get(name)` 名字不存在时**会抛** `backend-not-found`（不是返回 undefined，\n * 见 `dsh-storage` 的 `BackendRegistry`），所以每一步都在 try 里。任何一步不齐\n * 都返回 `null` ⇒ 控制层退回内存态并如实说 `persisted: false` —— 那是**正常降级**，\n * 不是异常分支（D8）。\n *\n * @param {object} storage - `ctx.storage`（hub）\n * @returns {object|null} 后端或 null\n */\nfunction controlBackendOf(storage) {\n  try {\n    const registry = storage && storage.backend\n    if (!registry || typeof registry.get !== 'function') return null\n    const named = typeof registry.names === 'function' ? registry.names() : []\n    for (const candidate of ['json', ...named]) {\n      try {\n        const backend = registry.get(candidate)\n        if (backend && backend.kv && typeof backend.kv.open === 'function') return backend\n      } catch {\n        // 这个后端没注册 —— 试下一个\n      }\n    }\n    return null\n  } catch {\n    return null\n  }\n}\n\n/**\n * 宿主插件体：等 webServer / sessions 到位后挂只读路由。\n * @param {import('@deepseek-ai/cordis').Context} ctx - 宿主根上下文\n * @returns {void}\n */\nexport function apply(ctx) {\n  // v0.16：订阅会话事件流 —— 这是 Knit 唯一的读证据来源。\n  // ⚠️ 注册在这里，而不是 `inject(['webServer','sessions'])` 的回调里：\n  // `knit_docs` 的 `audit: true` 也能打开记账，没有 webServer 的环境照样要记。\n  ctx.on('session/event', onSessionEvent, { global: true })\n\n  ctx.inject(['webServer', 'sessions'], (webCtx) => {\n    // v0.17 修订：工具那条路（`knit_docs audit:true`）也要能回填，所以留一份引用。\n    sessionsRef = webCtx.sessions\n    const handler = async (req, res) => {\n      if (!isLoopback(req.socket?.remoteAddress)) {\n        sendJson(res, 403, { ok: false, code: ERROR_CODES.loopbackOnly })\n        return\n      }\n      // v0.21：整个 HTTP 面**仍然只读**，只有一条写动作 —— 固定 / 排除。\n      // 它改的也只是 Knit 自己的控制状态，从不碰工作区里的任何文件。\n      const path = (req.url || '/').split('?')[0]\n      const isControl = path === `${ROUTE_PREFIX}/api/control`\n      // v0.23：第二条（也是最后一条）写通道 —— 只写 Knit 自己的语义 provider 配置。\n      // 它同样**只认 POST**（`GET /api/semantic` 一律 405，与 `GET /api/control` 一致）。\n      const isSemantic = path === `${ROUTE_PREFIX}/api/semantic`\n      const isWrite = isControl || isSemantic\n      // 写通道**只认 POST**：别的路由仍然是纯 GET。\n      // （写成「非 GET 一律 405，除非是写路由的 POST」会让 `GET /api/control`\n      // 掉进写分支里报 400 —— 那是「方法不对」不是「请求不对」。）\n      if (req.method !== (isWrite ? 'POST' : 'GET')) {\n        sendJson(res, 405, { ok: false, code: ERROR_CODES.methodNotAllowed })\n        return\n      }\n\n      const url = new URL(req.url || '/', 'http://localhost')\n      const sessionId = url.searchParams.get('sessionId') || ''\n      const root = workspaceRootOf(webCtx, sessionId)\n\n      try {\n        if (isSemantic) {\n          // 只认 `{kind, base, model}`：三个都空 ⇒ **清空配置**；否则必须整份合法。\n          // 配置是**机器级**的（不按工作区），所以这里不需要 sessionId / rel 校验 ——\n          // 但**仍然**只回环、只 POST、坏 body 400（与 `/api/control` 同一条纪律，§6.9）。\n          const body = await readJsonBody(req)\n          const raw = body && typeof body === 'object' ? body : {}\n          const empty = !raw.kind && !raw.base && !raw.model\n          const config = empty ? null : normalizeProviderConfig(raw)\n          if (!empty && !config) {\n            sendJson(res, 400, { ok: false, code: ERROR_CODES.badRequest })\n            return\n          }\n          await semanticEngine.configure(config)\n          // 保存后**顺手探一次**：界面要的是「现在到底能不能用」，不是「我存下了」。\n          const checked = config ? await semanticEngine.check() : { available: false, reason: 'no-provider' }\n          sendJson(res, 200, {\n            ok: true,\n            configured: !!config,\n            available: !!checked.available,\n            reason: checked.available ? null : (checked.reason || 'probe-failed'),\n          })\n          return\n        }\n        if (isControl) {\n          // 只认 `{action, rel}`；动作白名单在 `control.js` 里（一处真源）。\n          // `root` 由 sessionId 解析 —— 工作区**不能由请求指定**，与其余路由同一条纪律。\n          const body = await readJsonBody(req)\n          const action = body && typeof body.action === 'string' ? body.action : ''\n          const rel = body && typeof body.rel === 'string' ? body.rel : ''\n          if (!CONTROL_ACTIONS.includes(action)) {\n            sendJson(res, 400, { ok: false, code: ERROR_CODES.badRequest })\n            return\n          }\n          if (!relInside(root, rel)) {\n            sendJson(res, 400, { ok: false, code: ERROR_CODES.missingRel })\n            return\n          }\n          const result = await controlRegistry.act(root, action, rel)\n          sendJson(res, 200, {\n            ok: true,\n            action,\n            rel,\n            changed: result.changed,\n            persisted: result.persisted,\n            control: result.control,\n          })\n          return\n        }\n        if (url.pathname === `${ROUTE_PREFIX}/api/recent`) {\n          const limit = Math.min(Math.max(Number(url.searchParams.get('limit')) || 20, 1), 100)\n          const sort = url.searchParams.get('sort') === 'relevance' ? 'relevance' : 'time'\n          const kindParam = url.searchParams.get('kind')\n          // v0.19：多一档 `code`。白名单形态不变（认不出的值一律回落 `doc`），\n          // 而 `context` 那个内部语料**不从 HTTP 暴露**。\n          const kind = kindParam === 'all' || kindParam === 'media' || kindParam === 'code'\n            ? kindParam\n            : 'doc'\n          const payload = await scan(root, limit, {\n            session: sessionOf(webCtx, sessionId), sessionId, sort, kind,\n            // v0.23：默认 `lexical`（不带这个参数的老客户端行为逐字不变）。\n            retrieval: url.searchParams.get('retrieval') === 'hybrid' ? 'hybrid' : 'lexical',\n          })\n          const body = publicScanPayload(payload)\n          // v0.14：相关模式下顺带给出任务上下文分层。\n          // ⚠️ 带上 `context` 是**可选**的（老客户端忽略它），而 `docs` 一字未动。\n          // ⚠️ v0.25（第二轮修订）：**这里不再有任何 Git 变更关联**。`/api/recent` 的响应\n          // 与 v0.24 逐字相同（`changes` 那个键根本不存在）—— 变更关联走独立的\n          // `/knit/api/changes`。这条纪律有测试守着：常规检索请求里不许出现变更字段。\n          body.context = await contextPayload(root, payload, sort, kind)\n          // v0.21：面板要显示「固定了什么 / 排除了什么」（含恢复按钮），而这两份\n          // 是**用户动作的原始记录**，不是 Context Pack 的投影 —— 固定项本身在\n          // `context.pinned` 里，这里给的是状态本身。`skipped` 是**这一批**里真的被\n          // 排掉了几篇：管道条要的是如实计数，不是 `excluded.length`（切到代码档时，\n          // 被排除的那篇 Markdown 根本不在语料里）。\n          {\n            // 先等首访装载落定：`persisted` 是**已证明**的意思，不许在证据到之前先点头\n            // （真机验收实测过：不等它就会在写失败时回一句 `true`）。\n            await controlRegistry.ready(root)\n            const state = controlRegistry.controlOf(root)\n            const alive = payload.stats && payload.stats.controlAlive\n            body.control = {\n              pinned: state.pinned,\n              // `exists` = 这一篇现在还在工作区里吗。记录一律保留（用户排除过的就是排除过的），\n              // 但「恢复」按钮只在它真的还可能回来时给 —— 否则按下去什么都不会发生。\n              excluded: state.excluded.map((item) => ({\n                rel: item.rel, at: item.at, exists: alive ? alive.has(item.rel) : false,\n              })),\n              skipped: Number(payload.stats && payload.stats.controlSkipped) || 0,\n              persisted: controlRegistry.persisted,\n            }\n          }\n          // v0.15：面板把「使用情况」开关打开后，请求会带 `usage=1` —— 那一刻开始记账。\n          // v0.17 修订：开闸的同时**回填**这个会话已经发生的事件（闸门开晚时，\n          // 前面那些真实发生过的读不该被显示成「未读」——那是假话，见 `backfillFeedback`）。\n          // ⚠️ 默认（不带这个参数且本会话从未打开过）**一个字节都不记**。\n          if (sessionId && url.searchParams.get('usage') === '1') {\n            // 交上此刻手上的包，回填才能把补记的读归到「我们已知最早的那份包」，而不是包外。\n            activateFeedback(sessionId, sessionOf(webCtx, sessionId), body.context)\n          }\n          if (sessionId && feedbackActive(sessionId)) {\n            // ⚠️ 顺序是刻意的：先取 usage（它报告的是**上一份**包之后发生了什么），\n            // 再把这一份包记成新快照 —— 从下一次请求起，它才是「上一份」。\n            //\n            // v0.17：当前版本标记用**全量**扫描结果建立，不是被 limit 截断的这一页 ——\n            // 否则一篇被读过、但没落在当前页的文档拿不到当前 mtime，会永远停在「已读」。\n            const full = Array.isArray(payload.allDocs) && payload.allDocs.length > 0\n              ? payload.allDocs\n              : payload.docs\n            const mtimes = new Map(full.map((doc) => [doc.rel, doc.mtimeMs]))\n            const usage = auditBridge.usage(sessionId, mtimes)\n            // lifecycle 只发真正会渲染的那些行：当前页 ∪ 包外明细（后者的「已读 ×N」\n            // 也要显示，只按当前页裁剪会把它们的状态丢掉）。\n            const rels = new Set([\n              ...body.docs.map((doc) => doc.rel),\n              ...((usage && Array.isArray(usage.outsideDocs) ? usage.outsideDocs : [])\n                .map((row) => row.rel)),\n            ])\n            body.usage = publicUsage(usage, 20, rels)\n            if (body.context) auditBridge.note(sessionId, body.context)\n          }\n          sendJson(res, 200, body)\n          return\n        }\n\n        if (url.pathname === `${ROUTE_PREFIX}/api/changes`) {\n          /* v0.25 · **Git 变更关联**：独立接口。\n             ⚠️ 与 `/api/recent` 分开不是洁癖，是契约纪律：\n               · `/api/recent` 的响应形状**一个键都不加**（与 v0.24 逐字相同）——\n                 它同时喂着「只要列表」的调用方，不该因为少数人打开的功能变重；\n               · 这个接口有**自己的数据结构**（起点 / 目标 / 类型 / 行号），不借 Context Pack\n                 条目的词汇（`provenance` / `reason` / `relations`）—— 那套词汇属于三层，\n                 硬套过来就得扩工具 schema 的枚举，而工具契约不动。\n             成本：**一次 git + 一次扫描**，而且两者都与 `/api/recent` **共用**——\n             `corpusForChanges()` 复用最近一次扫描（8 s 同窗），`gitReader` 自己缓存 + 并发去重。\n             关掉时客户端根本不请求这条路由 ⇒ 一个 git 进程都不 spawn。 */\n          const limit = Math.min(Math.max(Number(url.searchParams.get('limit')) || 40, 1), 100)\n          const sort = url.searchParams.get('sort') === 'time' ? 'time' : 'relevance'\n          // ⚠️ **没有 `kind` 参数**（v0.25 收尾时删掉）。理由是可核验的：变更关联固定用\n          // 「文档 + 代码」那一份**不分档**语料（`collectDocs()` 的结果与档位无关，\n          // 档位只影响 `docs` 那一栏的输出），所以 `kind` 在这里**没有任何语义** ——\n          // 留一个「看着像能过滤、实际什么都不做」的参数比没有它更糟。\n          if (sort !== 'relevance') {\n            // 时间序没有 Context Pack，也就没有「该一起看什么」这回事。如实说，不给空壳。\n            sendJson(res, 200, {\n              ok: true, mode: 'changes', sort,\n              git: { available: false, reason: 'not-relevance-order', filesTotal: 0, truncated: false, files: [] },\n              links: [], linksTotal: 0, unresolved: [], outOfScope: [],\n            })\n            return\n          }\n          const payload = await corpusForChanges(root, {\n            limit,\n            options: { session: sessionOf(webCtx, sessionId), sessionId, sort, kind: 'context' },\n          })\n          sendJson(res, 200, await changesPayload(root, { corpus: payload.contextCorpus }))\n          return\n        }\n\n        if (url.pathname === `${ROUTE_PREFIX}/api/context`) {\n          // v0.14：独立的上下文接口。与 `/api/recent` 分开是为了**不让只想拿列表的\n          // 调用方被迫付引用图的钱** —— 面板走 recent 里的 `context` 字段，\n          // 这个路由留给「只要上下文、不要列表」的调用方。\n          const limit = Math.min(Math.max(Number(url.searchParams.get('limit')) || MAX_DOCS, 1), MAX_DOCS)\n          const sort = url.searchParams.get('sort') === 'time' ? 'time' : 'relevance'\n          const kindParam = url.searchParams.get('kind')\n          const kind = kindParam === 'all' || kindParam === 'media' || kindParam === 'code'\n            ? kindParam\n            : 'doc'\n          const payload = await scan(root, limit, {\n            session: sessionOf(webCtx, sessionId), sessionId, sort, kind,\n          })\n          // ⚠️ 与 `/api/recent` 的 `context` 字段**语义不同**：这里永远返回一个\n          // 结构齐全的包（没有命中就是三层全空），不用 null。\n          // null 是「请退回平铺列表」，那是 recent 的语义；独立的上下文接口\n          // 没有平铺列表可退，返回 null 只会让调用方多一次判空。\n          const context = withStats(await buildContextFor(root, {\n            ranked: Array.isArray(payload.ranked) ? payload.ranked : [],\n            topic: payload.topic,\n            task: payload.task,\n            total: payload.total,\n            withLinks: payload.mode === 'relevance' && kind === 'doc',\n          }))\n          // v0.15：走这条路的调用方（只要上下文、不要列表）同样会推进 Context Snapshot ——\n          // 否则「上下文变了」这件事会漏记。**只在已记账的会话里**（同 recent 的闸门）。\n          if (sessionId && feedbackActive(sessionId)) {\n            auditBridge.note(sessionId, context)\n          }\n          sendJson(res, 200, { ok: true, root, hostRoot: hostPathOf(root), mode: payload.mode, topic: payload.topic, context })\n          return\n        }\n\n        if (url.pathname === `${ROUTE_PREFIX}/api/doc`) {\n          const rel = url.searchParams.get('rel') || ''\n          if (!rel) {\n            sendJson(res, 400, { ok: false, code: ERROR_CODES.missingRel })\n            return\n          }\n          const payload = await readDocument(root, rel)\n          sendJson(res, payload.ok ? 200 : 404, payload)\n          return\n        }\n\n        if (url.pathname === `${ROUTE_PREFIX}/api/raw`) {\n          const rel = url.searchParams.get('rel') || ''\n          if (!rel) {\n            sendJson(res, 400, { ok: false, code: ERROR_CODES.missingRel })\n            return\n          }\n          const media = await mediaInfo(root, rel)\n          if (!media.ok) {\n            sendJson(res, 404, { ok: false, code: media.code })\n            return\n          }\n          sendMedia(req, res, media)\n          return\n        }\n\n        if (url.pathname === `${ROUTE_PREFIX}/api/links`) {\n          // v0.12：某篇的「谁引用了它 / 它引用了谁」。\n          // 形态逐字照抄 /api/doc —— 缺 rel 走同一个错误码，不新增读文件原语：\n          // 图只用 collectDocs / readDocument 建，两者本身已强制「必须在工作区内」。\n          const rel = url.searchParams.get('rel') || ''\n          if (!rel) {\n            sendJson(res, 400, { ok: false, code: ERROR_CODES.missingRel })\n            return\n          }\n          const graph = await buildLinkGraph(root, { list: collectDocs, read: readDocument })\n          const payload = linksOf(graph, rel)\n          sendJson(res, payload.ok ? 200 : 404, payload)\n          return\n        }\n\n        if (url.pathname === `${ROUTE_PREFIX}/api/attachments`) {\n          /* v0.25：本会话「工具产出」的图（媒体档里显示）。\n             列表**全部来自会话事件**（零 I/O）；这里只多做一件事：把「工作区里已经有同内容\n             文件」的条目去掉 —— 先按 `bytes` 筛候选，只给大小相同的候选算 sha256。 */\n          const sessionId = url.searchParams.get('sessionId') || ''\n          backfillAttachments(sessionOf(webCtx, sessionId), sessionId)\n          const items = sessionId ? attachmentStore.list(sessionId) : []\n          if (!items.length) {\n            sendJson(res, 200, { ok: true, items: [] })\n            return\n          }\n          /* ⚠️ 候选必须用**媒体档**扫一遍（`kind: 'media'`）：\n             · `contextCorpus` 是「文档 + 代码」，**媒体从不在里面**（媒体不参与 Context Pack）；\n             · `allDocs` 是**按档位切开**的 —— `kind: 'context'` 下连一张图都没有（实测）。\n             这次扫描只取 `{rel, bytes}` 两个字段，随后交给 `dropSaved` 按大小筛、只给\n             大小相同的候选算 sha256。扫描结果进备忘也没问题：`contextCorpus` 与档位无关\n             （`collectDocs()` 不分档），所以 `/api/changes` 读到的那份**一字不差**。 */\n          const mediaPayload = await scan(root, 40, {\n            session: sessionOf(webCtx, sessionId), sessionId, sort: 'relevance', kind: 'media',\n          })\n          const scanDocs = (mediaPayload && mediaPayload.allDocs) || []\n          const candidates = scanDocs\n            .filter((doc) => doc && (doc.kind === KIND_IMAGE || doc.kind === KIND_VIDEO))\n            .map((doc) => ({ rel: doc.rel, bytes: Number.isFinite(doc.size) ? doc.size : -1 }))\n          const kept = await dropSaved(items, { candidates, sha256Of: (rel) => sha256OfRel(root, rel) })\n          sendJson(res, 200, { ok: true, items: kept })\n          return\n        }\n\n        if (url.pathname === `${ROUTE_PREFIX}/api/attachment`) {\n          /* v0.25：按 **sha256** 读一个附件对象的字节 —— **本插件唯一越出工作区的读**。\n             三条边界缺一不可：\n               ① 只收 `sha256:<64 hex>`，**不接受任何路径**（路径由哈希算出来，给不出穿越）；\n               ② 这个 id 必须在**本会话**的 `tool/result` 里出现过（跨会话 / 没出现过一律 404）；\n               ③ 只回图片 / 视频，走既有的 `sendMedia`（nosniff + sandbox CSP）。 */\n          const sessionId = url.searchParams.get('sessionId') || ''\n          const id = url.searchParams.get('id') || ''\n          backfillAttachments(sessionOf(webCtx, sessionId), sessionId)\n          const meta = sessionId && isAttachmentId(id) ? attachmentStore.get(sessionId, id) : undefined\n          if (!meta) {\n            sendJson(res, 404, { ok: false, code: ERROR_CODES.notFound })\n            return\n          }\n          const abs = objectPath(attachmentsRoot(), id)\n          const info = abs ? await stat(abs).catch(() => null) : null\n          if (!info || !info.isFile() || !(info.size > 0) || info.size > MAX_ATTACHMENT_BYTES) {\n            sendJson(res, 404, { ok: false, code: ERROR_CODES.notFound })\n            return\n          }\n          sendMedia(req, res, { abs, type: meta.mediaType, size: info.size })\n          return\n        }\n\n        sendJson(res, 404, { ok: false, code: ERROR_CODES.notFoundRoute })\n      } catch (error) {\n        sendJson(res, 500, { ok: false, code: ERROR_CODES.internal, detail: String((error && error.message) || error) })\n      }\n    }\n\n    webCtx.effect(() => {\n      const unregister = webCtx.webServer.register({ kind: 'prefix', path: ROUTE_PREFIX, handler })\n      console.log(`[${name}] route ready: ${ROUTE_PREFIX}/api/recent, ${ROUTE_PREFIX}/api/doc, ${ROUTE_PREFIX}/api/raw, ${ROUTE_PREFIX}/api/links, ${ROUTE_PREFIX}/api/context, ${ROUTE_PREFIX}/api/changes, ${ROUTE_PREFIX}/api/attachments, ${ROUTE_PREFIX}/api/attachment, ${ROUTE_PREFIX}/api/control (POST)`)\n      return () => unregister()\n    }, 'dsh-knit: host route')\n  })\n\n  // ── v0.21：固定 / 排除的持久化（D8）───────────────────────────────\n  //\n  // 独立的一次 `ctx.inject`，理由与下面那次完全一样：`storage` 缺席时这个回调\n  // **根本不跑**（cordis 的 inject 语义：服务不齐就静默不加载），而面板路由与\n  // agent 工具照常工作 —— 只是控制状态活不过这次进程。这正是要的降级路径。\n  ctx.inject(['storage'], (storageCtx) => {\n    const backend = controlBackendOf(storageCtx.storage)\n    // ⚠️ 必须走 `sharedControlRegistry`：DSH 会在同一进程里把插件加载很多次，而\n    // kv 单元只允许一个活句柄 —— 每次加载各开一次的话，只有第一次开得成，而模块级\n    // 变量被最后一次加载覆盖 ⇒ 活跃实例恰恰是 `persisted: false` 的那个。\n    const shared = sharedControlRegistry(backend)\n    if (shared) controlRegistry = shared\n    console.log(`[${name}] control storage: ${shared ? 'json backend attached' : 'memory-only'}`)\n\n    // ── v0.22：增量索引的持久化 ─────────────────────────────────────\n    //\n    // 与上面共用**一个** `ctx.storage` 后端，但**各开各的 kv 单元**（`knit_index`）：\n    // 索引的写量与形状和控制状态完全不同（`per-record` + 每条一个文件），混在一个单元里\n    // 会让「改一个文件」变成重写整份控制状态。同一条 `sharedIndexStore()` 理由，\n    // 见 `index-store.js`。\n    const store = sharedIndexStore(backend)\n    if (store) setIndexRegistry(store)\n    console.log(`[${name}] index storage: ${store ? 'attached' : 'memory-only'}`)\n\n    // ── v0.23：可选混合检索的**配置**持久化 ──────────────────────────\n    //\n    // 第三个 kv 单元（`knit_semantic`）。**只存配置**（一条全局记录，`single` 布局）；\n    // 向量活在进程内缓存里 —— 持久化向量是 Phase B 的事（方案 §6）。\n    // 拿不到存储时引擎照样工作，只是配置活不过这次进程（面板会如实说）。\n    const semanticStore = sharedSemanticStore(backend)\n    if (semanticStore) semanticEngine = createSemanticEngine({ store: semanticStore })\n    console.log(`[${name}] semantic storage: ${semanticStore ? 'attached' : 'memory-only'}`)\n  })\n\n  // ── v0.7：把同一个排序结果也交给模型 ──────────────────────────────\n  //\n  // 独立的一次 `ctx.inject`，**不是**把 'tools' 加进上面那个数组。\n  // 加进去的话 `tools` 缺席时整个回调都不跑 —— 连面板路由都起不来。\n  // 两条路互不依赖：没有 tools 服务时，浏览器那半边照常工作。\n  ctx.inject(['tools'], (toolCtx) => {\n    toolCtx.effect(\n      // v0.15：多注入一个 `auditBridge` —— `knit_docs` 的 `audit: true` 走它拿\n      // 「上一份包之后发生了什么」，并把这次交出的包记成新快照。\n      () => registerKnitDocsTool(toolCtx, scan, readDocument, buildContextFor, auditBridge),\n      'dsh-knit: knit_docs tool',\n    )\n    console.log(`[${name}] agent tool ready: knit_docs`)\n  })\n}\n"
    },
    {
      "path": "src/client/client.js",
      "content": "/**\n * Knit · 浏览器半边\n *\n * 在两个宿主上注册同一个「最近文档」面板：\n *   1. DSH 自带右侧栏（@deepseek-ai/dsh-client-ui-sidebar-right）—— 主路径\n *   2. dsh-better-sidebar 的 ctx.betterSidebar.registerTab —— 可选，吃到它那批用户\n *\n * 面板本身：列表（相关性或 mtime 排序 + 过滤 + 键盘导航）+ 列表下方的就地预览。\n * 两个宿主共用同一个 KnitBody，只在「怎么开新标签页」上用适配器分叉。\n *\n * 构建：无。手写脚本，由 __ModuleLoader__ 直接装载，用 React.createElement 而非 JSX。\n */\nwindow.__ModuleLoader__.load({\n  id: 'dsh-knit',\n  factory: (require) => {\n    const module = { exports: {} }\n    const React = require('react')\n    /* v0.25（2026-10-22）：全屏查看器要**盖住整个屏幕**，所以必须挂到 `document.body` 上。\n       为什么不能就地渲染：`position:fixed` 会被**祖先的 transform / filter / contain 困住**\n       —— 宿主的右侧栏是滑入的（有 transform），那一层就成了 containing block，\n       `fixed` 于是变成「相对侧边栏」而不是视口，于是只能盖住面板那一块（用户实测如此）。\n       这是 CSS 逃不出来的坑，只有 portal 能解。取不到 react-dom（老宿主 / 测试替身）就退回就地渲染。 */\n    const ReactDOM = (() => { try { return require('react-dom') } catch { return null } })()\n    const h = React.createElement\n\n    /* ── 国际化（DSH 官方 ctx.locale）─────────────────── */\n\n    /** 本插件在 DSH locale 注册表里的命名空间。 */\n    const NS = 'knit'\n\n    /** 中文词典（源语言）。 */\n    const ZH = {\n      'type.label': 'Knit',\n      'guide.title': 'Knit 最近文档',\n      'guide.description': '按对话相关性排序，点开就地预览',\n      'entry.label': 'Knit 最近文档',\n\n      'count': '{n} 篇',\n      'count.filtered': '{hit} / {total} 篇',\n      'count.code': '{n} 个代码文件',\n      'count.code.filtered': '{hit} / {total} 个代码文件',\n      'count.media': '{n} 个媒体',\n      'count.media.filtered': '{hit} / {total} 个媒体',\n      'action.refresh': '刷新',\n      'path.openTitle': '在文件管理器中打开',\n      'peek.empty': '这个工作区里还没有 Markdown 文档。',\n      'action.refreshNow': '立即刷新',\n\n      'sort.relevance': '相关',\n      'sort.time': '最新',\n      'sort.mediaTimeTitle': '图片一律按时间排序（最新在前）',\n      'sort.relevanceTitle': '按与当前对话的相关性排序（纯本地关键词匹配，不调模型）',\n      'sort.timeTitle': '按文件修改时间倒序',\n\n      'kind.doc': '文档',\n      // v0.19：「代码」这一档。文案口径刻意保持朴素 —— 不写「代码知识库 / AI Code\n      //   Intelligence / 智能代码分析」。Knit 只是把**当前任务真正需要的**代码文件\n      //   纳入同一份 Context Pack，它不是代码浏览器、不是 grep、不是 IDE（需求 §44）。\n      'kind.code': '代码',\n      // ⚠️ 2026-10-06 用户定：类型页签与「全部」分区标题都用**「媒体」**，不用「图片与视频」\n      //    （原话：「我想修改成 媒体 或者 多媒体，你觉得呢？」→ 随后确认「媒体」）。\n      //    理由：① 这一档的计数本来就是「{n} 个媒体」（count.media），页签叫「图片与视频」\n      //    是唯一的例外；② 「多媒体」在中文 IT 语境里带 AV / 课件味，还暗示音频，而这一档\n      //    只扫图片与视频（宿主按扩展名放行，没有音频）；③ 「媒体」省 3 个字，窄侧栏少一次\n      //    省略号。**含义由空态说明**（list.emptyMedia 仍写「还没有图片或视频」）。\n      'kind.media': '媒体',\n      'kind.title': '切换要列出的产物类型',\n\n      'filter.placeholder': '过滤文档',\n      'filter.aria': '过滤文档',\n\n      'usage.toggle': '使用情况',\n      'usage.toggleTitle': '打开后开始统计这个会话：先看的那篇有没有被读、有多少次读落在包外、上下文换过几回。只记事实，不给分数。',\n      'usage.none': '还没有记录',\n      'usage.note': '只统计本会话 · 数据在内核内存里，重启 DSH 就没了',\n\n      // ── v0.18 Context Usage Lens ────────────────────────────────\n      // 这一层只回答一件事：「Knit 交出去的那份 Context，被怎样消费了」。\n      // ⚠️ 它**不是** Dashboard：没有 KPI 大数字、没有百分比、没有评分、没有图表、\n      //    没有进度条、没有「使用率 / 健康度 / 认可度」。字号一律弱于文档标题 ——\n      //    层级只靠空间与灰阶（AGENTS.md §6.3 / §7.1）。\n      // ⚠️ 每一条都是**事实陈述**，不是评价：不许写成「Agent 没看这篇 / 用错了 /\n      //    Knit 漏了 / 推荐得不准」。「最近读取」也不是「正在阅读」—— 证明不了。\n      'lens.title': '使用情况',\n      'lens.expand': '展开使用情况',\n      'lens.collapse': '收起使用情况',\n      'lens.epoch': 'Epoch {n}',\n      'lens.reads': '{n} 次读取',\n      'lens.outside': '{n} 篇包外',\n      'lens.changes': '上下文变化 {n} 次',\n      'lens.currentContext': '当前上下文',\n      'lens.recentRead': '最近读取',\n      'lens.recentNone': '暂无记录',\n      'lens.outsideDocs': '上下文外读取',\n      'lens.more': '还有 {n} 篇',\n      'lens.openDoc': '打开 {rel}',\n      'lens.delta': '上下文变化',\n      'lens.locate': '定位到{tier}上下文',\n      // 读屏专用（md §六十三）：**屏幕上不出现这句话**，视觉给的是「层名 + n / m + 圆点」。\n      'lens.coverageAria': '{tier}上下文：{read} / {total} 篇已读',\n      // 上下文变化那一行的右侧说明（md §三十八「上下文变化　最近一次 ›」）：\n      // 变化永远只说**最近一次**，所以这里不写条数（条数由展开后的行数承担）。\n      'lens.deltaLatest': '最近一次',\n\n      // ── v0.17 文档生命周期（Document Lifecycle）──────────────────\n      // ⚠️ 四态全是**事实**，不是评价：「读后已更新」只说「文件在最后一次成功读取之后\n      //    变过」，绝不许写成「Agent 还不知道最新版本」「Agent 用了旧版本」这类推断。\n      // ⚠️ 「上下文外读取」只陈述「这篇不在当前包内、但被成功读过」。\n      // ⚠️ `readCountShort` 是给行尾用的：行首的 glyph 已经说了「读过了」，\n      //    行尾只需要补一个「几次」—— 再说一遍「已读」是重复信息。\n      'usage.deltaEnter': '进入',\n      'usage.deltaLeave': '离开',\n      'usage.deltaMove': '换层',\n      'usage.deltaTask': '任务上下文已更新',\n      'usage.deltaMore': '还有 {n} 条',\n      'lifecycle.unread': '未读',\n      'lifecycle.read': '已读',\n      'lifecycle.readCount': '已读 ×{n}',\n      'lifecycle.readCountShort': '×{n}',\n      'lifecycle.updatedAfterRead': '读后已更新',\n      'lifecycle.rereadAfterUpdate': '修改后已重新读取',\n      'tierName.primary': '主要',\n      'tierName.supporting': '辅助',\n      'tierName.related': '相关',\n\n      // ── v0.14 当前任务上下文（Context Pack）──────────────────────\n      // ⚠️ 文案纪律：不出现「AI / 智能 / 推荐 / 置信度 / 百分比」。\n      // 这一层是确定性规则算出来的，说成 AI 就是在骗用户。也不能放表情符号\n      // （test/i18n.test.mjs 有守卫）。\n      // ⚠️ 这里只剩**分组**与**理由**的文案（2026-09-29）：右栏那个\n      // 「当前任务上下文」面板整个删掉了 —— Context Pack 是**数据层**结构\n      // （Primary / Supporting / Related），不是一张要单独显示的卡片。\n      // 所以 `context.title` / `matched` / `task*` / `evidence*` / `ev*` /\n      // `float` / `dock` / `dragHint` / `gripAria` 这些词条一起删了：\n      // 不留在词典里当死键，否则下一个人会以为那个面板还在。\n      'context.primary': '主要上下文',\n      'context.supporting': '辅助上下文',\n      'context.related': '相关上下文',\n      'context.other': '其他相关文档',\n      // 提示词**极短**（用户要求）：长副标题会把分组标题读成说明文。\n      'context.primaryHint': '先看',\n      'context.supportingHint': '辅助',\n      'context.relatedHint': '背景',\n      'context.why': '为什么在这里',\n      // ── v0.21 上下文控制（固定 / 排除）与关系来源 ────────────────────\n      // ⚠️ 三个来源词是**中性词**：来源只说明「它怎么进来的」，不表达强弱。\n      //    所以它们一色到底（都是 caption 灰），靠**字**区分，不靠颜色。\n      'context.pinned': '固定上下文',\n      'context.pinnedHint': '你自己标记的',\n      // v0.25：Git 变更关联。**与三层平行的一区**，不参与 01…0N 的编号。\n      'context.changes': '变更关联',\n      'context.changesHint': '由未提交的改动牵出来的',\n      'context.changesEmpty': '{files} 个变更文件，没有找到关联证据',\n      'context.changesUnreadable': '读不到 Git 变更状态：{reason}',\n      'prov.retrieval': '检索',\n      'prov.relation': '关系',\n      'prov.manual': '用户固定',\n      // v0.23：第四档来源。它**只**由「标题 + 摘要」的向量与任务相似而来 ——\n      // 不是关键词命中、也不是关系证据，而且只可能落在「相关」那一层。\n      'prov.semantic': '语义相关',\n      'prov.change': '变更关联',\n      'control.pin': '固定',\n      'control.unpin': '取消固定',\n      'control.exclude': '排除',\n      'control.restore': '恢复',\n      'control.excluded': '被用户排除：{rel}',\n      'control.failed': '操作没生效：{error}',\n      // 行级证据（需求 §6.2）：类型 + 方向 + 谁 + 第几行 + 打开。点「为什么」才展开。\n      'rel.toggle': '点开看这一行的证据',\n      'rel.references': '引用',\n      'rel.imports': '导入',\n      'rel.tests': '测试',\n      'rel.documents': '描述',\n      'rel.line': '第 {line} 行',\n      'rel.open': '打开',\n      'rel.more': '共 {n} 条关系，每项最多投影 {max} 条（预算，不是建议）',\n      // 检索状态摘要（需求 §6.3）：**分组与顺序本身就是这条设计要传达的信息** ——\n      // 工作区候选 ｜ 检索与调整 ｜ 最终结果；三组之间是细竖线，组内是中点（见 CSS 的 .knit-pipe）。\n      // ⚠️ 每一格都是**已经发生过的事实**，不是估算，也不许改成别的口径（见宿主侧注释）。\n      'pipe.collect': '收集 {n}',\n      'pipe.exclude': '排除 {n}',\n      // v0.21.x（2026-10-09 用户规格）：排除之后的候选数原来是一个**光数字**（只有\n      // 「→ 79」），现在给它一个名字 —— 状态摘要里每一格都必须能独立读懂。\n      'pipe.candidates': '候选 {n}',\n      'pipe.rank': 'BM25 检索',\n      // ⚠️ 「关系 N 条」说的是**这一份包里带了几条关系证据**（三层各条 relations 之和），\n      // 不是工作区里的关系总数、也不是候选数（那两类数字宿主另有字段，这里不展示）。\n      'pipe.relations': '关系 {n} 条',\n      // v0.25：状态行里那一格（**默认关**）。关着也出现 —— 藏起来用户就永远打不开这个功能。\n      'pipe.changesOff': '变更',\n      'pipe.changesOn': '变更 {n}',\n      'pipe.changesUnavailable': '变更 —',\n      'changes.titleOff': '按 Git 变更查找需要一起检查的文件（只读：只跑一条 git status，不执行任何写操作）',\n      'changes.titleOn': '{files} 个变更文件 · {related} 条关联证据 · 点一下关闭',\n      'changes.titleUnavailable': '读不到 Git 变更状态：{reason}',\n      'changes.reason.notARepo': '不是 Git 工作区',\n      'changes.reason.gitMissing': '找不到 git 命令',\n      'changes.reason.timeout': 'git 读取超时',\n      'changes.reason.tooLarge': 'git 输出过大（已截断）',\n      'changes.reason.failed': 'git 读取失败',\n      'changes.reason.request': '变更关联接口请求失败',\n      'changes.reason.unknown': '原因未知',\n      // ⚠️ 「固定 N」= 有几篇被你固定、因此**从三层移出**进了固定区（pack.pinned 的长度）。\n      // 不写「固定覆盖」这种内部说法；也不带量词 —— 固定对象可能是文档、代码或媒体。\n      'pipe.pin': '固定 {n}',\n      'pipe.pack': '入包 {n}',\n      // v0.23（Phase A）：混合检索。**默认词法** —— 这一格说的是实际生效的模式，不是用户的点击。\n      'pipe.rankHybrid': 'BM25 + 语义补充',\n      // 语义候选**只计数**（Phase A 不进包）。它是「有界」的：上限由消融定（方案 §5.2）。\n      'pipe.semantic': '语义候选 {n} 条',\n      // 检索模式选择器（工具栏第三组）\n      'sem.mode.aria': '检索模式',\n      'sem.mode.lexical': '词法',\n      'sem.mode.hybrid': '混合',\n      'sem.mode.lexicalTitle': '词法检索：BM25 + IDF，纯本地、零模型调用（默认）',\n      'sem.mode.hybridTitle': '混合检索（实验）：在词法候选之外补充语义候选；需要先配置 provider',\n      // ⚠️ 2026-10-13：原来的 sem.mode.lexicalShort / hybridShort 两个**短标签键已删除** ——\n      // 检索方式的可见文案改成状态行的 pipe.rank / pipe.rankHybrid（实际生效的模式），\n      // 键留着只会变成没人渲染的死键（i18n 的键集对齐守卫也查不出「定义了但没人用」）。\n      // 菜单里两个选项的副文案（长解释收进菜单，工具栏不再挤第三组）\n      'sem.mode.lexicalOption': '词法检索',\n      'sem.mode.hybridOption': '混合检索 · 实验',\n      'sem.mode.lexicalDesc': '默认模式；沿用当前 BM25 + IDF 排序。',\n      'sem.mode.hybridDesc': '在词法候选之外补充语义候选；需先配置 provider。',\n      // 菜单底部的**状态行**（如实说这一档现在到底生效成什么，不美化）\n      'sem.state.lexical': '当前按词法检索。',\n      'sem.state.hybridLive': '混合已生效：语义候选只追加在「相关」层最后，主要 / 辅助两层不动。',\n      'sem.state.noProvider': '未配置 provider —— 混合还没生效。',\n      // 就地配置入口（未配 provider 时菜单里那一条）\n      'sem.cfg.show': '配置语义 provider…',\n      'sem.cfg.hide': '收起配置',\n      // 混合没生效时的**事实**（宿主只给码，文案在这里）\n      'sem.reason.noProvider': '混合检索不可用：还没有配置 provider',\n      'sem.reason.probeFailed': '混合检索不可用：provider 连不上',\n      'sem.reason.timeout': '混合检索不可用：provider 超时',\n      'sem.reason.badResponse': '混合检索不可用：provider 返回了无法解析的结果',\n      'sem.reason.noQuery': '混合检索不可用：这一轮没有可用的查询文本',\n      'sem.reason.unknown': '混合检索不可用：原因未知（已退回词法）',\n      // 防御性：时间序下宿主整层短路，回的是这个码（界面极少走到 —— 那档根本不出现这个下拉）\n      'sem.reason.notApplicable': '混合检索不适用：时间序没有相关性分层（已按词法）',\n      // 老宿主没有 `semantic` 字段 ⇒ 如实说是宿主的问题，不让用户去配一个用不上的 provider\n      'sem.unsupported': '混合检索不可用：当前宿主版本不支持（已退回词法）',\n      // 最小配置区（就地一行，不是面板）\n      'sem.kindAria': 'provider 类型',\n      'sem.kind.ollama': 'Ollama（本地）',\n      'sem.kind.openai': 'OpenAI 兼容',\n      'sem.basePlaceholder': '服务地址，如 http://127.0.0.1:11434',\n      'sem.baseAria': 'provider 服务地址',\n      'sem.modelPlaceholder': '模型名，如 nomic-embed-text',\n      'sem.modelAria': 'provider 模型名',\n      'sem.save': '保存并测试',\n      'sem.saving': '测试中…',\n      'sem.saveTitle': '保存配置并让宿主探测一次（会发一次请求）',\n      'sem.savedOk': '已保存：provider 可用',\n      'sem.savedFail': '已保存，但 provider 现在还不可用',\n      // ⚠️ 披露措辞不许含糊：回环 = 不离开本机；其余一律明写「会发送到 <地址>」\n      'sem.disclose.local': '本地服务：内容不离开这台机器',\n      'sem.disclose.empty': '填上服务地址后，这里会写明内容会不会离开这台机器',\n      'sem.disclose.remote': '内容会发送到你配置的服务 {base}',\n      // 理由码 → 文案。宿主只给码（AGENTS.md §4.5），翻译在这里。\n      // ⚠️ 2026-09-29 用户要求把这行压得更克制：原来是「直接命中当前话题：…」，\n      // 读起来像调试信息。现在它是**标签 + 值**，词之间用「 · 」分隔。\n      // ⚠️ 2026-10-07 用户裁决（去掉中文全角冒号）：这一族标签原来是\n      // 「直接命中」「标题命中」后面跟一个全角冒号。全角冒号在中文里占**一个整字宽**\n      // 且强制一个停顿 —— 这一行是 metadata，两个标签并排时显得很重；去掉后\n      // 「命中在前、值紧随」，也正是用户要的阅读顺序。**冒号只在「引出列表」时保留**\n      // （正文里的句子照旧，见 `list.failed` 这类），**英文保留 ASCII 冒号**：\n      // 它只占半个字宽，而且英文靠它把标签和值绑在一起。\n      'why.direct': '直接命中 {term}',\n      'why.titleMatch': '标题命中 {term}',\n      // v0.19：代码占的是 `title` / `summary` 两个槽位（文件名、所在目录），\n      // 但**不能**对 `.ts` 文件说「标题命中」—— 判据一样，称谓必须分开。\n      // 这两个码由宿主直接给出（`context.js` 的 `explainContext()`），\n      // 客户端不做 kind → key 的重映射：宿主给什么码就翻什么码。\n      'why.filenameMatch': '文件名命中 {term}',\n      'why.pathMatch': '路径命中 {term}',\n      'why.summaryMatch': '摘要命中 {term}',\n      'why.bodyMatch': '正文命中 {term}',\n      'why.bodyMatchPlain': '正文命中',\n      'why.linkTarget': '被主要上下文引用',\n      'why.linkSource': '引用了主要上下文',\n      'why.related': '与当前任务相关',\n      // v0.23：语义补进来的理由。**只陈述可复核的事实**（标题 + 摘要的向量与任务相似），\n      // 不许写成「模型觉得相关」这类不可核查的话。\n      'why.semantic': '语义相关',\n\n      'row.tooltip': '{path}\\n单击就地预览 · 双击在新标签页打开',\n      /* v0.20：命中片段（需求 §12）。**纯 metadata**：行号区间，不是分数、不是评分、\n         不是「相关度 92%」。点击＝就地预览并跳到那一段（代码可跳，Markdown 见已知限制）。 */\n      'row.passages': '命中段 {range}',\n      'summary.empty': '（没有正文摘要）',\n\n      'list.scanning': '正在扫描工作区…',\n      'list.failed': '读取失败：{error}',\n      'list.failedHint': '确认插件宿主半边已加载。',\n      'list.empty': '这个工作区里还没有 Markdown 文档。',\n      'list.emptyCode': '这个工作区里还没有可纳入上下文的代码文件。',\n      'list.emptyMedia': '这个工作区里还没有图片或视频。',\n      'list.noMatch': '没有匹配「{query}」的文档。',\n      // 文档列表这个 listbox 的无障碍名字（原先硬编码在 JSX 里，英文界面下会漏出中文）\n      'list.aria': '最近文档',\n\n      // 相对时间。⚠️ 这六条原先**硬编码在 relTime() 里**，英文界面下会漏出中文\n      // （2026-09-19 被真机截图抓出来的）。**加时间粒度时必须同时加中英两条。**\n      'time.justNow': '刚刚',\n      'time.minutesAgo': '{n}分钟前',\n      'time.hoursAgo': '{n}小时前',\n      'time.yesterday': '昨天',\n      'time.daysAgo': '{n}天前',\n      'time.monthDay': '{month}月{day}日',\n\n      'media.play': '播放视频',\n\n      // 「全部」的分区：类型名复用 kind.doc / kind.media，这里只补计数与跳转\n\n      'preview.loading': '正在读取…',\n      'preview.truncated': '（文件较大，仅预览前 512 KB）',\n      // v0.25 预览里的查找（Cmd+F）。数字用 {current}/{total}，两种语言同形。\n      'lightbox.aria': '查看大图：{name}',\n      'lightbox.close': '关闭（Esc）',\n      'attach.badge': '对话',\n      'attach.title': '对话里生成的图，还没保存到本地',\n      'fav.off': '收藏',\n      'fav.on': '已收藏',\n      'fav.addTitle': '收藏（排在媒体列表最前面）',\n      'fav.removeTitle': '取消收藏',\n      'fav.mark': '已收藏',\n      'find.openBtn': '查找',\n      'find.openTitle': '在本文里查找（Cmd+F）',\n      'find.placeholder': '在本文里查找',\n      'find.aria': '在预览的文档里查找',\n      'find.count': '{current}/{total}',\n      'find.none': '无结果',\n      'find.prev': '上一个',\n      'find.next': '下一个',\n      'find.close': '关闭查找',\n      'preview.fullscreen': '全屏',\n      'preview.exitFullscreen': '退出全屏',\n      'preview.fullscreenTitle': '全屏阅读',\n      'preview.exitFullscreenTitle': '退出全屏（Esc）',\n      // v0.19 追加：HTML 的「网页预览」入口。\n      // 就地预览给的是**源码**，这个按钮开的是**官方文档预览标签页** ——\n      // 那一侧有 DSH 自带的 HTML 渲染器（`extensions:['html','htm']`，默认走静态档：\n      // 清洗过的完整文档 + 不给任何 sandbox 权限的 iframe + 摆在 `<head>` 最前的 CSP，\n      // 挡脚本 / 外部资源 / 表单 / 嵌套框架，内联 `<style>` 与 `data:` 图片保留）。\n      // 两者**不重复**，所以它不是把 v0.10 撤掉的那个「新标签页」按钮原样搬回来。\n      'preview.openWeb': '网页预览',\n      'preview.openWebTitle': '{path}\\n在官方文档预览里按网页渲染',\n      'preview.openLocal': '{path}\\n用系统默认应用打开这篇文档',\n      'preview.openLocalBtn': '本地打开',\n      // 面包屑那条路径点开的是**文件管理器里这个文件所在的位置**（并把文件选中），\n      // 不是「打开文件」—— 那是页脚「本地打开」的事，所以文案也得说清。\n      'preview.reveal': '{path}\\n在文件管理器中显示并选中这个文件',\n      'preview.close': '收起预览',\n      // v0.19：同名 source map 的入口。**它是低权重动作，不是文件列表条目** ——\n      //   `.map` 不参与检索、不进上下文、不进代码列表（需求 §6 §28），\n      //   只有用户在这个 .js 的预览里主动点它才会打开，且以纯文本/JSON 呈现。\n      'preview.sourceMap': 'Source map',\n      'preview.sourceMapTitle': '查看同名 source map（不进入上下文检索）',\n      // v0.19：代码预览的两条边界提示。\n      //   `codeTruncated` —— 渲染侧的行数上限（与宿主 512 KB 字节上限是两道不同的闸门）。\n      //   `copyFailed` —— 剪贴板两条路都失败时才出现。**不能静默**：点了没反应，\n      //   用户会以为是按钮坏了，而不是「浏览器不给权限」。\n      'preview.codeTruncated': '（文件较大，仅显示前 {n} 行）',\n      'preview.copyFailed': '复制失败，请手动选择文本',\n      'preview.resizeTitle': '拖动调整高度',\n      // v0.12 引用条。⚠️ 不放任何表情符号（test/i18n.test.mjs 有守卫）。\n      'links.summary': '被引用 {in} · 引用了 {out}',\n      'links.incoming': '被引用',\n      'links.outgoing': '引用了',\n      'links.noneIn': '没有被引用',\n      'links.noneOut': '没有引用别的文档',\n      'links.more': '还有 {count} 篇',\n      'links.failed': '引用关系读取失败',\n      'links.incomplete': '工作区较大，结果可能不完整',\n      'preview.rawFallback': '原生 Markdown 渲染不可用，下面是纯文本。请看控制台的 [knit] 日志。',\n      'code.copy': '复制',\n      'code.copied': '已复制',\n\n      'error.noSession': '当前 tab 没有 sessionId',\n      'error.hostFailed': '宿主返回失败',\n      'error.noHostTab': '当前宿主没有提供「在新标签页打开」',\n      'error.noOpenResource': '座位没有提供 tab.actions.openResource',\n      'error.openFailed': '打开失败：{error}',\n      'error.bsNoContext': 'better-sidebar 上下文不可用',\n      'error.bsNoService': 'betterSidebar 服务不可用',\n      'error.bsEditorDisabled': 'better-sidebar 的「编辑器」标签页被禁用了（设置 → 侧边卡片）',\n\n      'host.outsideWorkspace': '路径越出工作区',\n      // v0.19：从 `host.markdownOnly`（「只支持 Markdown」）改名。能力已经不止\n      //   Markdown 了，文案必须跟着说清**真正的**边界：这个类型不支持在面板里预览。\n      'host.notPreviewable': '这个类型不支持在面板里预览',\n      'host.notFound': '文件不存在',\n      'host.notAFile': '不是普通文件',\n      'host.imageOnly': '只允许图片类型',\n      'host.imageTooLarge': '图片过大',\n      'host.mediaOnly': '仅支持图片或视频类型',\n      'host.mediaTooLarge': '视频过大',\n      'host.readFailed': '读取失败',\n      'host.missingRel': '缺少 rel 参数',\n      'host.internal': '宿主内部错误',\n    }\n\n    /** 英文词典。键必须与 ZH 完全一致（有测试守着）。 */\n    const EN = {\n      'type.label': 'Knit',\n      'guide.title': 'Knit — recent documents',\n      'guide.description': 'Relevance-sorted, click to preview in place',\n      'entry.label': 'Knit — recent documents',\n\n      'count': '{n} docs',\n      'count.filtered': '{hit} / {total} docs',\n      'count.code': '{n} code files',\n      'count.code.filtered': '{hit} / {total} code files',\n      'count.media': '{n} media',\n      'count.media.filtered': '{hit} / {total} media',\n      'action.refresh': 'Refresh',\n      'path.openTitle': 'Open in file manager',\n      'peek.empty': 'No Markdown documents in this workspace yet.',\n      'action.refreshNow': 'Refresh now',\n\n      'sort.relevance': 'Relevant',\n      'sort.time': 'Recent',\n      'sort.mediaTimeTitle': 'Images are always sorted by newest first',\n      'sort.relevanceTitle': 'Sort by relevance to the current conversation (local keyword matching, no model call)',\n      'sort.timeTitle': 'Sort by file modified time, newest first',\n\n      'kind.doc': 'Docs',\n      'kind.code': 'Code',\n      // 2026-10-06: user picked 「媒体」 for the tab + the \"All\" section title, so English\n      // follows the same word as count.media (\"{n} media\"): the tab says Media, and the\n      // explicit \"images and videos\" wording stays in the empty state / README prose.\n      'kind.media': 'Media',\n      'kind.title': 'Switch which artifacts are listed',\n\n      'filter.placeholder': 'Filter docs',\n      'filter.aria': 'Filter documents',\n\n      'usage.toggle': 'Usage',\n      'usage.toggleTitle': 'Measure this session: whether the primary doc was read, how many reads fell outside the pack, how often the context changed. Facts only — no score.',\n      'usage.none': 'Nothing recorded yet',\n      'usage.note': 'This session only · kept in kernel memory, gone after a DSH restart',\n\n      // ── v0.18 Context Usage Lens ───────────────────────────────\n      // Answers exactly one question: how was the context Knit handed over actually\n      // consumed. ⚠️ Not a dashboard: no KPI figures, no percentages, no scores, no\n      // charts, no progress bars, no \"usage rate / health / confidence\". Every line is\n      // a fact, never a judgement — and \"recent read\" is not \"currently reading\".\n      'lens.title': 'Usage',\n      'lens.expand': 'Expand usage',\n      'lens.collapse': 'Collapse usage',\n      'lens.epoch': 'Epoch {n}',\n      'lens.reads': '{n} reads',\n      'lens.outside': '{n} outside the pack',\n      'lens.changes': 'context changed {n}×',\n      'lens.currentContext': 'Current context',\n      'lens.recentRead': 'Recent read',\n      'lens.recentNone': 'Nothing yet',\n      'lens.outsideDocs': 'Reads outside context',\n      'lens.more': '{n} more',\n      'lens.openDoc': 'Open {rel}',\n      'lens.delta': 'Context changes',\n      'lens.locate': 'Locate {tier} context',\n      'lens.coverageAria': '{tier} context: {read} / {total} read',\n      'lens.deltaLatest': 'Latest',\n\n      // ── v0.17 document lifecycle ───────────────────────────────\n      // ⚠️ All four states are facts, never judgements: \"Updated after read\" only says the\n      //    file changed after the last successful read. Never \"the agent has not seen the\n      //    latest version\" or \"the agent used a stale copy\" — that would be inference.\n      // ⚠️ `readCountShort` is for the row tail: the leading glyph already says it was\n      //    read, so the tail only adds the count — repeating \"read\" would be redundant.\n      'usage.deltaEnter': 'Entered',\n      'usage.deltaLeave': 'Left',\n      'usage.deltaMove': 'Moved tier',\n      'usage.deltaTask': 'Task context updated',\n      'usage.deltaMore': '+{n} more',\n      'lifecycle.unread': 'Unread',\n      'lifecycle.read': 'Read',\n      'lifecycle.readCount': 'Read ×{n}',\n      'lifecycle.readCountShort': '×{n}',\n      'lifecycle.updatedAfterRead': 'Updated after read',\n      'lifecycle.rereadAfterUpdate': 'Re-read after update',\n      'tierName.primary': 'Primary',\n      'tierName.supporting': 'Supporting',\n      'tierName.related': 'Related',\n\n      // ── v0.14 current-task context (Context Pack) ──────────────\n      // ⚠️ Never say \"AI\", \"smart\", \"recommended\", \"confidence\" or show percentages:\n      // this tiering is deterministic local rules, and pretending otherwise is a lie.\n      // ⚠️ Only **group** and **reason** labels live here now (2026-09-29): the\n      // right-hand \"Current task context\" panel was deleted — a Context Pack is a\n      // **data-layer** structure (Primary / Supporting / Related), not a card.\n      // `context.title` / `matched` / `task*` / `evidence*` / `ev*` / `float` /\n      // `dock` / `dragHint` / `gripAria` went with it, so no dead keys remain.\n      'context.primary': 'Primary',\n      'context.supporting': 'Supporting',\n      'context.related': 'Related',\n      'context.other': 'Other documents',\n      // Hints are deliberately **tiny**: a long subtitle turns a group title into prose.\n      'context.primaryHint': 'read first',\n      'context.supportingHint': 'supporting',\n      'context.relatedHint': 'background',\n      'context.why': 'Why it is here',\n      // ── v0.21 context control (pin / exclude) and relation provenance ──\n      // ⚠️ The three provenance words are **neutral**: provenance says how an item got\n      //    in, not how strong it is — so they share one colour and differ by word.\n      'context.pinned': 'Pinned',\n      'context.pinnedHint': 'you marked these',\n      'context.changes': 'Tied to changes',\n      'context.changesHint': 'pulled in by your uncommitted edits',\n      'context.changesEmpty': '{files} changed file(s), no related evidence found',\n      'context.changesUnreadable': 'Git change status unavailable: {reason}',\n      'prov.retrieval': 'retrieved',\n      'prov.relation': 'relation',\n      'prov.manual': 'pinned',\n      // v0.23: the fourth provenance (semantic) — same neutral, lowercase word group.\n      'prov.semantic': 'semantic',\n      'prov.change': 'change',\n      'control.pin': 'Pin',\n      'control.unpin': 'Unpin',\n      'control.exclude': 'Exclude',\n      'control.restore': 'Restore',\n      'control.excluded': 'Excluded by you: {rel}',\n      'control.failed': 'Action failed: {error}',\n      'rel.toggle': 'open the evidence for this line',\n      'rel.references': 'references',\n      'rel.imports': 'imports',\n      'rel.tests': 'tests',\n      'rel.documents': 'documents',\n      'rel.line': 'line {line}',\n      'rel.open': 'Open',\n      'rel.more': '{n} relations total, at most {max} projected per item',\n      'pipe.collect': '{n} collected',\n      'pipe.exclude': '{n} excluded',\n      'pipe.candidates': '{n} candidates',\n      'pipe.rank': 'BM25 retrieval',\n      'pipe.relations': '{n} relations',\n      'pipe.changesOff': 'Changes',\n      'pipe.changesOn': 'Changes {n}',\n      'pipe.changesUnavailable': 'Changes —',\n      'changes.titleOff': 'Find the files to check alongside your Git changes (read-only: one git status, no write commands)',\n      'changes.titleOn': '{files} changed file(s) · {related} related by evidence · click to turn off',\n      'changes.titleUnavailable': 'Git change status unavailable: {reason}',\n      'changes.reason.notARepo': 'not a Git working tree',\n      'changes.reason.gitMissing': 'git command not found',\n      'changes.reason.timeout': 'git timed out',\n      'changes.reason.tooLarge': 'git output too large (truncated)',\n      'changes.reason.failed': 'git read failed',\n      'changes.reason.request': 'the change-links request failed',\n      'changes.reason.unknown': 'unknown reason',\n      'pipe.pin': '{n} pinned',\n      'pipe.pack': '{n} in pack',\n      // v0.23 (Phase A): hybrid retrieval. This cell states the mode **in effect**, not the click.\n      'pipe.rankHybrid': 'BM25 + semantic',\n      'pipe.semantic': '{n} semantic candidates',\n      'sem.mode.aria': 'Retrieval mode',\n      'sem.mode.lexical': 'Lexical',\n      'sem.mode.hybrid': 'Hybrid',\n      'sem.mode.lexicalTitle': 'Lexical retrieval: BM25 + IDF, fully local, no model call (default)',\n      'sem.mode.hybridTitle': 'Hybrid retrieval (experimental): adds semantic candidates on top of lexical ones; needs a configured provider',\n      'sem.mode.lexicalOption': 'Lexical retrieval',\n      'sem.mode.hybridOption': 'Hybrid retrieval · experimental',\n      'sem.mode.lexicalDesc': 'Default: keeps the current BM25 + IDF ranking.',\n      'sem.mode.hybridDesc': 'Adds semantic candidates on top of the lexical ones; needs a configured provider.',\n      'sem.state.lexical': 'Currently lexical retrieval.',\n      'sem.state.hybridLive': 'Hybrid is live: semantic candidates are appended to the related tier only; primary and supporting are unchanged.',\n      'sem.state.noProvider': 'No provider configured — hybrid is not active yet.',\n      'sem.cfg.show': 'Configure semantic provider…',\n      'sem.cfg.hide': 'Hide configuration',\n      'sem.reason.noProvider': 'Hybrid retrieval unavailable: no provider configured yet',\n      'sem.reason.probeFailed': 'Hybrid retrieval unavailable: provider is unreachable',\n      'sem.reason.timeout': 'Hybrid retrieval unavailable: provider timed out',\n      'sem.reason.badResponse': 'Hybrid retrieval unavailable: provider returned an unusable response',\n      'sem.reason.noQuery': 'Hybrid retrieval unavailable: no usable query text this round',\n      'sem.reason.unknown': 'Hybrid retrieval unavailable: unknown reason (fell back to lexical)',\n      'sem.reason.notApplicable': 'Hybrid retrieval does not apply: a time-ordered list has no relevance tiers (kept lexical)',\n      'sem.unsupported': 'Hybrid retrieval unavailable: this host version does not support it (fell back to lexical)',\n      'sem.kindAria': 'Provider kind',\n      'sem.kind.ollama': 'Ollama (local)',\n      'sem.kind.openai': 'OpenAI-compatible',\n      'sem.basePlaceholder': 'Service URL, e.g. http://127.0.0.1:11434',\n      'sem.baseAria': 'Provider service URL',\n      'sem.modelPlaceholder': 'Model name, e.g. nomic-embed-text',\n      'sem.modelAria': 'Provider model name',\n      'sem.save': 'Save and test',\n      'sem.saving': 'Testing…',\n      'sem.saveTitle': 'Save the configuration and let the host probe it once (sends one request)',\n      'sem.savedOk': 'Saved: provider is available',\n      'sem.savedFail': 'Saved, but the provider is still unavailable',\n      'sem.disclose.local': 'Local service: content stays on this machine',\n      'sem.disclose.empty': 'Once a service URL is filled in, this line says whether content leaves this machine',\n      'sem.disclose.remote': 'Content will be sent to your configured service {base}',\n      // Reason codes → copy. The host only ships codes (AGENTS.md §4.5).\n      // ⚠️ Flattened on 2026-09-29: \"direct topic match: …\" read like debug output.\n      'why.direct': 'direct match: {term}',\n      'why.titleMatch': 'title match: {term}',\n      'why.filenameMatch': 'filename match: {term}',\n      'why.pathMatch': 'path match: {term}',\n      'why.summaryMatch': 'summary match: {term}',\n      'why.bodyMatch': 'body match: {term}',\n      'why.bodyMatchPlain': 'body match',\n      'why.linkTarget': 'referenced by a primary document',\n      'why.linkSource': 'references a primary document',\n      'why.related': 'related to the current task',\n      // v0.23: semantic match — states the verifiable fact (title + summary embedding),\n      // never \"the model thinks this is relevant\".\n      'why.semantic': 'semantic match',\n\n      'row.tooltip': '{path}\\nClick to preview here · double-click to open in a new tab',\n      /* v0.20：matched passage range (requirement §12) — metadata only, never a score. */\n      'row.passages': 'Passage: {range}',\n      'summary.empty': '(no summary)',\n\n      'list.scanning': 'Scanning the workspace…',\n      'list.failed': 'Failed to read: {error}',\n      'list.failedHint': 'Make sure the plugin’s host half is loaded.',\n      'list.empty': 'No Markdown documents in this workspace yet.',\n      'list.emptyCode': 'No code files eligible for context in this workspace yet.',\n      'list.emptyMedia': 'No images or videos in this workspace yet.',\n      'list.noMatch': 'No documents match “{query}”.',\n      // Accessible name of the document listbox (was hardcoded in JSX before)\n      'list.aria': 'Recent documents',\n\n      // Relative time. ⚠️ These six used to be **hardcoded inside relTime()** and leaked\n      // Chinese into the English UI (caught by a real-machine screenshot, 2026-09-19).\n      // **Add both languages whenever you add a granularity.**\n      'time.justNow': 'just now',\n      'time.minutesAgo': '{n} min ago',\n      'time.hoursAgo': '{n} h ago',\n      'time.yesterday': 'yesterday',\n      'time.daysAgo': '{n} d ago',\n      'time.monthDay': '{month}/{day}',\n\n      'media.play': 'Play video',\n\n      // \"All\" sections: titles reuse kind.doc / kind.media, only count + jump live here\n\n      'preview.loading': 'Loading…',\n      'preview.truncated': '(large file — showing the first 512 KB)',\n      'lightbox.aria': 'Image viewer: {name}',\n      'lightbox.close': 'Close (Esc)',\n      'attach.badge': 'Chat',\n      'attach.title': 'Generated in this chat — not saved locally yet',\n      'fav.off': 'Favorite',\n      'fav.on': 'Favorited',\n      'fav.addTitle': 'Favorite this (it moves to the front of the media list)',\n      'fav.removeTitle': 'Remove favorite',\n      'fav.mark': 'Favorited',\n      'find.openBtn': 'Find',\n      'find.openTitle': 'Find in this document (Cmd+F)',\n      'find.placeholder': 'Find in this document',\n      'find.aria': 'Find in the previewed document',\n      'find.count': '{current}/{total}',\n      'find.none': 'No results',\n      'find.prev': 'Previous',\n      'find.next': 'Next',\n      'find.close': 'Close find',\n      'preview.fullscreen': 'Fullscreen',\n      'preview.exitFullscreen': 'Exit fullscreen',\n      'preview.fullscreenTitle': 'Read fullscreen',\n      'preview.exitFullscreenTitle': 'Exit fullscreen (Esc)',\n      'preview.openWeb': 'Web preview',\n      'preview.openWebTitle': '{path}\\nRender as a web page in the official document preview',\n      'preview.openLocal': '{path}\\nOpen this document in your default app',\n      'preview.openLocalBtn': 'Open locally',\n      'preview.reveal': '{path}\\nShow this file in your file manager (and select it)',\n      'preview.close': 'Close preview',\n      'preview.sourceMap': 'Source map',\n      'preview.sourceMapTitle': 'View the sibling source map (not part of context retrieval)',\n      'preview.codeTruncated': '(large file — showing the first {n} lines)',\n      'preview.copyFailed': 'Copy failed — select the text manually',\n      'preview.resizeTitle': 'Drag to resize',\n      'links.summary': 'Referenced by {in} · links to {out}',\n      'links.incoming': 'Referenced by',\n      'links.outgoing': 'Links to',\n      'links.noneIn': 'Not referenced by anything',\n      'links.noneOut': 'Links to no other document',\n      'links.more': '{count} more',\n      'links.failed': 'Could not read references',\n      'links.incomplete': 'Large workspace — results may be incomplete',\n      'preview.rawFallback': 'Native Markdown rendering is unavailable — showing plain text. Check the [knit] logs in the console.',\n      'code.copy': 'Copy',\n      'code.copied': 'Copied',\n\n      'error.noSession': 'This tab has no sessionId',\n      'error.hostFailed': 'The host returned a failure',\n      'error.noHostTab': 'This host cannot open a new tab',\n      'error.noOpenResource': 'The seat did not provide tab.actions.openResource',\n      'error.openFailed': 'Open failed: {error}',\n      'error.bsNoContext': 'better-sidebar context is unavailable',\n      'error.bsNoService': 'The betterSidebar service is unavailable',\n      'error.bsEditorDisabled': 'better-sidebar’s Editor tab is disabled (Settings → Side card)',\n\n      'host.outsideWorkspace': 'Path escapes the workspace',\n      'host.notPreviewable': 'This type cannot be previewed here',\n      'host.notFound': 'File not found',\n      'host.notAFile': 'Not a regular file',\n      'host.imageOnly': 'Images only',\n      'host.imageTooLarge': 'Image too large',\n      'host.mediaOnly': 'Images or videos only',\n      'host.mediaTooLarge': 'Video too large',\n      'host.readFailed': 'Read failed',\n      'host.missingRel': 'Missing the rel parameter',\n      'host.internal': 'Internal host error',\n    }\n\n    /**\n     * 把 `{name}` 占位符换成实参。\n     * @param {string} template - 模板串\n     * @param {object} [params] - 实参\n     * @returns {string} 结果\n     */\n    function format(template, params) {\n      if (!params) return template\n      return template.replace(/\\{(\\w+)\\}/g, (whole, key) => (\n        Object.prototype.hasOwnProperty.call(params, key) ? String(params[key]) : whole\n      ))\n    }\n\n    /**\n     * 当前翻译函数。`apply` 时绑到 ctx.locale；未绑定时退回中文词典，\n     * 这样单测里不装 locale 也能直接渲染（真实运行时一定会绑）。\n     */\n    let t = (key, params) => format(ZH[key] !== undefined ? ZH[key] : key, params)\n\n    /**\n     * 宿主错误码 → 词典键。\n     *\n     * 宿主只返回机器可读的码，文案在这里翻译 —— 这样宿主与 UI 语言解耦。\n     * 未登记的码原样显示（便于发现宿主新增了码但忘了翻译）。\n     */\n    const HOST_ERROR_KEY = {\n      'knit/outside-workspace': 'host.outsideWorkspace',\n      'knit/not-previewable': 'host.notPreviewable',\n      'knit/not-found': 'host.notFound',\n      'knit/not-a-file': 'host.notAFile',\n      'knit/image-only': 'host.imageOnly',\n      'knit/image-too-large': 'host.imageTooLarge',\n      'knit/media-only': 'host.mediaOnly',\n      'knit/media-too-large': 'host.mediaTooLarge',\n      'knit/read-failed': 'host.readFailed',\n      'knit/missing-rel': 'host.missingRel',\n      'knit/internal': 'host.internal',\n    }\n\n    /**\n     * 把一个失败的宿主响应翻成当前语言的文案。\n     * @param {object} data - 宿主载荷\n     * @returns {string} 文案\n     */\n    function hostMessage(data) {\n      const code = data && data.code\n      if (!code) return t('error.hostFailed')\n      const key = HOST_ERROR_KEY[code]\n      return key ? t(key) : code\n    }\n\n    /**\n     * DSH 共享的 Markdown 渲染器（@deepseek-ai/dsh-client-ui-primitives 的 MarkdownText，\n     * 官方 ui-sidebar-documentpreview 与 dsh-better-sidebar 用的是同一个）。\n     *\n     * ⚠️ 它由 `React.memo()` 包出来，值是**对象**不是函数\n     * （`{ $$typeof: Symbol(react.memo), type: fn }`）。所以这里只能判空，\n     * 不能用 `typeof === 'function'` —— 那样会把可用的渲染器误判成不可用，\n     * 一路静默降级成纯文本（真实踩过的坑）。React 认这个对象形态，直接交给\n     * createElement 渲染即可。\n     */\n    let MarkdownText = null\n    try {\n      const primitives = require('@deepseek-ai/dsh-client-ui-primitives')\n      const candidate = primitives && primitives.MarkdownText\n      if (candidate !== undefined && candidate !== null) MarkdownText = candidate\n      else console.warn('[knit] ui-primitives does not export MarkdownText — preview falls back to plain text')\n    } catch (error) {\n      console.warn('[knit] could not load ui-primitives.MarkdownText — preview falls back to plain text', error)\n    }\n\n    /* ── 官方语法高亮器（v0.20，2026-10-07 用户新增需求）────────────────────\n       代码预览原本是**单色**（浅色黑 / 暗色白），用户的原话是「对于一个阅读代码\n       用户来说，可读性太低了」，并给了 DSH 自己那份带行号的代码视图当参照。\n\n       这里用的是**同一个包**里的 `useCodeHighlighter(language) → (code) =>\n       HighlightSpan[][]`。它的 `style.color` 一律是 `var(--shiki-*)`，而那张\n       调色板定义在 DSH 主题包里（浅色一套、`body[data-ds-dark-theme]` 一套）——\n       所以**我们一行颜色都不写**：既不会自己发明一套配色，也不会在某个主题下\n       悄悄写死白色（那正是上一轮暗色治理踩过的坑）。\n\n       ⚠️ 它是个 **hook**：必须**无条件**调用。所以缺包/缺导出时用下面这个同形状的\n       假 hook 顶上（返回的 highlighter 一律 `undefined` = 纯文本兜底），而不是在\n       组件里写「如果有就调用」—— 条件调用 hook 是 React 的硬错误。语法是**懒加载**\n       的（TypeScript / shell / JSON 启动即在，python、html、css、yaml 首次用到才\n       装载）：那一帧回落纯文本，hook 自己订阅了装载事件并会重渲染，我们不必插手。 */\n    let useCodeHighlighter = null\n    try {\n      const primitives = require('@deepseek-ai/dsh-client-ui-primitives')\n      const candidate = primitives && primitives.useCodeHighlighter\n      if (typeof candidate === 'function') useCodeHighlighter = candidate\n      else console.warn('[knit] ui-primitives does not export useCodeHighlighter — code preview falls back to plain text')\n    } catch (error) {\n      console.warn('[knit] could not load ui-primitives.useCodeHighlighter — code preview falls back to plain text', error)\n    }\n\n    /** 没有官方高亮器时 `(code) => undefined` —— 与官方同形状，调用方不必分叉。 */\n    const PLAIN_CODE_HIGHLIGHTER = () => undefined\n    /** 假 hook：恒等返回上面那个函数（引用稳定，可以安全当 memo 依赖）。 */\n    function usePlainCodeHighlighter() { return PLAIN_CODE_HIGHLIGHTER }\n    /** 真 hook 或假 hook，二选一 —— **在组件里永远是无条件调用**（见上）。 */\n    const useCodeSpans = useCodeHighlighter || usePlainCodeHighlighter\n\n    /* 高亮结果**按文件缓存**（v0.20 性能治理，2026-10-07）。官方高亮器实测 170–560 ms /\n       千行，而「关掉再点开同一篇」「切标签再回来」都会重新挂载 `CodePane` —— 不缓存就每次\n       从头再分词一遍。键 = `rel#行数`，命中时还比一次原文（原文变了就重算）；上限 8 篇，\n       够覆盖「来回点几篇」，又不会把整库正文吊在内存里（真机量到：点开 4000 行的文件\n       3459 ms、其中 1259 ms 就是分词；重开同一篇从 2155 ms 降到几十毫秒）。 */\n    const CODE_HL_CACHE = new Map()\n    function cachedCodeSpans(key, text, run) {\n      const hit = CODE_HL_CACHE.get(key)\n      if (hit && hit.text === text) { CODE_HL_CACHE.delete(key); CODE_HL_CACHE.set(key, hit); return hit.spans }\n      const spans = run()\n      CODE_HL_CACHE.set(key, { text, spans })\n      while (CODE_HL_CACHE.size > 8) CODE_HL_CACHE.delete(CODE_HL_CACHE.keys().next().value)\n      return spans\n    }\n\n    /* ── 常量 ───────────────────────────────────────── */\n\n    /** 官方右侧栏 tab 的身份，也是 body/title 注册用的 key。 */\n    const TAB_ID = 'dsh-knit:recent'\n    /** page 类型判别符；openTab('knit') 用它。 */\n    const KIND = 'knit'\n    /** better-sidebar 里这个 tab 的 id。 */\n    const BS_TAB_ID = 'knit:recent'\n\n    const LIST_API = '/knit/api/recent'\n    /* v0.25：Git 变更关联的**独立接口**。它与列表接口分开，所以「列表的响应形状」\n       不会被这个功能碰到；关掉功能时客户端连这个请求都不发。 */\n    const CHANGES_API = '/knit/api/changes'\n    /* v0.25：媒体档额外显示「对话里工具产出的图」——**独立接口**，`/api/recent` 一个字节没动。\n       列表零 I/O（元数据全在会话事件里）；字节按 **sha256** 取（见 `attachmentUrl`）。 */\n    const ATTACH_LIST_API = '/knit/api/attachments'\n    const ATTACH_RAW_API = '/knit/api/attachment'\n    const DOC_API = '/knit/api/doc'\n    const RAW_API = '/knit/api/raw'\n    // v0.12：某篇的「谁引用了它 / 它引用了谁」。与上面三条一样是**同源相对地址**，\n    // 所以仍然满足「客户端零网络出口」那条守卫（test/security.test.mjs）。\n    const LINKS_API = '/knit/api/links'\n    // v0.21：整个 HTTP 面**唯一**的写动作（固定 / 排除）。只回环、只 POST、只认\n    // `{action, rel}`；工作区根由 `sessionId` 解析 —— 与其余路由同一条纪律。\n    const CONTROL_API = '/knit/api/control'\n    // v0.21：**镜像**宿主的面板投影上限（`src/host/relations.js` 的\n    // `MAX_RELATIONS_PER_ITEM = 3`）。客户端只需要它来写「共 N 条关系，每项最多投影 3 条」\n    // 那句话 —— 真正的截断在宿主做，这里**不截断**（截断两次就会出现两份真相）。\n    // ⚠️ 两个数字必须一致：`test/client.test.mjs` 有一条源码级守卫同时读两侧。\n    const REL_MAX = 3\n\n    /** 轮询间隔。 */\n    const POLL_MS = 5000\n    /** 多久之内算「新」，打 🆕 标记。 */\n    const NEW_WINDOW_MS = 2 * 60 * 1000\n\n    /** 悬停偷看：进入后延迟显示，离开后延迟收起（避免误触与闪烁）。 */\n    const PEEK_SHOW_DELAY = 250\n    const PEEK_HIDE_DELAY = 200\n    /** 悬停浮层里最多列几篇。 */\n    const PEEK_LIMIT = 5\n\n    /** 用户偏好（选了就记住）。 */\n    const SORT_KEY = 'dsh-knit:sort'\n    const RATIO_KEY = 'dsh-knit:preview-ratio'\n    const KIND_KEY = 'dsh-knit:kind'\n    /**\n     * v0.15「使用情况」的开闸键。**默认关** —— 记账意味着每次轮询都要读一遍会话事件，\n     * 用户没要看这个之前，不该有人替他付出这个代价（也不该悄悄攒数据）。\n     */\n    const USAGE_KEY = 'dsh-knit:usage'\n\n    /* ── v0.23（Phase A）：检索模式 ──────────────────────────\n       默认**词法**。「混合」只是把语义候选**补进候选集**的一种可选模式，\n       它要用户显式选、并且配了 provider 才会真的跑 —— 「零模型调用 / 零网络出口」\n       这条对外承诺只在默认模式成立（细则见 v0.23 方案 §2 的文案纪律）。 */\n    const RETRIEVAL_KEY = 'dsh-knit:retrieval'\n    /** v0.25：Git 变更关联的开关。**默认关** —— 不写这一项就是关。 */\n    const CHANGES_KEY = 'dsh-knit:changes'\n    /** 语义 provider 的**唯一写路由**；读走 `/api/recent` 的 `semantic.provider`。 */\n    const SEMANTIC_API = '/knit/api/semantic'\n\n    /** 列表类型：仅文档 / 仅代码 / 仅图片视频 / 全部混排。默认 doc，与旧版体验一致。 */\n    const KIND_DOC = 'doc'\n    /**\n     * v0.19：代码档。**它是同一份 Context Retrieval 结果的另一个切片，不是代码工具页。**\n     * 这一档里显示的仍然是「按当前任务排出来的代码候选」，不是仓库的代码文件树\n     * （需求 §24：任务「修改 Skill loader 使它支持新的 frontmatter」时，\n     * 应该看到 skill-loader.ts / frontmatter.ts，而不是 src/ 下的全部 .ts）。\n     */\n    const KIND_CODE = 'code'\n    const KIND_MEDIA = 'media'\n\n    /**\n     * v0.19：分类层给的「生成产物」档（`.map` / `*.min.js` / `package-lock.json` …）。\n     *\n     * **它不出现在任何列表里**（`contextual:false`、`searchable:false`，宿主根本不会\n     * 把它放进候选），但它**可以预览** —— 用户主动点「Source map」时才走到这里。\n     * 「能不能进上下文」与「能不能看」是两件事（需求 §29：Context eligibility ≠\n     * File system visibility）。\n     */\n    const KIND_GENERATED = 'generated'\n\n    /* ── 产物 kind（宿主 `classification.js` 的取值）─────────────────────\n       ⚠️ **不要把它和上面的页签常量 `KIND_DOC` 混起来**：`KIND_DOC` 是**页签值**\n       （`'doc'`，只活在 URL 参数与 localStorage 里），而宿主下发的 `doc.kind` 是\n       **分类层的产物类型**（Markdown 是 `'md'`）。两者字面量不同、语义也不同，\n       写成 `doc.kind === KIND_DOC` 会恒为假 —— 那正是「代码区永远空白」这类\n       看起来像没数据、其实是比较写错的问题。 */\n    const ARTIFACT_DOC = 'md'\n    const ARTIFACT_CODE = 'code'\n\n    /** 预览面板高度的上下限：任何一端都不把对方挤没。 */\n    const MIN_RATIO = 0.2\n    const MAX_RATIO = 0.8\n    const DEFAULT_RATIO = 0.46\n\n    /* ── 曾经在这里的一组常量：右栏的宽度与形态 ──────────────\n       `PACK_W_DEFAULT`(310) / `PACK_W_MIN`(260) / `PACK_W_MAX`(420) /\n       `PACK_SNAP_PX`(28) / `PACK_DRAG_SLOP`(4)\n       **2026-09-29 整组删除**：它们只服务于「拖宽那个面板 / 把它拖出去浮动 /\n       拖到右缘吸附回来」这一套动作，而**右侧那个面板本身没有了**。\n       用户当天的结论：Context Pack 是**数据层**概念（Primary / Supporting /\n       Related 的结构化结果），**不是一个必须单独显示出来的 UI 卡片** ——\n      同一个结构直接落进文档列表的分组里，不再另开一栏解释一遍。\n       ⚠️ 留着一套只服务于已删 UI 的常量，下一个人只会以为它还在生效。 */\n\n    /** 「全部」视图里文档区的固定上限。 */\n    /* v0.23（方案 A）：「全部」档的**两个类型上限**已整体删除 ——\n       「全部」不再是「文档前 4 + 代码前 4 + 媒体」，而是**整份包的原样**\n       （三层混排文档 + 代码，媒体在三层之后一个不截断的网格）。 */\n    /** 「全部」视图里代码区的固定上限（与文档区同量级 —— 代码不该在这一档里压过文档）。 */\n    /**\n     * 一屏基准：两行 × 4 列的观感（只在「媒体」这一档决定一屏铺几行时用）。\n     * **它不决定列数** —— 列数交给 CSS 的 `auto-fill`，见 mediaLayoutFor。\n     */\n    const MEDIA_MAX_ITEMS = 8\n    /**\n     * 媒体格子的基准边长（CSS `minmax` 的下限）。\n     *\n     * **它与条目数完全无关** —— 这是 2026-09-20 第二版修正的核心。\n     * 第一版仍然按「条目数」反推格宽：条目 ≤8 个想要 4 列满宽、超过就缩到 64px 硬塞两行。\n     * 结果**列数被条目数锁死**：实测面板从 400px 拉到 1200px，列数一直卡在 **5 列**，\n     * 只有格子从 64px 被吹到 224px。用户的原话：「要我拉到一定的宽度以后，它才从 4 个变成更多」\n     * 「它不是真的响应式」。\n     *\n     * 现在只钉一个数：**格子基准 104px**（实际渲染约 104–155px），\n     * 列数 = 浏览器按可用宽度连续数出来的（`repeat(auto-fill, minmax(104px, 1fr))`）——\n     * 拖宽约 120px 就多一列，与 AIGC 资产中心的图片网格同一套机制\n     * （它的窄屏档就是 `minmax(104px,1fr)`）。\n     */\n    const MEDIA_TRACK_PX = 104\n    /* ── 文档列表为什么是单列（历史，写给下一个人看）─────────────────\n     * 这一段**不修饰任何声明**，只记结论与代价 —— 因为原来修饰的那个常量\n     * （`DOC_GRID_MIN_COLS` 那一组）已经随多列一起删了。\n     *\n     * 文档列表**永远是单列**（2026-09-29 用户拍板，第四版也是最后一版）。\n     *\n     * 演进，每一版都是真机体验后被打回的：\n     *  - 第一版「把完整卡直接压窄」→ 632px 面板 4 列时标题只剩 **9 个字**\n     *    （真实标题中位数 18、最长 43）。**多列不等于可以砍数据**（第二版\n     *    「多列只留标题 + 时间」也被否掉）。\n     *  - 第三版保留全部字段、上限收到 2 列；用户原话：「大于三行体验上视觉跳动信息过载了」。\n     *  - **第四版（当前）**：用户看到真机上的 2 列后拍板 ——「文档列表最多一个就行，\n     *    现在一行两个有点太多了」。**上限改成 1 列，多列那套整体删除**\n     *    （`docLayoutFor` / `DOC_TRACK_PX` / `DOC_SUMMARY_MIN_PX` / `.knit-multicol.cols-N`\n     *    与 `.no-sum` 兜底全部不再存在）。\n     *\n     * 单列之后行内改成**元信息在上、标题独占一行**（用户同一条消息里给的方向：\n     * 「时间跟那个置顶的序号可以一行」）—— 见 `DocRow` 的组装顺序与 `.knit-row1`。\n     *\n     * ⚠️ **不要加回多列**。真要提升宽面板的信息利用率，该做的是让**单列更舒展**，\n     * 不是切栏 —— 这句从第三版起没变过。\n     */\n    /**\n     * 实际格宽低于这个值才让卡片文字让位给缩略图。\n     *\n     * ⚠️ **正常情况下这个分支永远不触发**：格子基准 104px + `1fr` 只会把格子**撑宽**，\n     * 所以任何面板宽度下实际格宽都 ≥ 100px，文件名放得下。\n     * 旧版（按条目数把格子压到 64px 那套）才会频繁让位；这里保留判据只是兜底。\n     */\n    const MEDIA_LABEL_MIN_PX = 96\n    const MEDIA_GAP_PX = 10\n    /** 网格左右内边距合计（.knit-media-grid 的 padding:0 12px / 8px 12px 16px）。 */\n    const MEDIA_GRID_PAD_X = 24\n    /** `.knit-list` 自己的左右内边距（padding:8px）—— 量到的是它，算格子要先扣掉。 */\n    const LIST_PAD_X = 16\n    /** 量不到宽度时的兜底：默认右侧栏的几何（旧实现里的默认值，别改）。 */\n    const MEDIA_FALLBACK_WIDTH = 632\n\n    /**\n     * 算媒体网格当前能排几列、单格实际多宽。\n     *\n     * 规则（2026-09-20 第三次修正后的口径）：\n     *\n     * 1. **格子基准固定 104px，与条目数无关** —— 面板拖宽是**多出一列**，不是把格子吹大。\n     * 2. **列数连续增长** —— 宽约 120px 就多一列；不再像第一版那样卡在 5 列不动。\n     * 3. **纵向有多少行就铺多少行** —— 网格**不再设 maxHeight**。\n     *\n     * ⚠️ **第 3 条是 2026-09-20 第三次修正**：前两版都把高度封在「两行」，\n     * 让网格自己内部滚动。真机上第三行只能露出一点点，用户的原话是\n     * 「本来有三行，结果第三行只显示了一点点，应该纵向也完整显示」——\n     * 封顶高度是按「两行」算死的，跟面板实际有多高无关，必然截断。\n     * 现在整块交给 `.knit-list` 的滚动，与 AIGC 资产中心的做法一致。\n     *\n     * ⚠️ **这里的列数算术必须与 CSS 的 `auto-fill` 逐字同源**：CSS 那行是\n     * `repeat(auto-fill, minmax(104px, 1fr))`，所以列数是\n     * `floor((可用宽 + gap) / (104 + gap))`，**不是** `floor(可用宽 / 104)`；\n     * 少算 gap 会让 JS 与真机差一列（第一版实测踩过）。\n     *\n     * @param {number} width - 网格可用宽度（px，不含左右内边距）\n     * @returns {{min:number, columns:number, cell:number, scaled:boolean}}\n     *   格子基准宽（= CSS 的 minmax 下限）、当前宽度下能排几列、单格实际宽度、\n     *   是否让卡片文字让位\n     */\n    /* ── v0.25：媒体档「悬停看大图」────────────────────────────────────────\n       用户要的是「鼠标停在图片上，弹一个大图」。\n\n       三条取舍：\n       ① **800×800 是上限，不是尺寸** —— 面板本身只有几百像素宽，硬占 800 会把对话区盖住。\n          所以盒子按「卡片左边还剩多少」与视口算，最后再夹到 800。\n       ② **只做图片**（视频要解码 + 起播放器，噪声与代价都不是一个量级）。\n       ③ **延迟出现**（`HOVER_SHOT_DELAY_MS`）：鼠标扫过网格时不许一路闪；\n          离开即收。`pointer-events:none` —— 它只是「看一眼」，不许挡点击。\n    */\n\n    /**\n     * 悬停浮窗的边长上限。\n     *\n     * ⚠️ 2026-10-21 从 800 改成 420：用户在真机上看了之后说「现在浮窗太大了」，\n     * 并在截图上用红框标出他想要的大小 —— 约等于原来的**一半**。\n     * 这是**一个人眼定的大小**，不是算出来的；要再调就只改这一个数。\n     */\n    const HOVER_SHOT_MAX = 420\n    /* ── v0.25：媒体档「双击全屏」（2026-10-22，参照用户给的 Codex 截图）────────\n       用户要的三件事：① 双击图片进全屏；② 点图片以外关闭；③ 左侧一列「近 10 张」缩略图。\n       另加两件（不然光看图就断手）：图片以外是**毛玻璃**且随主题变（他第 4 点要的），\n       以及 `←` `→` 在带子里前后翻。\n       刻意**没做**（他没要，也不该顺手塞）：缩放百分比、下载、用其他应用打开。\n    */\n\n    /**\n     * 把查看器挂到哪：**能 portal 就一定 portal**（否则 `fixed` 会被侧边栏的 transform 困住）。\n     *\n     * 单独抽成一个函数是为了「这件事有没有做」能被源码守卫直接看见 ——\n     * 测试替身没有 `document`，这条路径只能在真机上走，所以形状守卫是它唯一的护栏。\n     *\n     * @param {object} node - 要挂的 React 元素\n     * @param {{doc?:object, dom?:object}} [env] - 可注入的 document / ReactDOM（默认取模块里的）\n     * @returns {object} portal 结果，或原节点（降级）\n     */\n    function mountLightbox(node, env = {}) {\n      const dom = env.dom === undefined ? (typeof document === 'undefined' ? null : document) : env.dom\n      const renderer = env.renderer === undefined ? ReactDOM : env.renderer\n      try {\n        if (node && dom && dom.body && renderer && typeof renderer.createPortal === 'function') {\n          return renderer.createPortal(node, dom.body)\n        }\n      } catch { /* portal 失败就就地渲染，不许白屏 */ }\n      return node\n    }\n\n    /** 全屏查看器左侧缩略图带显示几张。 */\n    const LIGHTBOX_RAIL = 10\n    /** 当前这张在带子里前面留几张（偏「刚看过的」，不是偏「后面的」）。 */\n    const LIGHTBOX_RAIL_LEAD = 4\n\n    /**\n     * 全屏查看器的左侧缩略图带：取**当前这张附近**的 N 张。\n     *\n     * 为什么不是「最新的 N 张」：双击第 30 张时，「最新 10 张」里根本没有它 ——\n     * 带子里看不到当前这张，前后翻也断在画面外。所以取一个以当前为中心的窗口，两头夹紧。\n     * **纯函数**：只吃数组与下标，能真断言。\n     *\n     * @param {object[]} docs - 当前媒体列表（已排好序）\n     * @param {number} index - 当前这张的下标\n     * @param {{size?:number, lead?:number}} [opts] - 带子长度与前置张数\n     * @returns {{start:number, items:object[]}} 起点与带子内容\n     */\n    function lightboxRail(docs, index, opts = {}) {\n      const list = Array.isArray(docs) ? docs : []\n      const size = Number.isFinite(opts.size) ? Math.max(1, Math.round(opts.size)) : LIGHTBOX_RAIL\n      const lead = Number.isFinite(opts.lead) ? Math.max(0, Math.round(opts.lead)) : LIGHTBOX_RAIL_LEAD\n      if (!list.length) return { start: 0, items: [] }\n      const at = Number.isFinite(index) ? Math.min(Math.max(0, Math.round(index)), list.length - 1) : 0\n      const start = Math.min(Math.max(0, at - lead), Math.max(0, list.length - size))\n      return { start, items: list.slice(start, start + size) }\n    }\n\n    /** 浮窗与卡片之间的间距。 */\n    const HOVER_SHOT_GAP = 12\n    /** 浮窗与视口边缘的最小留白。 */\n    const HOVER_SHOT_MARGIN = 12\n    /** 停多久才出现 —— 短了会在鼠标扫过时一路闪，长了会显得没反应。 */\n    const HOVER_SHOT_DELAY_MS = 350\n\n    /**\n     * 算悬停浮窗的盒子。**纯函数**：只吃两个矩形，不做任何 DOM 读。\n     *\n     * 规则：默认摆在卡片**左侧**（面板在右边，浮窗往对话区那边让，不压住网格）；\n     * 左边放不下就翻到右侧；垂直以卡片中线居中并夹进视口；盒子边长**最后**夹到 800。\n     *\n     * @param {{left:number,top:number,width:number,height:number}|null} card - 卡片矩形\n     * @param {{width:number,height:number}} view - 视口尺寸\n     * @param {{max?:number,gap?:number,margin?:number}} [opts] - 可注入的常数（测试用）\n     * @returns {{left:number,top:number,width:number,height:number,side:'left'|'right'}} 盒子\n     */\n    function hoverShotBox(card, view, opts = {}) {\n      const max = Number.isFinite(opts.max) ? opts.max : HOVER_SHOT_MAX\n      const gap = Number.isFinite(opts.gap) ? opts.gap : HOVER_SHOT_GAP\n      const margin = Number.isFinite(opts.margin) ? opts.margin : HOVER_SHOT_MARGIN\n      const viewW = view && Number.isFinite(view.width) ? view.width : 1024\n      const viewH = view && Number.isFinite(view.height) ? view.height : 768\n      // 拿不到卡片矩形（测试替身没有 DOM / 事件不带 currentTarget）⇒ 视口里居中，仍然守 800 上限\n      if (!card || !Number.isFinite(card.left) || !Number.isFinite(card.top)) {\n        const size = Math.min(max, viewW - margin * 2, viewH - margin * 2)\n        return {\n          left: Math.max(margin, Math.round((viewW - size) / 2)),\n          top: Math.max(margin, Math.round((viewH - size) / 2)),\n          width: size,\n          height: size,\n          side: 'right',\n        }\n      }\n      const roomLeft = card.left - gap - margin\n      const roomRight = viewW - (card.left + card.width) - gap - margin\n      const side = roomLeft >= roomRight ? 'left' : 'right'\n      const room = Math.max(0, side === 'left' ? roomLeft : roomRight)\n      const width = Math.max(1, Math.min(max, room, viewW - margin * 2))\n      const height = Math.max(1, Math.min(max, viewH - margin * 2, width * 1.6))\n      const rawLeft = side === 'left' ? card.left - gap - width : card.left + card.width + gap\n      const left = Math.min(Math.max(margin, Math.round(rawLeft)), Math.max(margin, viewW - margin - width))\n      const centerY = card.top + card.height / 2 - height / 2\n      const top = Math.min(Math.max(margin, Math.round(centerY)), Math.max(margin, viewH - margin - height))\n      return { left, top, width, height, side }\n    }\n\n    /* ── v0.25：媒体收藏 ───────────────────────────────────────────────────\n       只活在 localStorage（`readPref / writePref` 那一族：这是**语义偏好**，不是界面几何）。\n       **不改宿主、不加接口** ⇒ 只需要硬刷新，不用重启 DSH。\n\n       顺序规则只有一条：**稳定分区** —— 收藏的按原有顺序排到前面，其余按原有顺序跟在后面。\n       刻意**不做第二套排序**（不按收藏时间排、不按文件名排）：用户要的是「收藏的放最前面」，\n       而收藏之间谁在前仍由当前的「相关 / 最新」决定 —— 这样它不会变成第三种排序口径。\n\n       ⚠️ 与既有的「固定 / 排除」（`control.*`，宿主存储 `knit_control`）**不是同一件事**：\n       那一套只服务三层 Context Pack，媒体不参与，媒体卡片上也没有那个入口。\n    */\n\n    /** 落盘的键。值形如 `{ \"<root>\": [\"a.png\", \"b.mp4\"] }`。 */\n    const FAV_KEY = 'dsh-knit:favorites'\n    /** 最多记几个工作区（换项目时旧的不会无限长）。 */\n    const FAV_MAX_ROOTS = 5\n    /** 每个工作区最多记几条（超了按写入顺序截断，不做 LRU）。 */\n    const FAV_MAX_RELS = 200\n\n    /**\n     * 把落盘的值解析成 `{ [root]: string[] }`。\n     *\n     * 畸形输入一律回空表，**不许抛** —— localStorage 里的东西可能是上一版、手改过的、\n     * 或者干脆是别的插件写坏的；这里坏了不能让整个面板白掉。\n     *\n     * @param {string|null} raw - localStorage 里的原始字符串\n     * @returns {Object<string, string[]>} 归一化后的表\n     */\n    function parseFavorites(raw) {\n      if (typeof raw !== 'string' || !raw) return {}\n      let data = null\n      try { data = JSON.parse(raw) } catch { return {} }\n      if (!data || typeof data !== 'object' || Array.isArray(data)) return {}\n      const out = {}\n      for (const root of Object.keys(data)) {\n        const list = data[root]\n        if (!Array.isArray(list)) continue\n        const rels = []\n        for (const rel of list) {\n          if (typeof rel === 'string' && rel && rels.indexOf(rel) < 0) rels.push(rel)\n          if (rels.length >= FAV_MAX_RELS) break\n        }\n        if (rels.length) out[root] = rels\n      }\n      return out\n    }\n\n    /**\n     * 某个工作区下的收藏。\n     * @param {Object<string, string[]>} table - `parseFavorites()` 的产物\n     * @param {string} root - 工作区根（未知时回空数组）\n     * @returns {string[]} 副本\n     */\n    function favoriteRelsFor(table, root) {\n      const key = typeof root === 'string' ? root : ''\n      if (!key || !table || !Array.isArray(table[key])) return []\n      return table[key].slice()\n    }\n\n    /**\n     * 加 / 取消一条收藏，返回**新数组**（不改入参）。\n     * 新加的排到最前 —— 同一次会话里立即可见，不用等重新排序。\n     *\n     * @param {string[]} rels - 当前收藏\n     * @param {string} rel - 目标\n     * @returns {string[]} 新数组\n     */\n    function toggleFavoriteList(rels, rel) {\n      const list = Array.isArray(rels) ? rels.slice() : []\n      if (typeof rel !== 'string' || !rel) return list\n      const at = list.indexOf(rel)\n      if (at >= 0) { list.splice(at, 1); return list }\n      list.unshift(rel)\n      return list.slice(0, FAV_MAX_RELS)\n    }\n\n    /**\n     * 收藏的排到最前（**稳定**：两组内部都保持入参顺序）。\n     * 没有收藏时**原样返回同一个数组**（同一引用，省一次无意义的重渲染）。\n     *\n     * @param {object[]} docs - 当前可见条目\n     * @param {Set<string>|string[]} favorites - 收藏的 rel\n     * @returns {object[]} 排好序的数组（或原数组）\n     */\n    function orderFavorites(docs, favorites) {\n      const list = Array.isArray(docs) ? docs : []\n      const has = (rel) => (favorites instanceof Set\n        ? favorites.has(rel)\n        : (Array.isArray(favorites) && favorites.indexOf(rel) >= 0))\n      if (!list.length) return list\n      const first = []\n      const rest = []\n      for (const doc of list) {\n        if (doc && has(doc.rel)) first.push(doc)\n        else rest.push(doc)\n      }\n      return first.length ? first.concat(rest) : list\n    }\n\n    function mediaLayoutFor(width) {\n      const w = Number(width)\n      const usable = Number.isFinite(w) && w > 0 ? w : MEDIA_FALLBACK_WIDTH\n      /** cols 列时每格实际能有多宽（含 gap 的同一套算术）。 */\n      const cellFor = (cols) => Math.floor((usable - (cols - 1) * MEDIA_GAP_PX) / cols)\n      // 与 CSS 的 auto-fill 同一套判定：minmax(104px, …) 下能排几条。\n      const columns = Math.max(1,\n        Math.floor((usable + MEDIA_GAP_PX) / (MEDIA_TRACK_PX + MEDIA_GAP_PX)))\n      const cell = cellFor(columns)\n      // 让位判据看的是**实际格宽**，不是基准宽：窄面板只出 2 列时格子反而宽到 135px，\n      // 那时文件名放得下，不该跟着一起让位。\n      return {\n        min: MEDIA_TRACK_PX,\n        columns,\n        cell,\n        scaled: cell < MEDIA_LABEL_MIN_PX,\n      }\n    }\n\n    /* ── 样式：跟随 DSH 主题令牌，深浅色自适应 ───────────────── */\n    const STYLE_ID = 'dsh-knit-style'\n    const CSS = `\n.knit-root{\n  /* 交互强调色统一走 DSH 品牌令牌：浅色 #4176e6 / 暗色 #5686fe，随主题切换。\n     这里曾经硬编码过一套紫与另一套蓝，两套都不跟主题，深色下尤其突兀。\n     填充改用 DSH 选中态的半透明令牌，不自己混色 —— color-mix 在旧内核上\n     会让整条声明失效（invalid at computed-value time），不是渐进增强。 */\n  --knit-accent:var(--dsw-alias-brand-primary-new-colorprimary-new-color,#4176e6);\n  /* 悬停 / 选中 / 命中段的灰底：**一律从 DSH 官方那两个交互令牌推**，不自己发明色。\n     官方值在 dsh-client-ui-theme/lib/client.js 里，浅色在前、暗色在后：\n       --dsw-alias-interactive-bg-hover   浅 #2631480f = 5.88%   暗 #ffffff14 = 7.84%\n       --dsw-alias-interactive-bg-active  浅 #2631481a = 10.20%  暗 #ffffff24 = 14.12%\n     Knit 的行比 DSH 的控件更小更密，所以取官方透明度的**一个固定比例**，\n     而不是把官方值原样搬过来（起因：用户觉得 DSH 默认那档「太灰了」，对比度被吃掉）。\n     浅色比例：悬停 ×0.41、选中 ×0.60、命中段 ×0.90；**暗色是浅色这组再 ×0.9**\n     （2026-10-07 用户：「暗色下最高那一档白得犯晕……再降一下，降 10%」）。\n     命中段是三档里最高的一档，必须比「行选中」再深一点，否则它在被选中 / 悬停的行里会消失。 */\n  --knit-hover-bg:rgba(38,49,72,.024);   /* 官方 5.88% × 0.41 */\n  --knit-active-bg:rgba(38,49,72,.061);  /* 官方 10.20% × 0.60 */\n  /* 「命中段」那一格要一个**灰底**而不是白描边（2026-10-07 用户裁决，原话是\n     「叫它寻一个背景就行了，寻灰背景就行了，不需要在背景填充外面再加一个白色的描边」）。 */\n  --knit-chip-bg:rgba(38,49,72,.092);    /* 官方 10.20% × 0.90 */\n\n  display:flex;flex-direction:column;height:100%;min-height:0;\n  color:var(--dsw-alias-label-primary,#e8eaed);font-size:13px}\nbody[data-ds-dark-theme] .knit-root{\n  /* 2026-10-07 用户：暗色下列表里最高那一档「白得犯晕」—— 命中段的底原本是**纯白 13%**，\n     确实是我们自己拍的数（官方 active 只有 14.12%）。现在三档一律「官方值 × 浅色比例 × 0.9」：\n       悬停 7.84% × 0.41 × 0.9 ≈ .028（原 .031）\n       选中 14.12% × 0.60 × 0.9 ≈ .076（原 .085）\n       命中 14.12% × 0.90 × 0.9 ≈ .114（原 .13 —— 降幅最多，因为那个数本来就是自己拍的）\n     α 只保留三位小数，所以是「≈」；三档相对深浅的关系没变。 */\n  --knit-hover-bg:rgba(255,255,255,.028);\n  --knit-active-bg:rgba(255,255,255,.076);\n  --knit-chip-bg:rgba(255,255,255,.114);\n}\n.knit-head{display:flex;align-items:center;gap:8px;padding:10px 12px 8px;flex:none}\n.knit-head .knit-root-path{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;\n  white-space:nowrap;font-size:11px;color:var(--dsw-alias-label-caption,#80868b);\n  background:transparent;border:none;padding:0;text-align:left;font-family:inherit;\n  cursor:pointer}\n.knit-head .knit-root-path:hover{color:var(--dsw-alias-label-primary,#e8eaed);\n  text-decoration:underline}\n.knit-head .knit-root-path:disabled{cursor:default;text-decoration:none}\n.knit-count{font-size:11px;color:var(--dsw-alias-label-caption,#80868b);flex:none}\n.knit-btn{flex:none;display:inline-flex;align-items:center;justify-content:center;\n  height:28px;padding:0 10px;border-radius:8px;cursor:pointer;\n  background:transparent;color:var(--dsw-alias-label-secondary,#9aa0a6);\n  border:.5px solid var(--dsw-alias-border-l4,rgba(255,255,255,.08));font-size:12px;\n  transition:background .16s ease,color .16s ease}\n.knit-btn:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03));\n  color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-btn.active{background:var(--knit-active-bg,rgba(255,255,255,.085));\n  color:var(--dsw-alias-label-primary,#e8eaed);border-color:var(--dsw-alias-border-l4,rgba(255,255,255,.22))}\n/* v0.19「低权重动作」：Source map。\n   它**不是**主要操作 —— .map 不参与检索，只是一个「顺手看一眼」的旁路。\n   所以去掉边框、压到 caption 色，让「复制 / 全屏 / 本地打开」保持主次分明。\n   ⚠️ 不要在这里加 accent 色（类型页签那条守卫也是这个道理）。\n   ⚠️ 这段注释在模板串里：**任何反引号都会截断样式表**（AGENTS.md 的老坑）。 */\n.knit-btn-quiet{border-color:transparent;color:var(--dsw-alias-label-caption,#80868b);font-size:11px;padding:0 8px}\n.knit-btn-quiet:hover{color:var(--dsw-alias-label-secondary,#9aa0a6)}\n/* 排序切换与搜索框：v0.18 UI 迭代（md §四~§六）把这两个控件**按输入控件的尺度重做** ——\n   圆角 10px / 字号 13px。原来那套 22px 迷你胶囊读起来像「标签」而不是控件，\n   与 14px 的页签、15px 的 Usage 标题差了两档，是「审美欠缺」最直观的一处。\n   ⚠️ 高度：md 写 36px，2026-10-06 用户看了真机后定成 **28px**（「太高了，不需要这么高」），\n      与左边的「使用情况 / 刷新」同高。\n   ⚠️ 描边色：用 **--dsw-alias-border-l3**，与 DSH 主区「对话」页签下面那条横线（官方\n      .wSkVaW_header 的 border-bottom: .5px solid rgba(0,0,0,.12) = 浅色下的 border-l3）\n      同一个 token —— 2026-10-06 用户要求「描边色值改成跟那条横一样」。不用更深的 l4：\n      l4（浅色 rgba(0,0,0,.161)）比官方分割线重一档，摆在页签下面像两个输入框框住了内容。\n    ⚠️ 描边粗细：**0.5px**（2026-10-06 用户第二轮要求「描边色值修改成 0.5px」）—— 官方那条\n       横本身就是 .5px，色值对上而粗细仍写 1px，高分屏上比它粗一倍。三处同粗：.knit-seg\n       外框、.knit-seg 内部竖线、.knit-filter。CSS 里统一写 0.5px（与官方 .wSkVaW_header 的 .5px 同值）。\n   ⚠️ 选中态只改**底色 + 字重 600**（不是 700），hover 只改底色 —— 不许 scale / translate /\n      box-shadow（md §五）。暗色下靠 --knit-active-bg 这个 token，不写死颜色。\n   ⚠️ 2026-10-09（v0.21.x 用户规格）/ 2026-10-12（v0.23.1 用户裁决）：这一行是\n      **两组 + 一个右对齐容器**，顺序就是控件顺序，别再挪 —— ① 排序「相关 / 最新」（灰底分段控件）\n      ② 一条浅灰竖线 ③ 类型「文档 / 代码 / 媒体」（下划线页签，**三档**）\n      ④ .knit-bar-right：检索模式小下拉（只在相关档出现）+ 搜索框（贴右、宽度自适应、唯一可伸缩项）。\n      那根竖线是**边界**，不是把六个选项连成一个整体：排序与类型是两个互不干扰的条件，\n      搜索只过滤当前范围、不重置它们（用户规格 §三.3）。 */\n.knit-bar{display:flex;align-items:center;gap:8px;padding:0 12px 8px;flex:none}\n/* v0.23（Phase A）：检索模式的两条行 —— 都只在**用户选了混合**时出现，默认词法时一个节点都不产生。\n   ① .knit-retnote = 混合没生效时的**事实行**（未配置 / 连不上 / 超时 / 返回不合法 / 没有可用查询文本 /\n      宿主版本较旧）。它是说明，不是错误提示，所以用次级文字色、不占卡片、不弹窗。\n   ② .knit-semcfg = 「选了混合 + provider 不可用」时**就地**展开的一行最小配置。\n      不是 Dashboard、不加滚动容器；三格控件都 flex:0/1 + min-width:0，窄面板先缩输入框。 */\n/* 检索模式那两组控件（工具栏第三组 / 配置区的 provider 类型）用**自己的类名**：\n   样式与 .knit-seg / .knit-seg-btn **逐字同值**（同一套 token、同一组数值、同一档 0.5px 描边），\n   只是它们是**另一个控件** —— 用同一个类名会让「工具栏里恰好两个排序按钮」那类老守卫\n   在查询 knit-seg-btn 时把检索模式的按钮也算进去。\n   ⚠️ 这段注释里不许出现反引号 —— 整个 CSS 在一个模板串里，一个反引号就会提前截断它。 */\n.knit-retseg{display:inline-flex;flex:none;border-radius:10px;overflow:hidden;\n  border:0.5px solid var(--dsw-alias-border-l3,rgba(255,255,255,.12))}\n.knit-retseg-btn{height:28px;padding:0 15px;cursor:pointer;font-size:13px;font-weight:400;\n  border:none;background:transparent;color:var(--dsw-alias-label-secondary,#9aa0a6);\n  transition:background .16s ease,color .16s ease}\n.knit-retseg-btn + .knit-retseg-btn{border-left:0.5px solid var(--dsw-alias-border-l3,rgba(255,255,255,.12))}\n.knit-retseg-btn:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03))}\n.knit-retseg-btn.active{background:var(--knit-active-bg,rgba(255,255,255,.085));\n  color:var(--dsw-alias-label-primary,#e8eaed);font-weight:600}\n.knit-retnote{flex:none;padding:0 12px 8px;font-size:11px;line-height:1.5;\n  color:var(--dsw-alias-label-secondary,#9aa0a6)}\n.knit-semcfg{display:flex;align-items:center;gap:8px;padding:0 12px 8px;flex:none;flex-wrap:wrap}\n.knit-semcfg-input{flex:1 1 140px;min-width:0;max-width:240px;height:28px;padding:0 12px;border-radius:10px;\n  font-size:13px;background:transparent;color:var(--dsw-alias-label-primary,#e8eaed);\n  border:0.5px solid var(--dsw-alias-border-l3,rgba(255,255,255,.12))}\n.knit-semcfg-note{flex:1 1 100%;font-size:11px;line-height:1.5;color:var(--dsw-alias-label-secondary,#9aa0a6)}\n/* 排序组与类型组之间**不再有竖线**（2026-10-12 用户裁决：「最新跟文档之间那条竖线可以去掉」）——\n   那根线的节点、类名与 CSS 规则**整体删除**，两组现在只靠 .knit-bar 的 gap 分隔。\n   留档：从前那根线取 .knit-seg 外框 / .knit-filter 描边同一个 border-l3（三处一样淡）、\n   粗细 1px（0.5px 在高分屏上看不见）、纯装饰 aria-hidden —— 这些理由随它一起作废。 */\n.knit-seg{display:inline-flex;flex:none;border-radius:10px;overflow:hidden;\n  border:0.5px solid var(--dsw-alias-border-l3,rgba(255,255,255,.12))}\n.knit-seg-btn{height:28px;padding:0 15px;cursor:pointer;font-size:13px;font-weight:400;\n  border:none;background:transparent;color:var(--dsw-alias-label-secondary,#9aa0a6);\n  transition:background .16s ease,color .16s ease}\n.knit-seg-btn + .knit-seg-btn{border-left:0.5px solid var(--dsw-alias-border-l3,rgba(255,255,255,.12))}\n.knit-seg-btn:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03))}\n.knit-seg-btn.active{background:var(--knit-active-bg,rgba(255,255,255,.085));\n  color:var(--dsw-alias-label-primary,#e8eaed);font-weight:600}\n/* 搜索框在工具栏**尾部**（用户规格 §二.3：搜索是对当前列表的进一步过滤，放最右符合\n   工具栏惯例）。flex-basis 180px + grow ⇒ 常规面板里就是 180–240px 并贴住右边；\n   max-width 240px 封顶之后剩下的空间交给 margin-left:auto（否则它会一路长到面板边缘）。\n   ⚠️ min-width:0 = 面板窄了**先缩搜索框**；前面两组都 flex:none，永远不被它挤。\n   v0.23（2026-10-11 用户裁决）：描边从 input 挪到**外层容器** —— 因为检索模式那个小下拉\n   就贴在容器右端（中间一条细左线），两者共用一圈描边才像一个整体控件。\n   焦点态挪到 :focus-within（输入框与下拉谁拿到焦点，外框都亮）—— 行为与原来一致。 */\n/* v0.23.1：右侧两个控件的**右对齐容器** —— 检索模式在搜索框左边。\n   margin-left:auto 从搜索框移交到这里；容器自身可缩（min-width:0），\n   里面**只有搜索框**是 flex:1 1 的可伸缩项 ⇒ 窄屏先缩搜索框。\n   ⚠️ 这段注释里不许出现反引号 —— 整个 CSS 在一个模板串里。 */\n.knit-bar-right{display:flex;align-items:center;gap:8px;margin-left:auto;min-width:0;justify-content:flex-end}\n.knit-searchwrap{display:flex;align-items:center;flex:1 1 180px;min-width:0;max-width:240px;\n  border:0.5px solid var(--dsw-alias-border-l3,rgba(255,255,255,.12));border-radius:10px;\n  transition:border-color .16s ease}\n.knit-searchwrap:focus-within{border-color:var(--knit-accent)}\n.knit-filter{flex:1 1 auto;min-width:0;height:28px;padding:0 12px;border:none;border-radius:10px;font-size:13px;\n  background:transparent;color:var(--dsw-alias-label-primary,#e8eaed);outline:none}\n/* v0.24（2026-10-12 用户裁决 + Demo 参考）：检索方式做成状态行里**可点的状态格**。\n   外观（2026-10-12 第三次裁决，用户：「UI 视觉参考命中段那种来修改」）：\n   **逐条对齐 .knit-hit（命中段）那套** —— 这是同一份视觉语言的复用，不是新造一个控件：\n   · 底 = --knit-chip-bg（三档灰底里最深那档，命中段同源；比行选中那档深一点）；\n   · 圆角 6px、内边距 1px 6px、描边一根都没有（与命中段逐字同值）；\n   · 字色 = 次级灰，hover / 键盘焦点 → 主文本色 + 下划线（命中段同款提示）；\n   · **字号 / 行高 / 字重与命中段逐字同值**（font:inherit + font-size:11px + line-height:15px、\n     不设 font-weight ⇒ 跟随所在行）：2026-10-13 用户裁决「字号与背景胶囊修改成命中段一样」。\n     ⚠️ 这一格因此比它所在的状态行（10.5px）**大 0.5px** —— 那是有意的：它是这一行里唯一的可点控件，\n     与命中段同一档，才让人一眼认出「这两处是同一类东西」。 */\n.knit-pipe-method-wrap{position:relative;flex:none}\n.knit-pipe-method{display:inline-flex;align-items:center;flex:none;white-space:nowrap;cursor:pointer;\n  padding:1px 6px;border:0;outline:none;border-radius:6px;\n  background:var(--knit-chip-bg,rgba(255,255,255,.12));\n  font:inherit;font-size:11px;line-height:15px;\n  color:var(--dsw-alias-label-secondary,#61666b)}\n/* 悬停只提亮颜色；**下划线给包文字的那一层**，不给按钮本身 ——\n   父级的 text-decoration 会传播到全部子节点、子级又无法取消，\n   所以写在按钮上会让箭头 › 也一起被划上（2026-10-13 用户裁决）。 */\n.knit-pipe-method:hover,.knit-pipe-method:focus-visible{color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-pipe-method:hover .knit-pipe-method-label,\n.knit-pipe-method:focus-visible .knit-pipe-method-label{text-decoration:underline}\n.knit-pipe-method[aria-expanded=\"true\"]{color:var(--dsw-alias-label-primary,#e8eaed)}\n/* v0.25：Git 变更关联那一格。**与检索方式复用同一份视觉语言**（同 --knit-chip-bg、同圆角 6px、\n   同内边距 1px 6px、同字号 11px / 行高 15px），但它是个**二态开关**：没有菜单、没有箭头。\n   开态只把字色提到主文本色（属性选择器 aria-pressed=true）—— **不换底色、不用品牌色**，\n   与检索方式「展开态」那条规则同一个手法：同一行里同类物，靠字重/字色分层，不靠颜色。\n   ⚠️ 尾随的 › 在检索方式那边才画；这一格没有箭头，所以下划线直接给文字层即可。 */\n.knit-pipe-changes{display:inline-flex;align-items:center;flex:none;white-space:nowrap;cursor:pointer;\n  padding:1px 6px;border:0;outline:none;border-radius:6px;\n  background:var(--knit-chip-bg,rgba(255,255,255,.12));\n  font:inherit;font-size:11px;line-height:15px;\n  color:var(--dsw-alias-label-secondary,#61666b);transition:color .14s ease}\n.knit-pipe-changes:hover,.knit-pipe-changes:focus-visible{color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-pipe-changes:hover .knit-pipe-changes-label,\n.knit-pipe-changes:focus-visible .knit-pipe-changes-label{text-decoration:underline}\n.knit-pipe-changes[aria-pressed=\"true\"]{color:var(--dsw-alias-label-primary,#e8eaed)}\n@media (prefers-reduced-motion:reduce){.knit-pipe-changes{transition:none}}\n/* 箭头：与「最近读取」行最右端那个 › 同一套视觉语言（同字形），基础态旋转 90° 变成「朝下」。\n   ⚠️ 展开态用 **横向翻转 scaleX(-1)**，不是对调角度、也不是 scaleY(-1)（2026-10-13 用户裁决：\n      「修改成横向翻转……默认箭头向下，交互展开箭头向上」）。\n      · 对调成 rotate(-90deg) ⇒ 箭头在 0.14s 里**原地转 180°**（像风车），读起来是「在转」；\n      · **scaleY(-1) 是空操作** —— › 这个字形本来就沿水平轴对称，上下镜像后一模一样，\n        矩阵算出来仍是朝下（曾经写错过一次，被用户当场抓到，现在有几何守卫盯着）；\n      · scaleX(-1) 才是「同一个字形左右翻个面」：先把 › 镜像成 ‹，再转 90° ⇒ 朝上。\n   ⇒ 关=朝下、开=朝上，过程是横向翻转。 */\n.knit-pipe-method-go{display:inline-block;margin-left:3px;font-size:12px;line-height:1;\n  transform:rotate(90deg);transition:transform .14s ease}\n.knit-pipe-method[aria-expanded=\"true\"] .knit-pipe-method-go{transform:rotate(90deg) scaleX(-1)}\n@media (prefers-reduced-motion:reduce){.knit-pipe-method-go{transition:none}}\n.knit-retmenu{position:absolute;left:0;top:22px;z-index:20;width:272px;padding:6px;text-align:left;\n  background:var(--dsw-alias-bg-base,#151517);border:0.5px solid var(--dsw-alias-border-l3,rgba(255,255,255,.12));\n  border-radius:10px;box-shadow:0 10px 26px rgba(0,0,0,.28)}\n/* 菜单里那两个可选项：**沿用命中段那套**（2026-10-12 用户裁决「对，就这样修改」）——\n   圆角 6px（命中段同值）、选中态底 = --knit-chip-bg（命中段那档）；\n   菜单**面板本身**仍是浮层（bg-base + l3 描边 + 阴影 + 10px 圆角）：浮层必须读起来像浮层，\n   把它也压成灰胶囊就没有层级了。 */\n.knit-retmenu-item{display:block;width:100%;text-align:left;cursor:pointer;padding:8px 9px;border-radius:6px;\n  border:none;background:transparent;color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-retmenu-item:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03))}\n.knit-retmenu-item.active{background:var(--knit-chip-bg,rgba(255,255,255,.12))}\n.knit-retmenu-item strong{display:block;font-size:12.5px;font-weight:600}\n.knit-retmenu-item span{display:block;margin-top:3px;font-size:11px;line-height:1.5;\n  color:var(--dsw-alias-label-secondary,#9aa0a6)}\n.knit-retmenu-note{margin-top:4px;padding:7px 9px 4px;font-size:11px;line-height:1.5;\n  border-top:0.5px solid var(--dsw-alias-border-l3,rgba(255,255,255,.12));\n  color:var(--dsw-alias-label-secondary,#9aa0a6)}\n.knit-retmenu-cfg{display:block;width:100%;text-align:left;cursor:pointer;padding:7px 9px;border:none;\n  border-radius:6px;background:transparent;color:var(--dsw-alias-label-primary,#e8eaed);font-size:12px}\n.knit-retmenu-cfg:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03))}\n.knit-filter::placeholder{color:var(--dsw-alias-label-caption,#80868b)}\n/* v0.15「使用情况」→ v0.18「Context Usage Lens」：**列表上方的一块轻量观察层**。\n   不是弹窗、不是新页面、不是 Dashboard、不画卡片、不画进度条、不用品牌色。\n   它占的是原来「相关性排序」那一行的位置 —— 2026-09-30 用户裁决那一行整个删掉\n   （排序方式由「相关 / 最新」那个切换按钮自己表达，再说一遍是重复），\n   于是它是类型页签下面、列表上面唯一的一块弱化信息，不是一块新面板。\n   ⚠️ 全宽横线一律不画：2026-09-29 用户要求**减少全宽分割线** ——\n   「页面上横线一多，读起来就像文件管理表格」。层级由空间与字号建立。\n   ⚠️ 它**自己不滚动**：滚动统一交给 .knit-list —— 窄侧栏里滚轮套滚轮很难用。\n   ⚠️ 这一条不许加 background / width / 品牌色（有守卫盯着，见 client.test.mjs）。 */\n.knit-usage{flex:none;padding:12px 12px 10px;font-size:12px;line-height:1.5;\n  color:var(--dsw-alias-label-caption,#80868b)}\n/* Lens 标题行：整行可点，展开 / 收起。**「使用情况」开关管统计开不开，\n   这一行管「统计开着但看不看细节」—— 两件事**（2026-10-05 规格 §25）。\n   v0.18 UI 迭代（2026-10-06，依 '02_方案与 Demo/dsh-knit V0.18 UI 重构开发提示词.md'\n   §七 / §四十七 的尺度表）：标题 15px/600（它是这一块的**标题**，不是元信息）、\n   Epoch 12px 弱化靠右、**不做成 Badge**（不画底、不画边）。 */\n.knit-lens-head{display:flex;align-items:baseline;gap:8px;width:100%;appearance:none;\n  border:0;background:none;margin:0;padding:0;font:inherit;cursor:pointer;text-align:left;\n  color:var(--dsw-alias-label-secondary,#9aa0a6)}\n.knit-lens-head:hover{color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-lens-head:focus-visible{outline:1px solid var(--knit-accent);outline-offset:1px}\n.knit-lens-title{flex:none;font-size:15px;font-weight:600;line-height:20px;\n  color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-lens-epoch{flex:none;margin-left:auto;font-size:12px;font-weight:400;line-height:20px;\n  color:var(--dsw-alias-label-caption,#80868b)}\n/* 摘要行：三件事实，一行。放不下就省略号 —— 绝不换行把列表顶下去。\n   12px/18px、与标题 4~6px（md §九 / §十）。 */\n.knit-lens-sum{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\n  margin-top:5px;font-size:12px;line-height:18px}\n.knit-lens-sec{margin-top:13px}\n.knit-lens-name{margin-bottom:6px;font-size:12px;font-weight:500;\n  color:var(--dsw-alias-label-secondary,#9aa0a6)}\n/* 「当前上下文」这一句是**分节标题**（比层名与行标签高一档，md §十三：13px/500）；\n   距摘要行 12~14px 由 .knit-lens-sec 的 margin-top 给。 */\n.knit-lens-cap{margin-bottom:6px;font-size:13px;font-weight:500;\n  color:var(--dsw-alias-label-secondary,#9aa0a6)}\n/* 当前上下文 Coverage：三层各「层名 + 已读 ÷ 总数 + 状态点」。\n   v0.18 UI 迭代（md §十二~§十九）：三层用 '1fr 1.2fr 1.8fr' 的**网格**（Related 通常\n   最多），层名与 'n / m' 落在**同一行**（数值右对齐），状态点是**真的 9px 圆点** ——\n   不再是 '○ ●' 字符：字符圆点在不同字体 / 字号下大小不一，正是「不像设计稿」的那一处。\n   ⚠️ 不是三张 Card：默认不画底、不画边，只有 hover 时一层很淡的底（md §十三 / §五十一）。\n   ⚠️ 分母是这一层当前真实几篇：Primary 不存在时整列不显示（不画 0 / 0 的假层）。 */\n.knit-cov{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr) minmax(0,1.8fr);\n  column-gap:14px;align-items:start;margin:0 -8px}\n.knit-cov-col{display:grid;grid-template-columns:1fr auto;column-gap:8px;row-gap:7px;\n  align-items:center;appearance:none;border:0;margin:0;padding:6px 8px;\n  background:transparent;font:inherit;cursor:pointer;text-align:left;border-radius:10px;\n  color:var(--dsw-alias-label-caption,#80868b);transition:background .16s ease}\n.knit-cov-col:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03))}\n.knit-cov-col:focus-visible{outline:1px solid var(--knit-accent);outline-offset:1px}\n.knit-cov-name{grid-column:1;min-width:0;overflow:hidden;text-overflow:ellipsis;\n  white-space:nowrap;font-size:12px;font-weight:500;\n  color:var(--dsw-alias-label-secondary,#9aa0a6)}\n/* 状态点：**真 CSS 圆** —— 未读＝空心环（1px 中性边）、已读＝中性填充；'○→●' 只做\n   background / border-color 两笔 220ms 过渡，不弹跳、不闪烁。\n   ⚠️ 轮询不动数据就不动 className，于是补间不会被重播。\n   ⚠️ 只用中性 token：没有绿 / 红 / 黄 / 蓝 —— 读没读过不是「好 / 坏」（PRD §7.3）。\n   ⚠️ 与文档行里的 .knit-glyph-mark **同一对 token、同一个直径**：md §二十九 要求\n   生命周期那枚空心圆与这里的空心圆「视觉完全一致」。 */\n.knit-cov-dots{grid-column:1 / -1;display:flex;flex-wrap:wrap;gap:6px;row-gap:5px;\n  min-height:6px;align-items:center}\n/* ⚠️ 圆点直径 6px（2026-10-06 用户定：「9px 真圆请改成 6px」）。\n   Coverage 与文档行的 glyph 必须**同一个直径、同一对 token**（守卫会比对两处）。 */\n.knit-cov-dot{flex:none;display:block;width:6px;height:6px;border-radius:50%;\n  border:1px solid var(--dsw-alias-label-caption,#80868b);background:transparent;\n  transition:background .22s ease,border-color .22s ease}\n.knit-cov-dot.on{background:var(--dsw-alias-label-caption,#80868b);\n  border-color:var(--dsw-alias-label-caption,#80868b)}\n.knit-cov-num{grid-column:2;text-align:right;font-size:11px;font-weight:400;\n  font-variant-numeric:tabular-nums;color:var(--dsw-alias-label-caption,#80868b)}\n/* 最近读取：**可点的一行**（文件名 · 相对时间 ›）。整行可点、hover 只改底色。\n   v0.18 UI 迭代（md §二十一 / §二十二）：高 38px、左右 10px、圆角 8px、\n   文件 12px、时间 11px、箭头 16px。\n   ⚠️ 语义仍是「最近一次成功 read」：文案不许写成「当前正在阅读」。 */\n.knit-read-row{display:flex;align-items:center;gap:10px;width:100%;appearance:none;\n  border:0;background:none;margin:0;padding:0 10px;height:38px;border-radius:8px;font:inherit;\n  text-align:left;cursor:pointer;color:var(--dsw-alias-label-primary,#e8eaed);\n  transition:background .16s ease}\n.knit-read-row:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03))}\n.knit-read-row:focus-visible{outline:1px solid var(--knit-accent);outline-offset:1px}\n.knit-read-rel{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;\n  white-space:nowrap;font-size:12px}\n.knit-read-time{flex:none;font-size:11px;color:var(--dsw-alias-label-caption,#80868b)}\n.knit-read-go{flex:none;font-size:16px;line-height:1;\n  color:var(--dsw-alias-label-caption,#80868b)}\n.knit-lens-empty{opacity:.75}\n/* 包外读取：每一行都是**可点对象**（点开预览），但不许加入 Context ——\n   V0.18 不做 Context Control，这里是「看一眼」，不是「改上下文」。\n   v0.18 UI 迭代（md §三十四~§三十七）：展开后逐行\n   '01  docs/…  ×3  已读'（序号 + 路径 + 次数 + 状态），11px、行内不画线。 */\n.knit-out-row{display:flex;align-items:center;gap:9px;width:100%;appearance:none;\n  border:0;background:none;margin:0;padding:5px 9px 5px 17px;border-radius:8px;font:inherit;\n  text-align:left;cursor:pointer;color:var(--dsw-alias-label-caption,#80868b);\n  transition:background .16s ease}\n.knit-out-row:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03));\n  color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-out-row:focus-visible{outline:1px solid var(--knit-accent);outline-offset:1px}\n.knit-out-num{flex:none;width:18px;text-align:right;font-size:11px;\n  font-variant-numeric:tabular-nums;color:var(--dsw-alias-label-caption,#80868b);opacity:.75}\n.knit-out-rel{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;\n  white-space:nowrap;font-size:11px}\n.knit-out-count{flex:none;font-size:11px;font-variant-numeric:tabular-nums}\n/* 行内生命周期 glyph（v0.17 起）：**极小、中性、不抢标题**。点它 = 打开 / 选中这篇。\n   v0.18 UI 迭代（md §二十七~§二十九）：四态改成与 Coverage **同一套**圆点语言 ——\n   未读＝空心环、已读＝实心、读后已更新＝空心环 + 中心点、修改后已重新读取＝ ↻ 字符。\n   两者用同一对 token、同一个 9px 直径，所以「同一套状态语言」不靠自觉。\n   ⚠️ 类名不能叫 knit-life-*：byClass 是子串匹配，会和 .knit-life 撞。 */\n.knit-glyph{flex:none;display:inline-flex;align-items:center;justify-content:center;\n  appearance:none;border:0;background:none;margin:0;padding:0;width:14px;height:18px;\n  cursor:pointer;color:var(--dsw-alias-label-caption,#80868b)}\n.knit-glyph:hover{color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-glyph:focus-visible{outline:1px solid var(--knit-accent);outline-offset:1px}\n.knit-glyph-mark{flex:none;display:block;width:6px;height:6px;border-radius:50%;\n  border:1px solid var(--dsw-alias-label-caption,#80868b);background:transparent;\n  transition:background .22s ease,border-color .22s ease}\n.knit-glyph-mark[data-mark=\"read\"]{background:var(--dsw-alias-label-caption,#80868b)}\n.knit-glyph-mark[data-mark=\"updated\"]{position:relative}\n.knit-glyph-mark[data-mark=\"updated\"]::after{content:'';position:absolute;inset:1.5px;\n  border-radius:50%;background:var(--dsw-alias-label-caption,#80868b)}\n.knit-glyph-mark[data-mark=\"reread\"]{width:9px;height:9px;border:0;background:transparent;\n  font-size:9px;line-height:9px;text-align:center}\n/* Coverage 点某一层 → 那一层**短暂高亮**（空间定位，不画横线、不加箭头）。\n   1200ms 轻微背景（md §十七原写 500~700ms，2026-10-06 用户看真机后定成 1200ms），\n   不许闪红、不许位移。CSS transition 的时长必须与 FLASH_MS 一致，否则会出现「已经取消高亮\n   但背景还在慢慢褪」的错帧。 */\n.knit-tier{transition:background 1.2s ease}\n.knit-tier.flash{background:var(--knit-hover-bg,rgba(255,255,255,.03));border-radius:10px}\n\n/* v0.17 文档生命周期（Document Lifecycle）—— 三条新信息，都只是**事实**。\n   ⚠️ 状态是文字，不是徽章：不加底色、不加边框、不用红绿 —— 红绿会把「事实」读成\n   「好 / 坏」（PRD §7.3）。永远不抢标题（标题 14px）。\n   v0.18 UI 迭代：10.5px → **11px** —— md §四十七 的尺度表里最小一档就是 11px。\n   ⚠️ 折叠块沿用 .knit-usage 的弱化灰阶：它们是同一行事实的展开，不是新卡片。\n   ⚠️ 这一段**不含反引号**，整段可以直接放在 CSS 模板串里。 */\n.knit-life{flex:none;font-size:11px;line-height:1.4;white-space:nowrap;\n  color:var(--dsw-alias-label-caption,#80868b)}\n.knit-usage-more{margin-top:10px}\n/* 菜单式展开行（包外读取 / 上下文变化）：整行可点、高 38px、圆角 8px、hover 只改底色；\n   左边是标题，右边是「数量 / 最近一次 + ›」，展开后箭头换成 ⌃（md §三十四 / §三十八）。 */\n.knit-more-btn{display:flex;align-items:center;gap:10px;width:100%;\n  appearance:none;border:0;background:none;margin:0;padding:0 10px;height:38px;\n  border-radius:8px;font:inherit;font-size:12px;line-height:1;cursor:pointer;text-align:left;\n  color:var(--dsw-alias-label-secondary,#9aa0a6);transition:background .16s ease}\n.knit-more-btn:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03));\n  color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-more-btn:focus-visible{outline:1px solid var(--knit-accent);outline-offset:1px}\n.knit-more-label{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;\n  white-space:nowrap}\n.knit-more-meta{flex:none;font-size:11px;font-variant-numeric:tabular-nums;\n  color:var(--dsw-alias-label-caption,#80868b)}\n.knit-gap-row,.knit-delta-row{display:flex;gap:9px;align-items:baseline;\n  padding:3px 9px 3px 17px;font-size:11px;\n  color:var(--dsw-alias-label-caption,#80868b)}\n.knit-gap-rel,.knit-delta-rel{flex:1 1 auto;min-width:0;overflow:hidden;\n  text-overflow:ellipsis;white-space:nowrap}\n.knit-delta-head{margin-top:8px;padding:0 9px 0 17px;font-size:11px;font-weight:500;\n  color:var(--dsw-alias-label-secondary,#9aa0a6)}\n\n\n/* ── v0.14 右栏（Context Pack 面板）已整体删除（2026-09-29）────────\n   用户裁定：Context Pack 是**数据层**结构（Primary / Supporting / Related），\n   不是一个要单独显示的 UI 卡片。右栏与左栏的 Primary / Supporting / Related\n   信息重复，「当前任务 / 命中 N 篇 / 证据」的视觉价值也有限，还容易把 Knit\n   做成 AI Dashboard ⇒ 界面改成**单栏**，分组直接落在文档列表里。\n\n   随这一栏删掉的东西（**删干净，不留死代码**）：\n   .knit-context-layout / .knit-col-list / .knit-context-column（两列网格）、\n   @media (max-width:1000px) 的并栏规则、.knit-grip（拖宽把手）、\n   .knit-pack*（面板与头部）、.knit-evrow 一整套证据行、\n   .knit-solo / .knit-undocked / .knit-snap 三个状态类。\n   JS 那边对应的 clampPackW / clampFloatPos / nearRightEdge、拖拽与吸附、\n   contextPanel 也一起删了。\n   ⚠️ 留着一套永远渲染不出来的样式，下一个人只会以为它还在生效。\n\n   ⚠️ 这段注释里不能出现反引号（整个 CSS 是一个模板串）。 */\n\n.knit-tier{display:block}\n.knit-tier + .knit-tier{margin-top:16px}\n/* ⚠️ 组与组之间**不再画线**（2026-09-29）：以前是 margin-top:2px + 一条 border-top，\n   读起来像表格。现在只有 16px 空间 —— 分组靠间距与组名建立，不靠横线。 */\n.knit-tierline{display:flex;align-items:baseline;gap:6px;padding:0 12px 6px;\n  font-size:10px;line-height:1.3;color:var(--dsw-alias-label-tertiary,#81858c)}\n/* Design §14：层名走「大写 + 字距」这套页签式排版，中文 hint 退到 muted 那一档。\n   ⚠️ uppercase 对中文是空操作，所以中文形态仍然是「主要上下文」——\n   不为了对齐英文形态去改词典：界面语言该由 i18n 决定，不该由 CSS 决定。\n   Design §14 里那个「可选的 5~6px 灰点」**不做** —— Primary 已经有一颗黑点了，\n   再加一颗同形状的点会让「层标记」和「主上下文标记」看起来是一回事。 */\n.knit-tiername{font-weight:600;font-size:12px;letter-spacing:.01em;\n  text-transform:uppercase;color:var(--dsw-alias-label-secondary,#61666b)}\n.knit-tierhint{font-weight:400}\n/* 「为什么在这里」＋「命中段」：**同一条 metadata 行**（2026-10-07 用户裁决）。\n   两条都是「这一行为什么在这里」，分两行会让每一行都变高；用户的原话是\n   「这样就会减少文档列表的高度」。命中段在左（本版最该被看见的那一格），\n   中间一条 1px 中性竖线分隔 —— 不是虚线、不是分隔带、不加底色。\n   ⚠️ 仍然**独占一行**，不并到标题行右侧：那里的省略号会把它截成\n   「标题命中当前…」，恰好把要传达的东西吃掉（Design §11 的字段顺序不变）。\n   2026-10-08 用户规格：这一行的**右端**现在是操作组（固定 / 排除 / 来源词），\n   所以行本身是「左证据 + 右动作」的两段式 —— 左边 flex:1 可截断，右边 flex:none。\n   行高不变、也不因为动作出现或隐藏而跳动（隐藏用的是 visibility，位置一直留着）。 */\n.knit-subrow{display:flex;flex-wrap:nowrap;align-items:baseline;gap:8px;min-width:0;padding-top:2px}\n.knit-subrow-main{flex:1 1 auto;display:flex;flex-wrap:nowrap;align-items:baseline;gap:8px;min-width:0}\n.knit-subrow-sep{flex:none;align-self:stretch;width:1px;margin:2px 0;\n  background:var(--dsw-alias-border-l3,rgba(255,255,255,.12))}\n/* 11px 而不是 10px，因为它承担的是**信息**（可核验的理由），不是装饰标注。 */\n.knit-why{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\n  font-size:11px;line-height:17px;color:var(--dsw-alias-label-tertiary,#81858c)}\n/* v0.20 命中段（需求 §12）：metadata 行里**靠左**那一格，只有行号区间。\n   它是个真 button（可 Tab、可回车、可读屏），但**不像按钮**：没有图标、没有描边\n   （border:0 + outline:none，选中 / 聚焦都不画环）、没有品牌色 —— §26「只展示可验证信息」，\n   行号是事实，不是分数，也不是 AI 判断。\n   2026-10-07 用户裁决：**要一个灰底**（\"叫它寻一个背景就行了，寻灰背景就行了，不需要在\n   背景填充外面再加一个白色的描边\"）—— 底用 --knit-chip-bg（比行选中那档深一点，\n   免得它在被选中的行里消失），内边距 1px 6px。\n   2026-10-07 同一天第二轮：圆角 **6px**（原话「圆角能不能改成一个胶囊……只是说圆角再增加 2 倍」，\n   3px 那档「有点硬」；行高 15px + 上下各 1px ⇒ 盒子高 17px，6px 已接近半高，就是胶囊）。\n   **描边仍然一根都没有**。\n   键盘焦点靠与 hover 同款的下划线提示。 */\n.knit-hit{display:block;flex:none;text-align:left;margin:0;padding:1px 6px;border:0;outline:none;\n  border-radius:6px;background:var(--knit-chip-bg,rgba(255,255,255,.12));font:inherit;\n  font-size:11px;line-height:15px;cursor:pointer;color:var(--dsw-alias-label-secondary,#61666b)}\n.knit-hit:hover,.knit-hit:focus-visible{color:var(--dsw-alias-label-primary,#0f1115);text-decoration:underline}\n/* ── v0.21 来源词 / 行级证据 / 固定与排除（需求 §6、§8）────────────\n   这一层整体是**弱化层**：来源、动作、证据都排在标题与摘要之下，字号 10–11px、\n   都是 caption / tertiary 灰。两条纪律：\n   ① **来源不是强弱**：检索 / 关系 / 用户固定 三个词**共用一种灰**，靠字区分，\n      不做彩色徽标、不做分数（需求 §8：颜色只用来区分来源，不用来表达强弱）；\n   ② 证据列表是「点开才有」的第二层，默认一个节点都不渲染（默认视图一个字节都不变）。\n   2026-10-08 用户规格（v0.21.x 布局改造）：来源词从标题行搬进证据行右端的操作组，\n   成为那一组里的**第三个文字按钮**（固定 → 排除 → 来源词）—— 于是它不能再是\n   一枚有底色的胶囊（§3.4：默认根本不显示，出现时就是克制的文字操作）。\n   ⚠️ 它仍然是「这一条怎么进来的」这条**事实**：没有图标、没有描边、同一种灰；\n      有关系可展开时才是 button（多一个 hover / 焦点的下划线反馈），\n      没有证据可展开时就是一个 span：**不装成能点的样子**。 */\n.knit-prov{flex:none;margin:0;padding:0 5px;border:0;outline:none;background:transparent;\n  border-radius:5px;font:inherit;font-size:11px;line-height:15px;\n  color:var(--dsw-alias-label-caption,#80868b)}\nbutton.knit-prov{cursor:pointer}\nbutton.knit-prov:hover,button.knit-prov:focus-visible{background:var(--knit-hover-bg,rgba(255,255,255,.03));\n  color:var(--dsw-alias-label-primary,#0f1115)}\n/* 证据行右端的操作组：固定 → 排除 → 来源词。\n   **默认整组不显示** —— 悬停到这一行、键盘光标在这一行（.cursor 类）、这一行处于\n   选中态（.active 类）、或焦点进入这一行（:focus-within）才出现（2026-10-08 用户规格 §3.3）。\n   ⚠️ 用 visibility:hidden 而**不是** opacity:0：隐藏时必须同时退出焦点序与命中测试，\n      否则「看不见却 Tab 得到 / 点得到」就是骗人的（§3.3 第 4 条）。\n   ⚠️ 没有 opacity / visibility 的过渡动画（§3.3 第 6 条：不加悬停动画、发光、装饰）。\n   ⚠️ flex:none + visibility ⇒ 出现与隐藏都**不改变行高、不推挤左侧证据**。 */\n.knit-rowacts{flex:none;display:flex;align-items:center;gap:2px;visibility:hidden}\n.knit-doc:hover .knit-rowacts,.knit-doc.active .knit-rowacts,.knit-doc.cursor .knit-rowacts,\n.knit-doc:focus-within .knit-rowacts{visibility:visible}\n.knit-act{flex:none;margin:0;padding:0 5px;border:0;outline:none;background:transparent;\n  border-radius:5px;font:inherit;font-size:11px;line-height:15px;cursor:pointer;\n  color:var(--dsw-alias-label-caption,#80868b)}\n.knit-act:hover,.knit-act:focus-visible{background:var(--knit-hover-bg,rgba(255,255,255,.03));\n  color:var(--dsw-alias-label-primary,#0f1115)}\n/* 2026-10-09 用户反馈（真机体验过第一版之后）：① 「固定 / 排除 / 检索 这个字号有点太小了，\n   可以跟命中段一样大小」⇒ 10px → **11px / 15px**，与命中段（.knit-hit）同档；\n   ② 「悬停的时候那个背景可以再左右各加 4 个像素，热区有点小、有点点不到」⇒\n   padding 5px → **9px**，同时用 **-4px 的负外边距**把那 4px 从布局宽度里收回来：\n   于是**行宽与三个词之间的视觉间距一点没变**，只有悬停底色与可点区域向左右各长 4px。\n   ⚠️ 只作用于证据行右端这一组（恢复那个单独的 .knit-act 不动，它旁边没有兄弟会被挤）。 */\n.knit-rowacts .knit-act,.knit-rowacts .knit-prov{padding:0 9px;margin:0 -4px}\n/* 「为什么」在**有关系可看**时是一个按钮（点开就是那一行的证据），但看起来必须仍是\n   一行灰字：没有图标、没有描边、没有底色，只有 hover 时加下划线 —— 与 .knit-hit\n   同一套语言（那是事实，不是操作）。\n   ⚠️ 文本**一个字节都没变**（test/client.test.mjs 按 knit-why 取这一行的原文）。 */\nbutton.knit-why{margin:0;padding:0;border:0;outline:none;background:transparent;font:inherit;\n  font-size:11px;line-height:17px;text-align:left;cursor:pointer;\n  color:var(--dsw-alias-label-tertiary,#81858c)}\nbutton.knit-why:hover,button.knit-why:focus-visible{color:var(--dsw-alias-label-secondary,#61666b);\n  text-decoration:underline}\n/* 行级证据（需求 §6.2）：默认不渲染，点开才有。每条一行，四个字段都不省略：\n   类型 · 方向 · 谁 · 第几行。.knit-relline 用等宽体承接行号（对齐扫读）。 */\n.knit-rellist{margin-top:4px;padding:5px 0 0;display:flex;flex-direction:column;gap:2px;\n  border-top:.5px solid var(--dsw-alias-border-l3,rgba(255,255,255,.12))}\n.knit-relrow{display:flex;align-items:baseline;gap:6px;min-width:0;font-size:11px;line-height:16px;\n  color:var(--dsw-alias-label-tertiary,#81858c)}\n.knit-reltag{flex:none;font-size:10px;padding:0 4px;border-radius:4px;\n  background:var(--knit-active-bg,rgba(38,49,72,.061));color:var(--dsw-alias-label-caption,#80868b)}\n.knit-relwho{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.knit-relline{flex:none;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:10.5px}\n.knit-relopen{flex:none;margin:0;padding:0 4px;border:0;outline:none;background:transparent;\n  border-radius:4px;font:inherit;font-size:10px;line-height:15px;cursor:pointer;\n  color:var(--dsw-alias-label-caption,#80868b)}\n.knit-relopen:hover,.knit-relopen:focus-visible{color:var(--dsw-alias-label-primary,#0f1115);\n  text-decoration:underline}\n.knit-relmore{font-size:10px;line-height:16px;color:var(--dsw-alias-label-caption,#80868b)}\n/* 被用户排除的那一行：**单行弱化说明**，空的时候不出现、也不占位（需求 §6.3）。\n   它说的是「这一批少了什么」，所以用中性描边而不是警告色 —— 这不是错误，是用户的选择。 */\n.knit-excl{flex:none;display:flex;align-items:baseline;gap:6px;margin:0 12px 6px;padding:5px 8px;\n  border-radius:6px;font-size:11px;line-height:16px;\n  background:var(--knit-hover-bg,rgba(255,255,255,.03));color:var(--dsw-alias-label-caption,#80868b)}\n.knit-excl-what{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n/* 检索状态摘要（需求 §6.3；2026-10-09 用户规格重排）：**单行、三组、竖线分组** ——\n   收集 79 · 排除 0 · 候选 79  ｜  BM25 词法检索 · 关系 24 条 · 固定 0  ｜  入包 9。\n   三组就是阅读顺序：工作区候选 → 检索与调整 → 最终结果。\n   ⚠️ 箭头（↓ / →）和「检索 / 排序（BM25 词法）」「关系投影」「固定覆盖」这些内部说法\n      **已整体删除** —— 它们把一条**已经完成**的管线画成了流程图（用户原话：箭头「增加理解成本」）。\n   ⚠️ 它仍然只是一串计数：没有图标、没有胶囊、没有卡片、没有色块、没有装饰性边框，\n      只有灰字 + 中点 + 一根细竖线。\n   ⚠️ 中点与竖线都是**文本节点**（不是伪元素、不是边框）：它们跟同一行流排版，\n      基线天然对齐，窄面板换行时也不会留下一条贴边的孤线。\n   ⚠️ 这段是模板字符串：注释里**不许出现反引号**（AGENTS.md §6.1，踩过三回了）。 */\n.knit-pipe{flex:none;display:flex;align-items:baseline;flex-wrap:wrap;gap:4px;\n  margin:0 12px 8px;font-size:10.5px;line-height:15px;\n  color:var(--dsw-alias-label-caption,#80868b)}\n.knit-pipecell{flex:none;white-space:nowrap}\n.knit-pipecell.strong{color:var(--dsw-alias-label-secondary,#61666b);font-weight:500}\n.knit-pipedot,.knit-pipesep{flex:none;color:var(--dsw-alias-label-caption,#80868b)}\n.knit-pipesep{margin:0 3px}\n/* 滚动条**不要自己画**：DSH 主题里已有全局样式\n   （::-webkit-scrollbar 宽 8px ＋ --dsh-scrollbar-thumb，见 dsh-client-ui-theme）。\n   曾经在这里写死 6px 宽 ＋ rgba(255,255,255,.14) 的滑块 —— 白色 14% 在白底上完全隐形，\n   用户的原话是「没有一个右侧的滑动条」。删掉即继承主题默认（l1），与侧栏列表一致。\n   ⚠️ CSS 注释里不要出现反引号：这段是模板字符串，反引号会把它提前截断。 */\n.knit-list{flex:1 1 auto;min-height:0;overflow-y:auto;padding:8px;display:flex;flex-direction:column;gap:6px;outline:none}\n/* 文档列表**没有网格**：永远一个文档一行（2026-09-29 用户拍板，第四版也是最后一版）。\n   ⚠️ 这里曾经有 「.knit-multicol.cols-2」 那一档（JS 按可用宽度算列数、再加类），\n   连同 「docLayoutFor」 / 「DOC_TRACK_PX」 / 「DOC_SUMMARY_MIN_PX」 / 「.no-sum」 一起删了 ——\n   留着一套永远算不出 2 列的代码，下一个人只会以为它还在生效。\n   媒体网格不走这里（它有自己的 「.knit-media-grid」 + CSS auto-fill，不受影响）。 */\n.knit-list:focus-visible{box-shadow:inset 0 0 0 1px var(--knit-accent)}\n/* 列表行＝**两列的 grid**（2026-09-29 用户追加要求：「文档列表序号放在独立最左边，\n   其他数据放在右边」）。第一列＝序号那条竖直的轴（.knit-num），第二列＝其余全部数据\n   （.knit-body）。用 grid 而不是「有号才插一个元素」，是因为没有号的条目（时间序 /\n   筛选结果 /「其他相关文档」）也要和有的条目**左边缘对齐** —— 轨道一直在，\n   正文就永远不会因为少一个序号而左移。\n   2026-10-01 补：光对齐还不够 —— **混着**才刺眼（整屏没号时没人觉得缺东西）。所以\n   这一屏里有号时，没号的行在同一列渲染一个 .knit-gapmark（·）把格子顶住。 */\n/* 行的**静止态没有底色**（2026-09-29 用户反馈：「深色模式下，文档列表没有选中，鼠标没有悬停，\n   不需要有背景。或者是说，跟深色模式的最底下的背景一样」）。\n   ⚠️ 这里以前写的是 bg-layer-1 —— 浅色主题下它和面板底色都是 #fff（根本看不出来），\n   **暗色主题下它比 bg-base 亮一档**，于是每一行都像一张浮起来的小卡片，哪怕没选中、没悬停。\n   现在静止态直接 transparent，露出宿主侧边栏的底色（.knit-root / .knit-list 都不画底色）；\n   ⚠️ 右栏删除后这段注释里提到的 .knit-pack 已经不存在了（2026-09-29），\n   hover 与 .active 各有自己的令牌，\n   两者都**不该**跟着改成 transparent（那样一屏灰里就认不出选中态了）。\n   ⚠️ 2026-09-30 用户反馈：「悬停跟选中，最外层那个描边，我觉得也不需要了，还是有点影响」\n   ⇒ 原来那圈 .5px solid transparent（悬停 / 选中时才上色）**整条删掉**。\n   padding 各加 .5px 补回那条边框占掉的宽度，行的几何尺寸与改前逐像素一致\n   （所以下面这两条 padding 数字是有来历的，不是随手写的小数）。 */\n.knit-doc{display:grid;grid-template-columns:22px minmax(0,1fr);column-gap:8px;align-items:start;\n  padding:10.5px 11.5px;border-radius:10px;cursor:pointer;\n  background:transparent;\n  transition:background .18s,transform .18s,opacity .18s}\n.knit-doc:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03));transform:translateX(-2px)}\n/* 选中（正在预览）＝**只有灰底**（2026-09-30 用户裁决）。\n   ⚠️ 这条的上一版是「中性描边 + 灰底」（2026-09-29 裁决，用来取代更早的品牌色描边）。\n   用户这次的原话是「文档列表悬停跟选中，最外层那个描边，我觉得也不需要了」⇒\n   描边整条删掉，**选中态只剩灰底**。\n   ⚠️ 灰底是选中唯一的分层信号，**不许**跟着改成 transparent（一屏灰里就认不出选中了）。\n   ⚠️ hover 与选中的区别现在**只**是底色深浅（--knit-hover-bg / --knit-active-bg），\n   不再有任何一圈线。 */\n.knit-doc.active{background:var(--knit-active-bg,rgba(255,255,255,.085))}\n/* .knit-doc.cursor **故意不设样式**：键盘焦点靠「移动即预览」的预览面板表达，\n   再加描边会与 .active 的整块背景重复，显得突兀。\n   （曾经有一条 「.knit-multicol .knit-doc.cursor」 的中性环，是为多列网格补的 ——\n   多列没了，那条也删了。） */\n/* ── 列表进出动效的**静态**部分（v0.17，2026-10-03 用户要求）───────────────\n   补间本身在 JS 里用 WAAPI 跑（见 client.js 的 DocRow 与 MOTION_* 那段）—— 高度要按\n   量出来的自然高度补间，CSS 的 @keyframes 做不到（height:auto 不可插值）。这里只管两件事：\n   ① .leaving ＝正在离开的幽灵行：不吃指针事件、内容裁掉；\n   ② 系统开了「减弱动态效果」时，连底色过渡一起去掉（进出本来就不播）。 */\n.knit-doc.leaving{pointer-events:none;user-select:none;overflow:hidden}\n@media (prefers-reduced-motion: reduce){\n  .knit-doc{transition:none}\n  .knit-cov-dots,.knit-cov-dot{transition:none}\n  .knit-tier,.knit-tier.flash{transition:none}\n  .knit-cov-col,.knit-read-row,.knit-out-row,.knit-more-btn,.knit-glyph-mark{transition:none}\n}\n/* 行一＝**标题行**：Primary 点 + 标题 + 相对时间（**时间靠右**）。\n   2026-09-29 这一天里这一行改了三次：先是「序号 + 标题 + 时间」，然后\n   「时间跟那个置顶的序号可以一行」（序号留下、标题移出去），再后来\n   「序号放在独立最左边」（序号也出去、只剩点与时间）；最后用户要求\n   「将时间放到标题同行，时间放在右边，然后标题跟时间就可以以序号平行，居中平行」\n   ⇒ 标题**回到这一行**，时间从行尾滑到标题右边。\n   序号那一列与这一行**垂直居中**：靠 .knit-num 的 line-height 与标题行高对齐\n   （见下面 .knit-num 的说明 —— 两处必须同步改）。 */\n.knit-row1{display:flex;align-items:center;gap:8px;margin-bottom:5px}\n/* v0.14（Design §11 / §13）：**最左边独立一列**的序号（2026-09-29 用户追加要求）。\n   序号是「这个包里的第几篇」，不是分数；Primary 只给一个 5px 黑点 ——\n   不是星标、不是徽章、不是 AI 图标。「重要来自位置和结构，不来自图标」。\n   ⚠️ 深浅主题都要能看见：用文字色令牌，不写死 #242426（暗色下会消失）。\n   ⚠️ 没有序号的行**不渲染这个节点**；那一列由 .knit-doc 的 grid 轨道保着\n   （时间序 / 筛选结果 /「其他相关文档」照样和有条目的行左边缘对齐）。\n   ⚠️ line-height **19.6px 是把序号与标题第一行居中的唯一手段**：\n   它＝.knit-title 的 14px × 1.4。格的 align-items:start 让这一列从卡片顶边\n   开始排，所以只要这个行盒与标题行盒等高，两个字号不同的文本就自然居中。\n   **改 .knit-title 的字号或行高时，这里必须同步改**，否则序号会与标题错开。 */\n.knit-num,.knit-gapmark{grid-column:1;font-size:11px;line-height:19.6px;font-variant-numeric:tabular-nums;\n  color:var(--dsw-alias-label-caption,#80868b)}\n/* 中性占位标记（2026-10-01 用户反馈）：「其他相关文档」那一节没有序号，空着的那一格\n   被读成「漏了一个号」（原话：「没有序号以后左边就空了，视觉上比较割裂，就觉得是个 bug 一样」）。\n   没号的行就在同一列放一个最轻的 · —— 不冒充序号，也不让轨道断掉。\n   ⚠️ 只有**这一屏里有号**时才渲染（时间序 / 平铺列表整屏都没号 ⇒ 一个标记都没有：\n   一屏里要么都有、要么都没有；混着才是刺眼的原因）。\n   ⚠️ 几何与 .knit-num 共用同一条选择器 —— 这就是「改一处必须改另一处」的执行方式。 */\n/* 右边这一列＝其余全部数据（标题行 / 摘要 / 理由）。\n   ⚠️ min-width:0 不能省：轨道是 minmax(0,1fr)，但**单元格本身**默认也是按\n   min-content 撑的，不写它标题的省略号和摘要的两行截断就不生效（会把行撑宽）。 */\n.knit-body{grid-column:2;min-width:0}\n.knit-dot{flex:none;width:5px;height:5px;border-radius:50%;\n  background:var(--dsw-alias-label-primary,#0f1115)}\n/* 时间**在标题右边的行尾**（2026-09-29 用户要求「时间放在右边」）。\n   ⚠️ 这条推翻了同一天早先的写法（那时候时间跟在点后面左对齐，理由是\n   「元信息行读起来像一句话」）—— 时间现在和标题同一行，左对齐会把标题夹在中间。\n   靠 .knit-title 的 flex:1 1 auto 把时间挤到行尾；这里只要 flex:none 不被压扁。 */\n.knit-time{flex:none;font-size:11px;color:var(--dsw-alias-label-caption,#80868b)}\n/* 标题现在和 Primary 点、时间**同行**（见 .knit-row1 的说明；margin-bottom 移到了那一行）。\n   仍是单行省略 —— 列表是扫读用的，想看全标题就预览或打开；折行会让每条卡高度不一，\n   「移动到下一项」的位移就没法预期。\n   flex:1 1 auto + min-width:0 是**时间能被推到行尾、且长标题在时间之前省略**的前提：\n   去掉 min-width:0，标题会把整行撑宽（省略号失效）；去掉 flex-grow，时间会紧贴标题而不是靠右。 */\n.knit-title{flex:1 1 auto;min-width:0;font-weight:600;font-size:14px;line-height:1.4;\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.knit-sum{font-size:12px;line-height:18px;color:var(--dsw-alias-label-secondary,#9aa0a6);\n  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.knit-sum.empty{font-style:italic;color:var(--dsw-alias-label-caption,#80868b)}\n/* ── 列表行里为什么没有路径（2026-09-29） ────────────────────\n   这里曾经是「.knit-meta」（相对路径那一行）。用户否掉了它：\n   「文档列表中的文档路径，我觉得不需要出现了，因为点开查看文档详情的时候已经有了，\n   所以这里是重复的，隐藏掉」。\n   ⇒ **删掉，不是 display:none** —— 预览头的面包屑（.knit-preview-path）已经\n   始终显示完整路径，重复的那一份没有存在的理由。\n   ⚠️ 不要和「多列砍字段」那条教训混起来：**摘要（.knit-sum）仍然任何情况下都不许\n   display:none** —— 那条守的是「不许因为排版窄就静默少给信息」，而路径是**重复信息**。\n   ⚠️ 另：本文件整份 CSS 在一个模板串里，**注释里不能出现反引号**（会截断模板）——\n   这个教训在这里被踩到过一次（就是写上面这段注释的时候）。\n/* ── 曾经在这里的一段：2 列时的卡片 ─────────────────────────\n   它按「格子窄了」改排版（时间纵向排、标题折两行、摘要按格子宽让位、路径折两行），\n   并顺手把 :hover 的 translateX 关掉。\n   **2026-09-29 整段删除**：列表不再有第二列，这些规则一条也匹配不到。\n   删的时候**没有**把 「transform:none」 留下来 —— 上面的 「.knit-doc:hover」\n   仍然保留 「translateX(-2px)」（单列的悬停位移从来没被这些规则影响过）。 */\n.knit-msg{padding:24px 16px;text-align:center;font-size:12px;\n  color:var(--dsw-alias-label-caption,#80868b);line-height:1.7}\n.knit-notice{margin:6px 8px 0;padding:7px 10px;border-radius:7px;font-size:11px;line-height:1.5;\n  background:rgba(255,120,120,.12);border:.5px solid rgba(255,120,120,.3);color:#ffb4b4}\n.knit-badge{font-size:10px;margin-right:3px}\n/* v0.25 媒体收藏：★ 是**状态标记**，所以吃品牌色（与聚焦圈 / 分区「查看全部」同一档）；\n   只在**名字行里**占一个字形的位置，不上缩略图、不加底色、不做 hover —— 网格不许长出第二套 chrome。 */\n.knit-fav{font-size:10px;margin-right:3px;color:var(--knit-accent)}\n/* v0.25：对话里生成的图 —— 标记用**文字**（承担信息：还没存进项目、存进去就消失）。\n   字色取次级灰：它不是层级，是来源说明，不该抢过 ★。 */\n.knit-conv{font-size:10px;margin-right:3px;color:var(--dsw-alias-label-caption,#80868b)}\n/* v0.25 媒体档「悬停看大图」—— 与入口浮窗同一套外框（圆角 / 阴影 / 边框 / 层级）。\n   ⚠️ pointer-events:none 是必须的：它只是看一眼，绝不许挡住卡片的点击。\n   尺寸由 JS 下发（上限 800，按可用空间收缩），这里只负责「图在盒子里等比铺满」。 */\n.knit-shot{position:fixed;z-index:60;display:flex;align-items:center;justify-content:center;\n  padding:6px;border-radius:12px;pointer-events:none;\n  background:var(--dsw-alias-bg-layer-2,#2c2c2e);\n  border:.5px solid var(--dsw-alias-border-l4,rgba(255,255,255,.12));\n  box-shadow:0 12px 32px rgba(0,0,0,.32)}\n.knit-shot img{display:block;max-width:100%;max-height:100%;border-radius:8px;object-fit:contain}\n/* v0.25 媒体档「双击全屏」：整窗遮罩 + 毛玻璃。层级在悬停浮窗（60）与菜单之上。\n   左侧留 96px 给缩略图带（它绝对定位在遮罩里）；图片按 contain 铺满剩下的区域。 */\n.knit-lightbox{position:fixed;inset:0;z-index:2147483000;display:flex;align-items:center;justify-content:center;\n  padding:32px 32px 32px 96px;outline:none;cursor:zoom-out;\n  /* ⚠️ 遮罩的 α 是**人眼定的**（与 box-shadow 同一性质，推不出来）；两套值**必须不同**，\n     否则「随深色模式变化」就是假话（有守卫）。\n     ⚠️ 这两个变量故意**挂在查看器自己身上** —— 它被 portal 到 document.body 之后\n     不在 .knit-root 里了，读不到那层的变量（第一版就是这么静默变成透明遮罩的）。 */\n  --knit-scrim:rgba(255,255,255,.62);\n  background:var(--knit-scrim);backdrop-filter:blur(22px) saturate(1.1);\n  -webkit-backdrop-filter:blur(22px) saturate(1.1)}\nbody[data-ds-dark-theme] .knit-lightbox{--knit-scrim:rgba(18,18,20,.72)}\n.knit-lightbox-stage{flex:1 1 auto;min-width:0;min-height:0;display:flex;align-items:center;\n  justify-content:center;cursor:default}\n.knit-lightbox-img{max-width:100%;max-height:100%;object-fit:contain;border-radius:10px;cursor:default;\n  box-shadow:0 24px 64px rgba(0,0,0,.36);background:var(--dsw-alias-bg-base,#fff)}\n.knit-lightbox-tools{position:absolute;top:18px;right:62px;display:flex;align-items:center;gap:6px}\n.knit-lightbox-close{position:absolute;top:18px;right:18px;width:34px;height:34px;padding:0;\n  display:flex;align-items:center;justify-content:center;border:0;border-radius:10px;\n  cursor:pointer;font-family:inherit;font-size:15px;line-height:1;\n  color:var(--dsw-alias-label-primary,#0f1115);background:transparent;opacity:.7}\n.knit-lightbox-close:hover{opacity:1;background:var(--knit-hover-bg,transparent)}\n.knit-lightbox-rail{position:absolute;left:10px;top:50%;transform:translateY(-50%);display:flex;\n  flex-direction:column;gap:6px;max-height:88vh;overflow-y:auto;padding:4px;cursor:default}\n.knit-lightbox-thumb{flex:none;width:64px;height:64px;padding:0;border:0;border-radius:8px;overflow:hidden;\n  cursor:pointer;background:transparent;opacity:.68;transition:opacity .16s ease}\n.knit-lightbox-thumb img{width:100%;height:100%;object-fit:cover;display:block}\n.knit-lightbox-thumb:hover{opacity:1}\n.knit-lightbox-thumb.active{opacity:1;box-shadow:0 0 0 2px var(--knit-accent,var(--dsw-alias-brand-primary-new-colorprimary-new-color))}\n@media (prefers-reduced-motion: reduce){.knit-lightbox-thumb{transition:none}}\n\n/* ── 列表下方的预览面板 ───────────────────────────────\n   要让人一眼看出「这是另一层，不是列表的续行」，靠**结构**而不是底色：\n   ① 顶部圆角 + 更强的上边界；② 一层向上的柔影。\n   ⚠️ 底色**不再**参与分层（2026-09-20 起一律是纯阅读底色），理由见下面那条注释。\n   ⚠️ 也不要再拿 bg-layer-2 来做层级：浅色主题下 bg-layer-1/2/3 解析出来全是 #fff，\n      换过去等于没换（实测官方 theme 变量）。 */\n/* 预览面板的底色：**一律用纯阅读底色**（浅 #fff / 深 #151517）。\n   曾经是「先分层灰、用户一滚正文才过渡到白」，用户 2026-09-20 否掉了：\n   「下拉出现详情时背景是灰的，这个交互比较差……把它改成整个都是白」。\n   分层不靠底色了 —— 靠上边界 + 顶部圆角 + 向上柔影（下面三件仍然都在）。\n   ⚠️ 别只看浅色主题：这里必须走 bg-base，深色下它是 #151517；\n   写死 #fff 会在暗色主题里白得刺眼。 */\n.knit-preview{position:relative;flex:none;display:flex;flex-direction:column;min-height:0;\n  border-top:.5px solid var(--dsw-alias-border-l3,rgba(255,255,255,.14));\n  border-top-left-radius:12px;border-top-right-radius:12px;\n  background:var(--dsw-alias-bg-base,#fff);\n  box-shadow:0 -8px 24px rgba(0,0,0,.06)}\nbody[data-ds-dark-theme] .knit-preview{box-shadow:0 -8px 24px rgba(0,0,0,.38)}\n/* 拖拽把手：**绝对定位、不占布局高度**。\n   它原来是一条 11px 的普通 flex 行，把 38px 的头整体往下推 —— 用户看到的就是\n   「文档名和那几个按钮偏下」。改成浮在头顶的窄条后，头里的内容才真正上下居中。\n   高度取 6px：头里的按钮高 24px、在 37.5px 内容区里居中 → 顶边在 6.75px，\n   所以 6px 的把手**不会盖住按钮**（盖住会吃掉点击）。 */\n.knit-resize{position:absolute;top:0;left:0;right:0;height:6px;z-index:2;\n  cursor:ns-resize;background:transparent;\n  display:flex;align-items:center;justify-content:center}\n.knit-resize::after{content:'';width:44px;height:3px;border-radius:2px;\n  background:var(--dsw-alias-border-l3,rgba(255,255,255,.2));transition:background .15s,width .15s}\n.knit-resize:hover::after{background:var(--knit-accent);width:64px}\n/* 头对齐官方文档预览面板（.dhJKeW_header）：38px 高，\n   里面放路径面包屑而不是标题 —— 正文 H1 已经写了标题，重复只添乱。\n   ⚠️ 2026-09-30 用户裁决：官方那条 border-l3 底边**不要** ——\n   「查看文档详情被引用，上下那两条横线，细细的横线，我觉得也不需要的」。\n   头部与引用条 / 正文之间现在只靠留白分层（配合 .knit-links 同时去掉的那条）。 */\n.knit-preview-head{box-sizing:border-box;display:flex;align-items:center;gap:4px;\n  height:38px;padding:0 6px 0 12px;flex:none}\n/* 路径：**可点** —— 用系统默认应用打开这篇本地文档（阅读时多一个入口）。\n   目录一律不展开，只留一个「…/」占位（2026-10-01 用户要求：「前面那一串都用三个点点点表示」，\n   头部宽度让给文件名）；文件名不收缩。**完整相对路径不丢** —— 在 .knit-preview-path 的悬停提示里。\n   ⚠️ 本段在 CSS 那一个大模板串里：注释里**不能出现反引号**（写 .knit-preview-path 这种\n   带反引号的类名会把模板提前截断，客户端半边整个加载失败 —— 2026-10-01 又踩一次）。 */\n.knit-preview-path{flex:1 1 auto;min-width:0;display:flex;align-items:center;\n  margin-right:6px;font-size:12px;white-space:nowrap;overflow:hidden;\n  background:transparent;border:none;padding:0;font-family:inherit;text-align:left;\n  color:inherit;cursor:pointer}\n.knit-preview-path:disabled{cursor:default}\n.knit-preview-path:hover:not(:disabled) .knit-preview-name{text-decoration:underline}\n.knit-preview-dir{flex:0 0 auto;color:var(--dsw-alias-label-tertiary,rgba(255,255,255,.4))}\n.knit-preview-name{flex:0 0 auto;color:var(--dsw-alias-label-primary,#e8eaed)}\n/* 正文区把滚动条提到 l2 —— 与官方文档预览面板同一档（那边的 .body 也覆盖这两个变量）。\n   不重写 ::-webkit-scrollbar，只覆盖变量，所以宽度/圆角/悬停都跟 DSH 完全一致。 */\n.knit-preview-body{--dsh-scrollbar-thumb:var(--dsw-alias-scrollbar-bg-l2);\n  --dsh-scrollbar-thumb-hover:var(--dsw-alias-scrollbar-hover-l2);\n  flex:1;min-height:0;overflow-y:auto;padding:10px 14px 16px;font-size:12.5px}\n.knit-preview-close{flex:none;width:24px;height:24px;border-radius:6px;cursor:pointer;\n  display:inline-flex;align-items:center;justify-content:center;font-size:13px;\n  background:transparent;border:none;color:var(--dsw-alias-label-secondary,#9aa0a6)}\n.knit-preview-close:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03));\n  color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-raw{margin:0;white-space:pre-wrap;word-break:break-word;font-size:11.5px;line-height:1.6;\n  color:var(--dsw-alias-label-secondary,#9aa0a6);font-family:ui-monospace,SFMono-Regular,Menlo,monospace}\n.knit-preview-note{font-size:11px;color:var(--dsw-alias-label-caption,#80868b);padding:2px 0 8px}\n\n/* v0.19：代码行的语言徽章（TS / JS / PY …）。\n   刻意**不是**一个胶囊：没有底色、没有边框、没有圆角 —— 它是一条弱注释，\n   不是标签墙。字号比标题小两档，颜色用 caption，永远不抢标题。\n   窄侧边栏里它 flex:none，压缩的是标题（.knit-title 会省略号收尾）而不是它。 */\n.knit-lang{flex:none;margin-left:6px;font-size:10px;letter-spacing:.04em;\n  text-transform:uppercase;color:var(--dsw-alias-label-caption,#80868b)}\n\n/* ── 代码预览（v0.19）────────────────────────────────────\n   轻量：行号栏 + 代码正文。**不做语法高亮、不做折叠、不做 minimap**，\n   也没引入 Monaco / CodeMirror —— Knit 不是编辑器（需求 §8 §25）。\n   横向滚动只发生在正文那一格（overflow-x:auto + min-width:0），\n   行号栏 flex:none 留在左边；纵向滚动仍由外面的 .knit-preview-body 负责，\n   所以这里**不开第二个纵向滚动容器**（两个纵向滚动条会互相打架）。 */\n.knit-codepane{position:relative;display:flex;align-items:stretch;min-height:100%;\n  font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11.5px;line-height:1.6}\n/* v0.20 命中区域（需求 §13）：一层**中性灰**横带（不是品牌色、不是荧光笔 —— §6.3\n   「用灰阶建立层级」）。绝对定位在代码正文之上、pointer-events:none ⇒ 它不参与\n   点击、不参与选中、也不改 DOM 结构（正文仍是**一个**文本节点）。 */\n/* v0.20 命中段的高亮横带。2026-10-07 用户裁决：**再浅一半**（原话「背景太深了，\n   再减少一半的，这样就让它显点，不用这么明显」）—— 用 opacity:.5 而不是换一个更浅的\n   写死色：令牌仍然是同一个中性灰（.knit-doc.active 那块），两个主题自动一致，\n   而且不引入新的 --knit-* 变量。 */\n.knit-code-hit{position:absolute;left:0;right:0;pointer-events:none;z-index:0;opacity:.5;\n  background:var(--knit-active-bg,rgba(255,255,255,.085))}\n/* v0.20：Markdown 预览跳到命中段之后，那一块**短暂**亮一下（2026-10-07 用户裁决：\n   「文档这边也参考代码块一样……要指定到段落」）。与代码那边是同一个意思、同一档灰，\n   只是形状不同：代码是一整条横带，Markdown 只能是「命中的那个块」。\n   ⚠️ transition 写在**基础选择器**上（不是 .knit-doc-hit 上）：写进 hit 类的话，\n   类一移除 transition 也跟着没了 —— 背景会「啪」地消失（Coverage 那层踩过同一个坑）。\n   ⚠️ 时长必须 == FLASH_MS（1200），否则会出现「高亮已取消但底色还在慢慢褪」的错帧。\n   这一块**不画边框、不位移、不留状态**，也不进任何列表数据。 */\n.knit-md-body :is(p,li,h1,h2,h3,h4,h5,h6,pre,blockquote,table,td,th,dt,dd,summary,figcaption){\n  transition:background 1.2s ease;border-radius:6px}\n.knit-md-body .knit-doc-hit{background:var(--knit-active-bg,rgba(38,49,72,.061))}\n/* ⚠️ 文字必须在横带**之上**：横带是定位元素（z-index:0），会盖住静态兄弟节点。\n   所以 position:relative;z-index:1 写进下面两条既有规则里 —— **不新增选择器**：\n   test/client.test.mjs 用 .knit-code-src\\\\{([^}]*)\\\\} 抓这两条规则，多一条同后缀的\n   规则会让它抓到错的那条（真的踩过：守卫报的是 z-index 里没有 overflow-x）。 */\n.knit-code-gutter{flex:none;white-space:pre;text-align:right;user-select:none;\n  position:relative;z-index:1;\n  padding:0 8px 0 2px;color:var(--dsw-alias-label-caption,#80868b);\n  border-right:1px solid var(--dsw-alias-border-l3,rgba(255,255,255,.08))}\n.knit-code-src{flex:1 1 auto;min-width:0;margin:0;padding:0 0 0 10px;\n  position:relative;z-index:1;\n  white-space:pre;overflow-x:auto;color:var(--dsw-alias-label-primary,#e8eaed)}\n\n/* ── 引用条（v0.12）────────────────────────────────────\n   夹在预览头与正文之间的一层。全用中性令牌：它是「信息」，不是「操作」。\n   ⚠️ 2026-09-30 用户裁决：它自己那条 border-l2 底边**删掉** —— 与预览头的底边\n   一上一下两条细线把这一小块夹成了独立一截，用户的原话是「有点割裂」。\n   现在这一层不画任何横线，收紧的 padding 就是它的边界。\n   注意 CSS 里不要写反引号 —— 这段样式是模板字符串，一个反引号就会把它截断。 */\n/* v0.25 查找条：与 .knit-links 同一层（夹在头与正文之间，**不参与正文滚动**）。\n   输入框直接复用工具栏那套（.knit-searchwrap + .knit-filter）—— 同一份视觉语言，不新造控件；\n   这里只把它的最大宽度放开（查找条要占满一行）。\n   ⚠️ 注意：本段注释里不许出现反引号 —— 整个 CSS 在一个模板串里。 */\n.knit-findbar{flex:none;display:flex;align-items:center;gap:6px;padding:4px 12px 6px}\n.knit-findbar .knit-searchwrap{flex:1 1 auto;max-width:none}\n.knit-findcount{flex:none;font-size:11px;color:var(--dsw-alias-label-caption,#80868b);\n  font-variant-numeric:tabular-nums}\n.knit-findnav{flex:none;width:22px;height:22px;border-radius:6px;cursor:pointer;\n  display:inline-flex;align-items:center;justify-content:center;font-size:12px;\n  background:transparent;border:none;color:var(--dsw-alias-label-secondary,#9aa0a6)}\n.knit-findnav:hover:not(:disabled){background:var(--knit-hover-bg,rgba(255,255,255,.03));\n  color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-findnav:disabled{opacity:.4;cursor:default}\n/* 命中的样式 —— **只有底色**。没有 padding、没有 border、颜色继承 —— 一有内边距就会改变行高与折行，\n   而代码预览的命中横带是按「滚动高度 ÷ 行数」算行高的，动了就会错位。\n   两级灰阶建立层级（普通命中 = hover 那档，当前命中 = 命中段那档），不引入第二种颜色。 */\nmark.knit-find{background:var(--knit-hover-bg,rgba(255,255,255,.03));color:inherit;\n  padding:0;border:0;border-radius:2px}\nmark.knit-find-current{background:var(--knit-chip-bg)}\n.knit-links{flex:none;font-size:11px;color:var(--dsw-alias-label-secondary,#9aa0a6)}\n.knit-links-state{padding:5px 12px;color:var(--dsw-alias-label-caption,#80868b)}\n.knit-links-head{box-sizing:border-box;display:flex;align-items:center;gap:6px;width:100%;\n  padding:5px 12px;background:transparent;border:none;cursor:pointer;text-align:left;\n  font:inherit;color:inherit}\n.knit-links-head:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03))}\n.knit-links-arrow{flex:none;width:10px;font-size:9px;opacity:.75}\n.knit-links-summary{flex:1 1 auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.knit-links-note{padding:2px 12px 6px;color:var(--dsw-alias-label-caption,#80868b)}\n.knit-links-body{padding:0 12px 8px;max-height:180px;overflow:auto}\n.knit-links-group + .knit-links-group{margin-top:6px}\n.knit-links-label{font-weight:600;color:var(--dsw-alias-label-caption,#80868b);margin-bottom:2px}\n.knit-links-empty{color:var(--dsw-alias-label-caption,#80868b);padding:1px 0}\n.knit-links-list{list-style:none;margin:0;padding:0}\n.knit-link-row{box-sizing:border-box;display:block;width:100%;text-align:left;padding:2px 4px;\n  border:none;background:transparent;border-radius:4px;cursor:pointer;font:inherit;color:inherit}\n.knit-link-row:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03))}\n.knit-link-name{display:block;color:var(--dsw-alias-label-primary,#e8eaed);\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.knit-link-path{display:block;font-size:10px;color:var(--dsw-alias-label-caption,#80868b);\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n\n/* ── 类型切换（文档 / 图片与视频 / 全部）────────────── */\n/* v0.14（Design §20）：**不再是三个并排的灰底按钮**，改成下划线式页签 ——\n   选中的那个用「深色文字 + 2px 深色下划线」表达。\n   ⚠️ 2026-09-29 用户裁决：这条**覆盖**了早先那条「选中填充背景灰就可以」。\n   当时用户的原话是「选中的时候不用加绿色、蓝色的描边，就跟下面列表一样」——\n   诉求是「别用品牌色描边」；现在连灰底也不要了，层级交给下划线，\n   依然不许出现 --knit-accent / --knit-accent-fill（Design §8：灰阶分层）。\n   ⚠️ 2026-09-30 用户反馈：页签条底下原本还有一条全宽 hairline（border-l1）——\n   「最细最淡那条横线」与下面的列表割裂，**删掉**。层级现在只由选中项自己那条\n   2px 下划线表达，页签条本身不画线（也不是「下划线悬空」：它画在自己的文字下面）。\n   ⚠️ 排序切换（.knit-seg-btn，Design §18）是**另一个控件**，它保持灰底不变。\n   ⚠️ 2026-10-09（v0.21.x 用户规格）：这一组从**自己一行**搬进了 .knit-bar，排在排序组\n   右边（2026-10-12 起中间**没有竖线了** —— 靠 .knit-bar 的 gap 分开）。于是这里**不再自带左右 12px 内边距**（那是\n   .knit-bar 的事，再写一遍就是双重缩进、两组对不齐）。下划线式选中态**保持不变** ——\n   用户这次说「选中项用浅色背景或文字强调即可」，下划线 + 主色文字正是「文字强调」，\n   而且它覆盖 2026-09-29 那条「不要灰底」的裁决，不要因为并排就退回灰底按钮。 */\n.knit-types{display:flex;gap:14px;flex:none}\n.knit-type-btn{flex:none;height:30px;padding:0;cursor:pointer;\n  border:none;border-bottom:2px solid transparent;background:transparent;\n  color:var(--dsw-alias-label-secondary,#9aa0a6);font-family:inherit;font-size:14px;\n  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\n  transition:color .15s,border-color .15s}\n.knit-type-btn:hover{color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-type-btn.active{color:var(--dsw-alias-label-primary,#e8eaed);font-weight:600;\n  border-bottom-color:var(--dsw-alias-label-primary,#e8eaed)}\n\n/* ── 图片与视频：方形缩略图网格 ─────────────────────\n   **列数由浏览器自己数**（用户 2026-09-20 点名的机制，取自 AIGC 资产中心的图片网格）：\n   auto-fill + 固定下限 104px —— 面板拖宽约 120px 就多出一列，格子大小基本不变。\n\n   ⚠️ **1fr 是有意写的，不要改成固定轨道**。第一版把上下限都写成 JS 算的「实际格宽」，\n   结果列数被**条目数**锁死（条目 >8 个就把格宽压到 64px）：实测 400→1200px 全是 5 列，\n   只有格子从 64px 被吹到 224px —— 用户的原话是「它不是真的响应式」。\n   改成 minmax(104px, 1fr) 后列数只跟**可用宽度**有关，与有几个媒体无关。\n\n   ⚠️ 但**下限也不能省**：只写 1fr 会让只有一个媒体时那张图撑满整个面板宽度。\n\n   ⚠️ **网格不许设 maxHeight、也不自己滚动**。前两版把高度封在「两行」并给网格加\n   overflow-y:auto，真机上第三行只能露出一点点（用户原话：「本来有三行，结果第三行\n   只显示了一点点，应该纵向也完整显示」）—— 封顶高度是按「两行」算死的，与面板实际多高无关，\n   必然截断。现在有多少行就铺多少行，纵向滚动统一交给 .knit-list（与资产中心一致）。\n\n   fallback 那一行（3 列）是给不认 minmax(变量) 的旧内核用的，必须写在前面。\n   --knit-media-cell 由 JS 按当前列数下发，只用于 height 的方形兜底。\n   ⚠️ 注释里不要出现反引号 —— 这段是模板字符串，反引号会把它提前截断（见 AGENTS §6.9）。 */\n.knit-media-grid{display:grid;gap:${MEDIA_GAP_PX}px;\n  --knit-media-label:block;\n  --knit-media-track:${MEDIA_TRACK_PX}px;\n  --knit-media-cell:120px;\n  grid-template-columns:repeat(3,1fr);\n  grid-template-columns:repeat(auto-fill,minmax(var(--knit-media-track,104px),1fr));\n  padding:8px 12px 16px;align-content:start;min-height:0}\n/* 分区里的网格：不留内边距。滚动一律交给 .knit-list，网格自己**不滚** ——\n   嵌套滚动会在「全部」里变成滚动陷阱，而且封顶高度必然截断最后一行。 */\n.knit-media-card{min-width:0;cursor:pointer;border-radius:10px}\n.knit-media-thumbbox{position:relative;width:100%;height:var(--knit-media-cell,auto);aspect-ratio:1/1;\n  border-radius:9px;overflow:hidden;\n  background:var(--dsw-alias-interactive-bg-hover,rgba(255,255,255,.06));\n  border:.5px solid var(--dsw-alias-border-l2,rgba(255,255,255,.1));\n  transition:border-color .15s,box-shadow .15s}\n.knit-media-card:hover .knit-media-thumbbox{border-color:var(--dsw-alias-border-l4,rgba(255,255,255,.22))}\n/* 键盘移动 → 只有中性描边。必须排在 .active 之前：键盘光标默认常驻第一项，\n   若排在后面会把「正在预览」的品牌色描边盖成灰色，点第一张图就看不到选中态。 */\n.knit-media-card.cursor .knit-media-thumbbox{\n  border-color:var(--dsw-alias-border-l4,rgba(255,255,255,.22));\n  box-shadow:0 0 0 1.5px var(--dsw-alias-interactive-bg-active,rgba(255,255,255,.1))}\n/* 正在预览 → 品牌色描边（排在 cursor 之后，确保同时命中时以「选中」为准） */\n.knit-media-card.active .knit-media-thumbbox{\n  border-color:var(--knit-accent);box-shadow:0 0 0 1.5px var(--knit-accent)}\n/* 格子窄到 96px 以下时，文件名与时间会挤成一团 —— 整块让位给缩略图（mediaLayoutFor 的 scaled） */\n.knit-media-meta{margin-top:5px;display:var(--knit-media-label,block)}\n.knit-media-name{display:flex;align-items:center;gap:3px;font-size:11.5px;line-height:1.3;\n  color:var(--dsw-alias-label-primary,#e8eaed);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.knit-media-time{margin-top:1px;padding:0 1px;font-size:10px;color:var(--dsw-alias-label-caption,#80868b)}\n\n/* ── 缩略图本体（图片 / 视频首帧 + 播放三角 + 时长）── */\n.knit-thumb{position:absolute;inset:0}\n.knit-thumb img,.knit-thumb video{width:100%;height:100%;object-fit:cover;display:block;background:#000}\n.knit-thumb-play{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;\n  color:#fff;pointer-events:none}\n.knit-thumb-play svg{width:32%;height:32%;fill:currentColor;opacity:.95;\n  filter:drop-shadow(0 1px 4px rgba(0,0,0,.65))}\n.knit-thumb-dur{position:absolute;right:5px;bottom:5px;padding:1px 5px;border-radius:5px;\n  background:rgba(0,0,0,.7);color:#fff;font-size:10px;line-height:1.5;font-variant-numeric:tabular-nums;\n  pointer-events:none}\n\n/* ── 预览面板里的图片 / 视频 ───────────────────────── */\n.knit-preview-body.is-media{display:flex;align-items:center;justify-content:center;\n  padding:12px;background:rgba(0,0,0,.22)}\n.knit-preview-media{max-width:100%;max-height:100%;object-fit:contain;border-radius:6px}\nvideo.knit-preview-media{width:100%;background:#000}\n\n/* Knit 图标：走 DSH 的**主文本色令牌**（浅 #0f1115 / 暗 #f9fafb），\n   不写死 #000 / #fff —— 令牌自己随主题切，所以**不需要**一条暗色覆盖规则。\n   ⚠️ 2026-10-07：暗色那一版原来是写死的 #fff，比 DSH 自己的主文本色还亮\n   （官方暗色 #f9fafb），属于「自己创造一套」，已删。 */\n.knit-icon{color:var(--dsw-alias-label-primary,#0f1115)}\n\n/* 入口按钮：挂在会话头部右侧与输入框工具行两处 list 座位上 */\n/* 悬停偷看浮层：自己画的，不碰框架（所以不会推开右侧栏） */\n.knit-peek-anchor{display:inline-flex;position:relative}\n.knit-peek{position:fixed;z-index:60;display:flex;flex-direction:column;max-height:60vh;\n  padding:5px;border-radius:12px;box-shadow:0 12px 32px rgba(0,0,0,.32);\n  background:var(--dsw-alias-bg-layer-2,#2c2c2e);\n  border:.5px solid var(--dsw-alias-border-l4,rgba(255,255,255,.12));\n  color:var(--dsw-alias-label-primary,#e8eaed)}\n.knit-peek-head{display:flex;align-items:center;gap:7px;padding:5px 7px 7px;\n  font-size:11px;color:var(--dsw-alias-label-caption,#80868b)}\n.knit-peek-list{display:flex;flex-direction:column;gap:1px;min-height:0;overflow-y:auto}\n.knit-peek-doc{display:flex;align-items:baseline;gap:8px;width:100%;padding:7px 8px;\n  border:none;border-radius:8px;cursor:pointer;text-align:left;font-family:inherit;\n  background:transparent;color:inherit}\n.knit-peek-doc:hover{background:var(--dsw-alias-interactive-bg-hover,rgba(255,255,255,.08))}\n.knit-peek-name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}\n.knit-peek-time{flex:none;font-size:10.5px;color:var(--dsw-alias-label-caption,#80868b)}\n.knit-peek .knit-peek-hint{padding:7px;font-size:10.5px;\n  color:var(--dsw-alias-label-caption,#80868b)}\n\n.knit-entry{display:inline-flex;align-items:center;justify-content:center;flex:none;\n  width:28px;height:28px;padding:0;border:none;border-radius:8px;cursor:pointer;\n  background:transparent;color:var(--dsw-alias-label-secondary,#9aa0a6);\n  transition:background .15s}\n.knit-entry:hover{background:var(--knit-hover-bg,rgba(255,255,255,.03))}\n.knit-entry:active{transform:scale(.94)}\n\n/* 全屏阅读：藏掉头部与列表，只留预览 */\n.knit-root.fullscreen .knit-head,\n.knit-root.fullscreen .knit-bar,\n.knit-root.fullscreen .knit-types,\n.knit-root.fullscreen .knit-list{display:none}\n/* v0.19 修补（2026-10-07 用户反馈）：**使用情况也是列表上方的观察层**，全屏时同样让位。\n   这条规则漏了它 ⇒ 开着「使用情况」再点全屏，Lens 仍占掉面板上方约三分之一，\n   预览被挤在下面 —— 看起来就像「全屏没生效」。它是 flex:none 的自然高度，\n   不是浮层，所以必须显式 display:none，光靠预览 flex:1 抢不回来。 */\n.knit-root.fullscreen .knit-usage{display:none}\n/* 全屏时预览铺满整个面板：圆角与向上柔影是「浮在列表上」的隐喻，这里没有列表，去掉 */\n.knit-root.fullscreen .knit-preview{flex:1 1 auto;max-height:none;\n  border-top:none;border-radius:0;box-shadow:none}\n`\n\n\n    /**\n     * 把样式表插进文档一次。\n     * @returns {void}\n     */\n    function ensureStyle() {\n      if (typeof document === 'undefined') return\n      if (document.getElementById(STYLE_ID)) return\n      const el = document.createElement('style')\n      el.id = STYLE_ID\n      el.textContent = CSS\n      document.head.appendChild(el)\n    }\n\n    /* ── 用户偏好 ───────────────────────────────────── */\n\n    /**\n     * 读一个 localStorage 偏好。\n     * @param {string} key - 键\n     * @returns {string|null} 值\n     */\n    function readPref(key) {\n      try {\n        return window.localStorage.getItem(key)\n      } catch {\n        return null\n      }\n    }\n\n    /**\n     * 写一个 localStorage 偏好。\n     * @param {string} key - 键\n     * @param {string} value - 值\n     * @returns {void}\n     */\n    function writePref(key, value) {\n      try { window.localStorage.setItem(key, value) } catch { /* 隐私模式忽略 */ }\n    }\n\n    /**\n     * 读用户上次选的排序方式。\n     * @returns {'relevance'|'time'} 排序方式\n     */\n    function readSortPref() {\n      return readPref(SORT_KEY) === 'time' ? 'time' : 'relevance'\n    }\n\n    /**\n     * 读上次选择的列表类型，非法值回落到 doc